window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_050"]={"n":"黄佐","dyn":"明","poems":[{"t":"铙歌鼓吹曲二十二首 朱鹭一章十一句 其一","f":"古风","c":["朱鹭，姚以般。","从以孔盖，车班班。","北至榆林，南逾淮之水，驾之日千里。","鹭飞得飞止，茄下游鱼赪其尾。","皇帝饮酒，恺乐寿无极。"]},{"t":"铙歌鼓吹曲二十二首 思悲翁一章十句 其二","f":"古风","c":["思悲翁，枭子雄。","美人梦翁也，从天以来下。","悲翁之来，神灵雨。","子朝以飞，暮何于处。","猗嗟嗟，松柏萧萧泰陵树。"]},{"t":"铙歌鼓吹曲二十二首 上之回一章十四句 其四","f":"古风","c":["上之回，大驱马。","汗沾野草，百里赭。","行以北，美人从，不驾舍。","行以南，美人泣，不旋驾。","左平虏，右写奕。","豫章率服，威武谁与敌。"]},{"t":"铙歌鼓吹曲二十二首 拥离一章七句 其五","f":"古风","c":["拥离在朱巷。","珂马避之谁者往。","前有宫殿詄荡荡。","箭火飞，从天门。","道傍讴者野游盘。","万年行乐谁不欢。"]},{"t":"铙歌鼓吹曲二十二首 战城南一章十二句 其六","f":"古风","c":["战城南，分战疆。","运握奇，陈八方。","铠甲纷员衷土黄。","龙江之水洪汤汤。","马得饮之，人不敢尝。","馘囚乡晨解其缚。","犒以钱刀，暮用为乐。","愿为忠臣死报国。"]},{"t":"铙歌鼓吹曲二十二首 巫山高一章十三句 其七","f":"古风","c":["巫山高，高若何。","淮水绕之，不可以过。","䯀骢文马锦障泥。","我欲渡之，徘徊而骄嘶。","阳台有女居迷楼。","爱而不见烟云愁。","胄有虮虱，户有蛜蝛。","嗟我行役，今还归。"]},{"t":"铙歌鼓吹曲二十二首 上陵一章十三句 其八","f":"古风","c":["上陵以游遨。","下津驻旌旄。","问君从何来，来从朔方渡淮濠。","軨猎为君车，驾以赭白马。","鼓声琅琅漏初下。","手格飞禽血四洒。","户寐而讹绝行者。","宫监盱骇走且僵。","玉盘荐食君莫尝。","当天鸣镝射兔獐。","须臾白日出东方。"]},{"t":"铙歌鼓吹曲二十二首 将进酒一章七句 其九","f":"古风","c":["将进酒，君莫辞。","何以侑之虎拨思。","荐嘉肴，陈雅诗。","群桀既剪江无螭。","时迈其德隆天基。"]},{"t":"铙歌鼓吹曲二十二首 君马黄一章十一句 其十","f":"古风","c":["君马黄，臣马玄。","狭斜相逢不敢前。","黄马驰，玄马逐。","后喷沙，前喷玉。","副以江许翼两张。","翩翩倏如流电光。","周有穆满今圣皇。","君臣布德周万方。"]},{"t":"铙歌鼓吹曲二十二首 芳树一章八句 其十一","f":"古风","c":["芳树生兰池，华叶何芬敷。","鸾凤去之栖者乌。","唶我西秦氏，家有荡子焉为夫。","乌乳且哺生有雏。","嗟嗟蹇尔胡乃无。","帝何尔惜金仆姑。"]},{"t":"铙歌鼓吹曲二十二首 有所思一章十三句 其十二","f":"古风","c":["有所思，思我母慈。","身上锦裲裆，母身清宁寿以眉。","日夜要襋之，于今化为缁。","嗟我乃多携离。","水流东海归何时。","嗟我会面安可知。","晨鸡鸣，鸣不已。","东方明星光动地。","照我驱驰走千里。"]},{"t":"铙歌鼓吹曲二十二首 雉子班一章十五句 其十三","f":"古风","c":["雉子班，行可思。","雄求山梁雌从之。","羽短何繇飞。","流宕原泽中，雉子雊以遨。","翁孺知之，思美其膏。","白龙化鱼，罹彼豫且。","视子所止，乃非丘隅。","谓之载之我有车。","雉子去，我将安所如。"]},{"t":"铙歌鼓吹曲二十二首 圣人出一章十句 其十四","f":"古风","c":["圣人出，龙翩翩。","美人出，以管弦。","千旌万骑雄哉纷。","四家从以部领军。","舞剑浮白觞，我镇国。","陈秘戏，乐复乐。"]},{"t":"铙歌鼓吹曲二十二首 上邪一章六句 其十五","f":"古风","c":["上邪，下狭山童不可猎。","射鼋向江江水竭。","愿皇垂拱开明堂。","铺仁获政和阴阳。","千秋万岁长乐康。"]},{"t":"铙歌鼓吹曲二十二首 临高台一章九句 其十六","f":"古风","c":["临高台，望泗与淮。","言采其芑于水涯。","谁其殖之感我怀。","奋戎东南逖以北。","无以逸欲临万国。","生民何依依我德。","皇祖在天，敬哉有赫。"]},{"t":"铙歌鼓吹曲二十二首 远如期一章十句 其十七","f":"古风","c":["远如期，驾马以出门，咫步不可知。","林有虺，水有蜮，短狐封狼，肉人以为糜。","万里吁可悲。","有杕之杜乔其枝。","皇人寿谷今旋师。"]},{"t":"铙歌鼓吹曲二十二首 石流一章九句 其十八","f":"古风","c":["石流江怒，乌龙万斛，不可以渡。","江怒石流，万斛乌龙，不可以浮。","神怪隳突卫皇跸。","皇潜以跃跃复出。","于万斯年保贞吉。"]},{"t":"铙歌鼓吹曲二十二首 唐尧一章七句 其十九","f":"古风","c":["务成昭，惟唐尧。","钦明秉德群后朝。","建礼缦缦歌庆霄。","屈轶在廷礼不彫。","茅茨土阶以逍遥。","望云就日谁敢骄。"]},{"t":"铙歌鼓吹曲二十二首 玄云一章七句 其二十","f":"古风","c":["玄云油油，北风肃肃。","震电晔晔拔大木。","雪雹须臾及牛腹。","驱车随銮走折轴。","关弓射天中鸿鹄。","酌金叵罗奏蕃曲。"]},{"t":"铙歌鼓吹曲二十二首 伯益一章十句 其二十一","f":"古风","c":["伯益虞有虞。","智周百物，禽用三驱。","无为而治永终誉。","皇帝孔武徒手搏彫虎。","去其爪以蹲俯。","腓皇于后寔率舞。","荷皇之勇骇万人。","山川宁，鸟兽驯。"]},{"t":"铙歌鼓吹曲二十二首 钓竿一章九句 其二十二","f":"古风","c":["钓竿何珊珊，不如罟网贤。","鰋鲤何筛筛，不如鲔与鳣。","网罟一举获者千。","彼鲔与鳣潜深渊。","嗟鳣与鲔终弃捐。","金瓢进御烹小鲜。","兜离欢呼寿万年。"]},{"t":"咏志二十首 其一","f":"五言古诗","c":["栖迟衡门下，向夕绝来鞅。","轻风荡微月，玄景振清响。","游心观物化，閒庭恣偃仰。","苍蝇以翼鸣，营营在蛛网。","鸿雁随阳飞，一览八纮广。"]},{"t":"咏志二十首 其二","f":"五言律诗","c":["朱火照玄夜，耿耿怀平生。","云汉经中天，为章竟何成。","潇潇风雨歇，引领晨鸡鸣。","褰帷纳素月，悠然钟我情。"]},{"t":"咏志二十首 其九","f":"五言律诗","c":["大道久已隐，中情末由写。","所欣青阳动，庭槐绿盈把。","仲尼亦何叹，匪虎率旷野。","出门望长川，谁为问津者。"]},{"t":"咏志二十首 其十","f":"五言古诗","c":["上山采芙蓉，日莫倾筐归。","驺轲陈王道，脂车向梁齐。","龙战方择肉，志愿空令乖。","理人为之牧，嗟哉名实违。","布谷春无畲，促织秋无衣。","悠悠感物变，恻恻怀烝黎。"]},{"t":"咏志二十首 其十一","f":"五言古诗","c":["昔余客幽燕，步上黄金台。","骏骨日以轻，昭王安在哉。","乐生功未奏，荆卿为祸媒。","风吹易水波，萧萧有馀哀。","谁知百代后，东阁淩天开。","岂令蹇谔士，零落同蒿莱。"]},{"t":"咏志二十首 其二十","f":"五言古诗","c":["荒哉阳台梦，无情成匹仇。","苟非精神合，淄渑为断流。","汉廷富群策，一言相千秋。","金石勒盟誓，倏忽婴罪尤。","河清尚可俟，汉广不可求。","言树谖草花，庶用忘我忧。"]},{"t":"学古三首赠胡承之归关中 其一","f":"五言古诗","c":["翩翩双鸣雁，噭噭云中飞。","娟娟蛾眉女，劄劄流黄机。","弃置不成匹，叹息减容辉。","问女何所叹，良人怅有违。","万里遥相望，何由接音徽。","蕙楼鉴素月，兰镫暧虚帏。","身非骖与服，安得同车归。","河清尚可俟，会合何可希。","临岐奏此曲，泪下谁能挥。"]},{"t":"秋怀","f":"五言古诗","c":["瑟瑟陵上松，琅琅峡中泉。","回风相遇合，凄清成管弦。","端居抚时运，闵默何由宣。","野庐尽县磬，飞挽犹开边。","初月张虚弓，流火无炊烟。","明河不可觞，白榆不为钱。","吾民亦劳止，昊天胡乃然。"]},{"t":"临江道中","f":"七言律诗","c":["荞麦花开山翠飞，腰镰翁孺愁相依。","金川道上风浪急，玉笥山前烟火微。","长鲸已堕黄石矶，大将犹搴龙虎旗。","翩然扬袂者谁子，陌上酣歌缓缓归。"]},{"t":"晓发卢沟望京城有感","f":"七言律诗","c":["大车殷地扬尘起，小车轧轧鸣不已。","苍凉似是长安日，呜咽元非陇头水。","玉辇南行筑将台，九重宫阙何崔嵬。","卢沟桥上阑干曲，不似行人肠九回。"]},{"t":"北风篇赠文衡山待诏","f":"七言古诗","c":["轻阴漠漠飞朔鸿，雪崖冰柱连烟空。","银缸入夜照瑶瑟，坐拥青绫闻北风。","北风浩浩吹南极，飞蓬满天堪叹息。","铜龙错落误昏晓，朱凤威垂失颜色。","骚骚屑屑断复连，据梧细听寒不眠。","鲲鹏变化抟碧落，虎兕叫啸愁苍烟。","有时悠扬入寥廓，妙韵奇音相间作。","碧梧翠竹竞竽籁，汉女胡姬合弦索。","又如鲛室鸣杼机，万灵汹涌乘潮归。","老蛟怒挟片云立，海水潇潇皆倒飞。","吾闻风自土囊起，摇荡青蘋千万里。","兰台词客谩雌雄，大块何心乃如此。","忆昨与君同燕娱，琼帘绣幕围彤炉。","坐中酬劝不知暮，门外寒威何处无。","出门势欲卷平地，幽栖咫尺何由至。","褰衣似怯寒浪涌，刮面不数锥刀利。","归来大笑行路难，岂知跬步成关山。","百年鼎鼎贵行乐，何用跋涉摧心颜。","君今未得扬帆去，归梦飘萧满烟雾。","浩歌一曲江南春，北风吹落三花树。"]},{"t":"淡交行","f":"古风","c":["琼楼十二中天起，弱柳崇桃斗青紫。","鱼钥初开鹤盖来，平头奴子皆珠履。","主人爱客名讴出，象琯鹍弦满人耳。","臛蠵脍鲤腾羽觞，文笙黼帐春风里。","当筵意气何所如，以漆投胶差可拟。","舞罢阳阿花作阵，歌残《子夜》霞成绮。","岂知戈戟在谈笑，回看堂上生荆杞。","雨云翻覆噫吁嚱，前有张陈后苏史。","君不见君子之交淡如水。"]},{"t":"碧梧丹凤图为黎侍御一卿题","f":"楚辞体","c":["凤兮凤兮尔来当何时，知尔之德万古长不衰。","不然上天纵尔九苞羽，安用毰毸为。","君不见桃虫当日飞为雕，脊令原上啼鸱鸮。","舄几几，音哓哓，室家恐为阴雨漂。","偃禾风定杲日出，冈上碧梧寒不凋。","尔于此时来，和鸣叶箫韶。","成王优游君奭喜，卷阿为尔歌且谣。","凤兮凤兮披图对尔起三叹，久矣不梦周公旦。","咸阳宫前多枳棘，何用屑屑悲秦汉。"]},{"t":"南征词六首 其一","f":"五言律诗","c":["凤野传清跸，龙旌逼绛霄。","风雷随鼓角，日月耀金貂。","跃马宜春苑，呼鹰织锦桥。","何如穆天子，空赋《白云谣》。"]},{"t":"南征词六首 其二","f":"五言律诗","c":["月照牛山迥，风飘凤吹长。","从臣黄制袷，歌妓锦为妆。","玉辇栖萝幌，金鞭问竹房。","夜阑调虎拨，知是奏《霓裳》。"]},{"t":"南征词六首 其三","f":"五言律诗","c":["翠网张瑶浦，黄旗漾碧流。","殷勤供庙荐，萧洒事宸游。","御气通蛟室，祥烟化蜃楼。","鱼龙应自喜，何敢负王舟。"]},{"t":"南征词六首 其四","f":"五言律诗","c":["簇仗迎春至，行宫向晓开。","日边千骑合，天上六龙来。","玉笛吹《杨柳》，雕鞍唱《落梅》。","共看毬拂笑，岐路满尘埃。"]},{"t":"南征词六首 其五","f":"五言律诗","c":["柳映金陵暮，花摇玉帐春。","江淮明炮火，阊阖动梁尘。","秘戏徵西域，迷楼构北辰。","三千歌舞地，谁似掌中人。"]},{"t":"南征词六首 其六","f":"五言律诗","c":["桂海停舟楫，蓬山献画图。","云屯七萃甲，风递九关符。","进酒龙衣湿，藏阄豸绣呼。","鸡人那复报，乘月射平芜。"]},{"t":"阻冰寓萧氏楼上作","f":"七言律诗","c":["朔风萧萧吹雪霜，登楼独坐生悲凉。","青山知我吏情澹，明月照人归梦长。","云影有时连去雁，水声何日到垂杨。","侧身天地频回首，谁道江湖远庙廊。"]},{"t":"秋穫喜晴","f":"七言律诗","c":["农事初成乐事繁。","即看云水接平原。","巾车道上黄迷垄，社鼓声中绿满尊。","十里断霞明雁鹜，半林斜照散鸡豚。","丰年有愿缘忧国，击壤今闻到处村。"]},{"t":"送顾少参进表之京","f":"七言律诗","c":["殊方长走画熊车，薇阁松窗月色虚。","喜见西山归战马，愁闻南海进明珠。","风生阊阖陈金镜，云拥罘罳拜玉除。","后夜若逢牛斗使，前星应有凤凰书。"]},{"t":"庚子三月八日奉命充经筵讲官有感赋十二韵","f":"七言古诗","c":["春风环佩集群仙，回首瀛洲二十年。","院柳绿垂鸾驾外，宫花红入凤池边。","晓承纶綍开经幄，夕佩兰英拱御筵。","青琐赤墀聊复尔，璇题珍馆故依然。","三阶瑞气缠黄道，六籍荣光出翠川。","祖武直从高帝始，人文真羡孝皇前。","翩跹鹓鹭趋清漏，缥缈麒麟飏紫烟。","芸阁秘书频驻辇，羽陵遗策自忘筌。","座临北斗沾尧酒，帘卷南薰协舜弦。","长乐赐来霞锦艳，上林擎出露桃鲜。","赓歌此日光华旦，下拜何时咫尺天。","遥望帝城珠树里，金华凉月夜娟娟。"]},{"t":"凯歌词十首 其四","f":"七言绝句","c":["孝陵松柏贴青霄，凤辇龙旗久寂寥。","百岁遗黎应感叹，神孙英武似先朝。"]},{"t":"凯歌词十首 其七","f":"七言绝句","c":["锦鞯白马出新河，蔟队吴娃善凯歌。","谱得升平新乐府，内家休按旧云和。"]},{"t":"凯歌词十首 其八","f":"七言绝句","c":["诸番鞮寄太侏离，重译于今圣得知。","已有茅封及边帅，更将天姓赐胡儿。"]},{"t":"宫怨","f":"七言绝句","c":["上阳宫殿倚云霞，天外时闻度翠华。","鱼钥重重锁窗户，夜来春雨到梨花。"]},{"t":"旅夜","f":"七言绝句","c":["沉水烟消腻烛黄，疏帷浮动月苍苍。","栖鸦不避霜风恶，绕树数声秋夜长。"]},{"t":"厓山怀古六首 其六","f":"七言绝句","c":["南闽不废祥兴朔，西蜀仍闻艺祖孙。","会与英雄消积恨，直从龙凤定中原。"]},{"t":"西清词六首 其二","f":"七言绝句","c":["碧殿峥嵘概泰清，飙台时送《步虚》声。","流铃掷火飞章地，一片云遮翡翠城。"]},{"t":"西清词六首 其四","f":"七言绝句","c":["辇道阴森万柳齐，水晶帘幕动晴霓。","六龙行处金蜩合，冉冉红云阆苑西。"]},{"t":"西清词六首 其五","f":"七言绝句","c":["红叶飘摇出御沟，银屏金屋不知秋。","侍臣鹄立空翘首，日色曈昽满凤楼。"]},{"t":"西清词六首 其六","f":"七言绝句","c":["减却云鬟带玉冠，紫烟衣薄露光寒。","《步虚》声里琪花落，赢得君王转盼看。"]},{"t":"莫春朝陵西游次张石川韵十首 其一","f":"七言绝句","c":["东风阁雨漫经春，日暖陵园绿未匀。","多少柳绵随燕子，宫监犹望属车尘。"]},{"t":"莫春朝陵西游次张石川韵十首 其二","f":"七言绝句","c":["胡马长窥白草凋，神宫休道紫台遥。","日斜堪望交河戍，风急如闻瀚海潮。"]},{"t":"莫春朝陵西游次张石川韵十首 其三","f":"七言绝句","c":["隧道前头御路平，春来雨露不胜情。","路人曾见官家过，翠幔红妆逐辇行。"]},{"t":"莫春朝陵西游次张石川韵十首 其四","f":"七言绝句","c":["天寿山前云出虹，玉泉长在柳阴中。","五风十雨多禾黍，野老开来说孝宗。"]},{"t":"翕云三章章八句黄钟清宫","f":"古风","c":["油油翕云，维龙之朋。","君子来思，球瑟和鸣。","和鸣鼓庸，篚帛既共。","式愉式诲，君子攸躬。","油油翕云，维龙之遒。","君子来思，鼓瑟鸣球。","德辉孔周，云胡曾不我留。","饮此芳醑，俾我昭受尔休。","油油翕云，维龙之光。","君子来思，球瑟锵锵。","球瑟锵锵，匪曰大康。","饮此芳醑，以俾我尚于中行。"]},{"t":"驱马五章章五句黄钟清宫","f":"古风","c":["驱马滔滔，遵彼林皋。","匪游以遨，将命靡竣，我心忉忉。","驱马滔滔，戒我徒旅。","匪游以遨，将命靡竣，岂求宁宇。","悠悠彼鳣，载浮载潜。","亦照于潭，将命靡竣，父于何瞻。","离离彼翟，载鸣载飞。","亦集于蓖，将命靡竣，母于何依。","驾彼乘牡，夙夜孔皆。","匪游以遨，念我二人，歌以告怀。"]},{"t":"彼尔有棠五章章四句黄钟清宫","f":"古风","c":["彼尔有棠，敷贲于稷。","焞焞輶车，迈如弗克。","我车徂丘，六辔既柔。","夙夜其勤，爰诹于郊。","我车徂岨，六辔如组。","夙夜其勤，爰谋于野。","我车徂薄，六辔如濯。","夙夜其勤，爰度于国。","我车徂宫，六辔既雍。","夙夜其勤，爰询于公。"]},{"t":"孟冬亲享礼成有述","f":"古风","c":["天眷有明，全付寰宇。","苍精洞照，黄垆孔膴。","三极荐馨，百祇协矩。","列圣受之，灵承于旅。","御历执符，率循伦序。","皇帝睿圣，克配舜禹。","河澄献瑞，虹流烛渚。","龙飞虎变，奋迹南楚。","躬发人文，志蕴神武。","亲以孝崇，民以仁煦。","望日就云，有睎匪?。","绍我毅皇，光于烈祖。","敷天之下，欢讴忭舞。","庆宵葱茜，宸景晰旿。","更化图新，主敬作所。","休否成泰，亨屯干蛊。","如彼巨室，饬厥藻斧。","如彼天道，以凉我暑。","皇帝笃友，室家哀素。","遗大投艰，创深痛钜。","康陵告竣，乃正当宁。","乃于孟冬，乃卜乃簿。","乃谋乃惟，乃集有瞽。","乃陈广乐，享七庙主。","虡业崇牙，乃县乃树。","箾筦琴瑟，应田柷敔。","钦钦维庸，逢逢维鼓。","作麟仪凤，吼鲸动虡。","镗鎝铿訇，匪淫匪怒。","佾舞洋洋，拜伏昂俯。","既备既调，既优既拊。","大乐展奏，既协雅部。","皇帝乃驾，斋宫往吾。","周庐星列，阁道宵抒。","中貂肃队，金吾设卤。","千官景从，接圭联组。","龙旗云丽，凤盖霞举。","和鸾韵风，旭旭许许。","亦既戒止，殚我丹腑。","维精维诚，神若可睹。","赫赫肸蚃，恍恍笑语。","左右赞相，将事黎暏。","揭虔妥灵，孰敢有侮。","奉璋具鬯，濯鼎及卣。","亦有藉茅，大羹玄酒。","有粱有秬，有稷有黍。","陈彼巨豆，大房鸿俎。","腒䐹醢酖，脾臄及鯆。","䨲鹿维炙，载有鲜羽。","皇帝乃奠，盘辟拜頫。","有祝伊弁，稽首覼謱。","会精思成，灌我清醑。","神其来止，歆我簋簠。","陟降左右，昭穆萃聚。","神其归止，祥飙灵雨。","云舆纾徐，星骥容与。","光景缤纷，绛霄翔栩。","皇帝孝谨，拜受神胙。","神锡皇帝，千祥百嘏。","室家之壸，眉寿黄耇。","执冒端委，作民父母。","于万斯年，永有中土。","神锡皇帝，股肱心膂。","翼以皋夔，从以周吕。","纳谋和衷，同德夹辅。","于万斯年，匹休扶珇。","神锡皇帝，丰年亡窭。","懞懞瑞麦，与与祥稆。","陈红相因，充满仓庾。","于万斯年，下民奠处。","神锡皇帝，聪明中度。","天临海镜，贤登佞去。","消彼獝狘，凿齿猰貐。","于万斯年，无有喔咻。","神锡皇帝，福女毋拒。","于万斯年，永其福女。","皇帝孝谨，拜受神祚。","怀福载归，詹恋堂庑。","采齐奏节，言旋禁籞。","出御端门，赐群臣脯。","徽仪熙穆，从容燕誉。","如天之泽，如露之湑。","万国同庆，龙德斯普。","于万斯年，孝享受祜。","于万斯年，埏垓顺叙。","于万斯年，有明之绪。","微臣作诗，用继商鲁。"]},{"t":"短歌行送洪子玉方","f":"古风","c":["秋露载晞，朔云云飞。","盍簪讵几，驾言騑騑。","肃彼前旌，奏此和铃。","风骖翼人，遄如流星。","今夕同堂，明发异乡。","何以别子，骊歌鸾觞。","林疏壑清，山空鸟鸣。","风吹断蓬，与客徂征。","子在在燕，洌洌寒泉。","挠不可浊，其流为川。","子在在浙，寒泉洌洌。","思子如濯，中心孔热。","石田碌碌，逋税斯督。","云谁之故，空其杼柚。","原则有杉，隰则有蓝。","糟糠短褐，饥寒所甘。"]},{"t":"奉使鼓吹曲四首 其一 关塞曲","f":"古风","c":["关塞长，关塞长，引弓鸣镝秋草黄。","临交河，望金微，风吹沙作浮云飞。","诏期门，驰羽书，韦韝索辫辞穹庐。","惟职方，贯利同，輶轩駊騀川原中。","抚长剑，行路难，有何者鸟菀于弁。","搏雕虎，接飞猱，登顿濡迹安足劳。","徵九赋，赉三军，䯀骢父马徕如云。","建华眊，遏奔鲸，奏铙旋镯邦国宁。"]},{"t":"奉使鼓吹曲四首 其二 汴梁曲","f":"五言古诗","c":["伊洛亘衿卫，沃野开豫疆。","分茅席英彦，信多筹策良。","抚翼希天池，抗志咏甘棠。","控绁兰皋侧，弭盖椒丘阳。","夙夜无茕嫠，闾阎交相庆。","输国有程度，启处安可遑。","露冕入燕冀，飞鹢浮河漳。","扶宫罗绣户，京室何煌煌。","引领三叹息，牵牛空服箱。"]},{"t":"奉使鼓吹曲四首 其三 燕山曲","f":"古风","c":["彼崇崇者燕山，北俯碣石祁连。","胡骑啾啾沸天，摧坚仗此佶闲，翩翩霞布星躔。","冀产俶傥权奇，军?逸迅雄姿。","忘筌引镜黄骊，膺帝命主治之。","濯龙歌万福徕，东方之日照坰。","服皂螭翥鸿惊，蹀足徒睎朔旌。","西驰瑶水冥冥，寤摽仰惟圣明。"]},{"t":"奉使鼓吹曲四首 其四 昆明曲","f":"古风","c":["浩浩昆明池，乃在点苍山阳，旁有罗施故邦。","蚁附蝉联，賨僰蛮髳，参错其间。","宣父居九夷，道大无不容。","白日灼幽崖，穷发渐华风。","浇讹反天经，由余谅非戎。","髬髵着裲裆，砺刃驰且都。","投刃拜中丞，呕吟挟诗书。","嫉巫信医，日和以愉。","芃芃彼荠麦，秽我兰亩。","培灌其勤，荠麦亡嗣有。","循圣贤长道，屈此群丑。","臣心不负陛下圣，上有仓浪之天，下有孩提黄口。"]},{"t":"骢马行赠别张侍御归常州省母","f":"古风","c":["骢马驱河干，饮饯相追攀。","骢马驱河干，饮饯相追攀。","朱汗染月题，玉珂鸣珊珊。","驾言将母，千里当何难。","歌以言之，骢马驱河干。","瞻彼瑶水旁，芝草何翩翻。","瞻彼瑶水旁，芝草何翩翩。","采采盈怀袖，盛以白玉柈。","奉母驻容颜，延寿千万年。","歌以言之，瞻彼瑶水旁。","象琯绕凤梁，芳筵乐未央。","象琯绕凤梁，芳筵乐未央。","青女素娥，迭舞浩倡。","彩服延鲜风，照耀白日光。","歌以言之，芳筵乐未央。"]},{"t":"吊许大夫文","f":"楚辞体","c":["闵大夫之偭辰兮，扣斧铋而商歌。","心愲结以涕洟兮，何仓浪之幽遐。","纷既邅回而树伐兮，身胡邈乎王家。","羌劲杓乎妖藩兮，卒离身而速化。","呜呼恫哉兮，大夫之纯贞。","世途氛霾兮，翳雒棠以为明。","驱鸡斯以守闾兮，乘狶獒而驾衡。","絷长离而笯之兮，鬼车奰奰而昼鸣。","谓钩吻为饴兮，谓膻湩为馨。","犠尊弃于溷澖兮，衷庞凉以为荣。","长门幽摈夫南威兮，登砻廉于曾城。","主伊皋以庖偪兮，偕来革而迅征。","于嗟梦梦兮，惟荃之故。","扣阶苔绣兮，泥秽遵夫。","鸾簬幽痗讳其膏盲兮，拒斥俞跗蹻蹠。","夹翼于皇舆兮，日怀宝而营富。","彼狡童亦何知兮，乃窥觎而干天步。","朋游光以为侣兮，魌魅集其如林。","嘑白徒使血人兮，鸣火狐而肆鸱音。","辟童触麋而首灰兮，顾宏肆其毒淫。","万舻销于一炬兮，程吴濞而卒禽。","桎拲崩厥角之纷如兮，饫珍谷夫何心。","维大夫之介特兮，狡童龈以为仇。","进欋梳而杖之扶兮，荃又昧夫好逑。","倅寸铁之弗持兮，耿忠略其谁谋。","表丹忱以就兵兮，白日为之匿幽。","呜呼凶罦高张兮，凤摧其仪羽。","神龙失凭兮，乃叽于鼠。","巷哭且䁲兮，伤我士女。","綵霞蜚兮，玉輤举。","风萧萧兮，神灵雨。","嗟世之知大夫兮，维守死而不移。","余惟追数夫荃兮，登大夫之匪宜。","朝有黯而淮南寝谋兮，寔大夫之优为。","苟维寄大夫以禦侮兮，又何至勤外部而陈师。","既告甸以县磬兮，聊以慰夫行路。","何大夫之同轨兮，尚或疏逖而齐怒。","謇大夫而慭遗兮，固亦遵涂而窘步。","泊皇穹之纯佑兮，何不改乎此度。","嗟佳冶之纬繣兮，稽前修以皆然。","璠玙有弃而抵鹊兮，堇䔭有采而升筵。","董道搆悯以不回兮，视余袂之涟涟。","魂耿耿其在天兮，亘宛虹之连蜷。","墋黩尚其有极兮，永与泰素而周旋。"]},{"t":"琴操三首 其一 玄云操","f":"古风","c":["油油玄云，蔽日之光。","有昏者椓，持天之纲。","禺原膴膴，可耕以粟。","驷马高车，无我囊三木。","若虞设罗，色斯駴而。","彼巢于幕，于嗟殆而。"]},{"t":"琴操三首 其二 荆山操","f":"古风","c":["我徂荆山，历彼林与丘。","大道坦坦，我行夷犹。","丘则有貉，林则有麻。","我采我猎，供我后裳与裘。","匪裘裳也，则无寒暑诒我忧。","嗟我后圣矣，国谁与预谋猗。"]},{"t":"琴操三首 其三 菊泉操","f":"楚辞体","c":["菊之株挺挺兮，匪则有柯兮。","泉之源庞庞兮，匪则有沱兮。","柯维其那，沱维其波，我啸以歌兮。","虽有胾肉，于以餐我菊兮。","虽有甘醴，于以酌我泉水兮。","匪菊之馨，匪泉之清，我忧如酲兮。"]},{"t":"琴操一首赠别徐可大","f":"楚辞体","c":["岳峰高兮石离之，高贤藏兮民知之。","中有田兮侧有茨，褐之父兮耕治之。","烝而云兮倏而雨，雨滂滂兮峰之下。","田亩亩兮以禾黍，云兮归兮吾待汝。"]},{"t":"孝烈祠乐章二首 其一","f":"楚辞体","c":["鼍逄逄兮考鲸，湛椒浆兮列兰蒸。","五音饰兮黻绣张，瑱瑶席兮玉英。","膋萧炳兮拜以頫，琴瑟奏兮云门舞。","南垓阕兮柏舟，灵不徕兮夷犹。","骖泰鸿兮烛龙辔，庆阴阴兮灵其有喜。","倏蕙带兮荷裳，又金支兮翠旗。","鸳鸯鴹兮灵之徕，灵徕不徕兮我心悲。"]},{"t":"孝烈祠乐章二首 其二","f":"楚辞体","c":["濮山㟪崔兮濮水漻泬，高贤愉愉兮繄孝而烈穆。","并骋兮槃桓，揽桑梓兮涕潺湲。","象舆轙兮憺容与，灵临飨兮福我士女。","矫扬光兮宴娭，永山侧兮云施。","般姚姚兮裔裔，灵何为兮汪然逝。","褰雾縠兮窅冥冥，山水夕兮含清。","春有兰兮秋有菊，结无极兮芳馨。"]},{"t":"情诗二首 其一","f":"五言古诗","c":["玄云亘北陆，朔风销繁林。","荏苒岁律殚，广庭多冱阴。","仰惜流景迅，俯叹无完衾。","所思眇天末，欲往冰雪深。","寒鹊求其曹，当檐遗我音。","翩翩倏相逐，望望独伤心。","伤心不可极，付此焦桐琴。"]},{"t":"情诗二首 其二","f":"五言古诗","c":["旭光射凝雪，起望前楹东。","曾云忽蔽亏，蹙啸延绪风。","绪风无回轮，曾云自冥濛。","佳人怅何许，天阻安可通。","晖目亦知晏，蛰虫亦知冬。","营魂抱区区，伫立思音容。","叹息咏其雨，劳心夜冲冲。"]},{"t":"学古为人代赠","f":"五言古诗","c":["信誓愿偕老，绮筵当夕张。","蕙心美无度，兰灯明洞房。","柔情方日洽，健翮俄风翔。","金门邈霄汉，玉音限河梁。","忧来拊齐瑟，偪侧中自伤。","人生有离合，世事安可常。","妍华化枯槁，会见熙春阳。"]},{"t":"岁暮言志","f":"五言古诗","c":["华年日婉晚，隐几意不惬。","晞古思振缨，抚时泪承睫。","遥闻逵术中，车马竞驰蹀。","金张富熏天，汉貂垂七叶。","纷纷誇毗群，蹇谔叵容接。","守朴道所敦，弥文世方业。","遗经如不售，已矣事畋猎。"]},{"t":"忧旱词四首次周太保韵 其一","f":"五言古诗","c":["火旻何硉兀，赪霞倏舒敛。","阳崖卉渐腓，阴畛穗犹懦。","淩晨秉良耜，届午已重趼。","丰殷虽有愿，藨蓘竟难展。","龟折遍沮洳，象耕失岩巘。","赤子本谁责，黄尘眯予眼。","下泉良可悟，膏雨亦云远。","桔槔正纾急，袯襫俄揭浅。","蹙啸起长叹，司命孰回转。"]},{"t":"忧旱词四首次周太保韵 其二","f":"五言古诗","c":["端居揆天道，回转藉人理。","歌雩泊周典，牺祷怀殷祀。","灵鉴未云集，甘澍难久俟。","皓皓咸池升，浩浩玄云起。","光景方蔽亏，忉怛靡终已。","重阴閟阊阖，阡术多荆杞。","幸此弥天泽，贶我崇朝喜。","鱼龙恣瀺灂，卉木纷旖旎。","骤焉不终惠，昭假竟谁恃。"]},{"t":"忧旱词四首次周太保韵 其三","f":"五言古诗","c":["昭假嗟无端，汗下如流汞。","长飙旦夕起，万里火云动。","仰睎灌木阴，俯羡渫泉涌。","箕毕澹不芒，蔚荟隮以耸。","积阳忽退舍，有渰弗旋踵。","渗漉洽瀛壖，葱茜被畴垄。","数极见仁悯，望惬免疑恐。","亮非牲玉感，尚觉蕴隆重。","谁能挥龙渊，为我刑螮蝀。"]},{"t":"忧旱词四首次周太保韵 其四","f":"五言古诗","c":["螮蝀不可指，矧可刑使雨。","氛祲未讵销，霖泽自为阻。","燮调付茂宰，陶钧自明主。","天居崇万里，齐州隔九土。","荐馨维齐明，厚生在农扈。","嗔雷怒未平，场苗青几许。","龟肠营一食，鹑衣成百缕。","颇闻禁苑凉，凤吹导鸾簬。","忧来奏虞弦，操缦且调柱。"]},{"t":"赠黄子令浙水","f":"五言古诗","c":["沐浴际嘉运，王路方清夷。","九重轸民瘼，推择为吏师。","夫子受灵眷，宰邑抚茕嫠。","露冕浙水春，银章有光辉。","种花当使滋，泽民当使肥。","中心发阳和，涸野成良畦。","灼灼崇桃枝，健翮聊假栖。","一朝风云合，当为鸿鹄飞。"]},{"t":"送丘子令馀姚","f":"五言古诗","c":["车盖集宛洛，爱子能久要。","览此光熙运，奋翮扬英翘。","绾绶宰花县，飞舄淩云霄。","别子问何时，朔风驱玄涛。","落叶归本茎，茂松见后凋。","君子秉贞性，岂为寒暑摇。","援琴奏清商，怅望心烦劳。","孤鸿遵修渚，别鹤唳远皋。","殷勤伏尊簋，于焉永今朝。"]},{"t":"送盱令奏凯北上","f":"五言古诗","c":["弱植抱匡济，宰邑光有孚。","妖藩构天祸，奋身被缦胡。","谈笑剪鲸鲵，志与白日孤。","长飙激西江，鲜彼乌林谟。","奏凯赴皇阙，裨海皆歌呼。","鼓角声遏云，组甲光载涂。","行当荷宠灵，千载昭令图。"]},{"t":"送刘子养和督学山西","f":"五言古诗","c":["金风鸣素节，严霜肃中坰。","新丰木叶脱，灞浐寒波生。","送君郭门道，衔命戒晨征。","飞幰指蒲坂，落霞随旆旌。","陈臬在风教，晞古当振缨。","尧宫土华碧，舜山烟草平。","相期辟皇路，为君歌德声。"]},{"t":"湛子宅夜宴和吕子仲木边炉诗","f":"五言古诗","c":["围炉坐寒夜，嘉宾愕以盱。","朱火光吐日，阳和满前除。","众肴归一器，变化斐然殊。","食美且需熟，充实谅由虚。","妙悟得同志，揽环誓相于。"]},{"t":"云洲隐居","f":"五言古诗","c":["结庐天水交，菰蒲断人境。","水气蒸为云，摇光混波影。","清飙驱云去，净绿澄万顷。","心随游鲋适，目送狎鸥迥。","卷舒悟世理，流动入神领。","举觥挥碧寥，浩笑策飞景。","与君论大年，龟鹤未为永。"]},{"t":"游李将军梅园呈同游张廖童三子","f":"五言古诗","c":["丹云出秋郭，萧晨恣游冶。","凉飙动天末，紫翠满平野。","驾言税梅园，水竹自幽雅。","方舟散鹥鹭，通川入桐槚。","兴乘虚籁发，目送惊湍泻。","云飞答流讽，川咏避挥斝。","盘纡极展眺，尘悰倏潇洒。","微茫高屿外，隐映暮霞赭。","营欢恨晷速，顾景不能舍。","今日乃何日，胜引得陶写。","达士谢溟涬，浮荣譬风灺。","文案苦缠纠，况复役车马。","缅怀区中人，亮志良已寡。"]},{"t":"伏读嘉靖登极诏有述","f":"五言古诗","c":["皇穹新泰运，帝迹发郢甸。","讴歌仰玄德，恭默受灵眷。","甘澍从宝舆，瑞日丽瑶殿。","宸景既昭晰，庆宵亦葱茜。","得一天下理，吹万群情忭。","渥恩流宇宙，丝纶迅风电。","扶听走衰白，喜极泪成霰。","毅皇昔开边，宇内轮蹄遍。","大阿忽所持，群妖竞方煽。","虐焰然不息，丰镐失诒燕。","悔从黄竹萌，痛自乌弓恋。","亨屯出雄断，休否席耆彦。","布濩神武震，灏噩人文绚。","奸如转石去，贤用拔茅荐。","外圉事櫜戢，内帑发馀羡。","鸿猷悉以举，丕构从此奠。","非心在黄屋，恫瘝惟赤县。","煌煌嘉靖治，不廑鬼方战。","崇极得辞圯，宜民见通变。","稽首诵尧言，万代永如见。"]},{"t":"抡材赴公宴作","f":"五言古诗","c":["抡材受明诏，骊步金马门。","清尘接台衮，彯节追华轩。","高宴春官署，序爵列长筵。","殽核一何绮，桂糈映兰鐏。","方怀失士惧，敢营酬酢欢。","金玉赞王度，化成肇人文。","引领睎皇居，紫气腾玄间。","联翩谢慈惠，稽首复何言。"]},{"t":"春院试士二首 其一","f":"五言古诗","c":["春院寂以迥，鱼钥何重重。","哲匠贲嘉运，海镜开昭融。","华镫照藻服，虚堂流夜虹。","丰膳侑清觞，有集惟俊雄。","入帷见素月，鸣枝怀绪风。","矢心同靖密，坐待虬漏终。","褰衣拂鞶砺，矫望明河空。","协极待群彦，道合时乃雍。","安得翙翙羽，接翼鸣高桐。"]},{"t":"春院试士二首 其二","f":"五言古诗","c":["冀产多龙骥，荆山饶奇璞。","永怀和氏愆，愿骋孙阳目。","拥衾盘礴裸，秉心向明烛。","朝餐青玉案，暮御流黄幄。","衣缊甘食萍，于焉愧珍谷。","谁令钩棘习，回漓见熙穆。","伟矣欧阳子，千秋仰乔岳。"]},{"t":"出京别亲友三首 其一","f":"五言古诗","c":["絜身游魏阙，周旋未言殚。","天衢何崇崇，短翮思飞翻。","赖我金兰友，婉娈同所欢。","衔恩负羁绁，遥役指岷嶓。","威蕤集端委，璀璨纷盘飧。","朝车发朔涂，莫舟泊河干。","褰衽自兹去，伫立怀辛酸。","矫矫飞鸾鸟，奕奕彤云端。","会长不自庆，别促空成叹。"]},{"t":"出京别亲友三首 其二","f":"五言古诗","c":["秋秋天地肃，玄林严风发。","嗷嗷宿雁起，万里黄云没。","行子怀越都，胡马嘶燕月。","伫立睇川原，川原莽空阔。","树萱亮有怀，食芹旷未达。","况兹别亲宾，何由慰饥渴。","昔为骖与靳，今为弦与筈。"]},{"t":"出京别亲友三首 其三","f":"五言古诗","c":["騑服本同驾，葛藟亦相因。","辞家忽五载，良朋成密亲。","贞心秉金石，绮言丽苍旻。","终始誓不渝，辉光期日新。","岁月不我留，鶗鴂鸣萧晨。","骊驹方载路，万里违音尘。","志气恒相孚，异县犹同人。","行矣各自励，修名良足珍。"]},{"t":"登衡岳值风雾至绝顶忽霁感灵贶赋二十韵","f":"五言古诗","c":["炎德殿南戒，玄功协北祇。","大哉祝融祀，邈矣陶唐时。","锡民溥鸿泽，翊国隆骏基。","明明翼轸列，滔滔江汉驰。","屹柱立乾栋，连络亘地维。","衣带萦三湘，婴孺抚九疑。","攒峰锁苍雾，标岚横彩霓。","青玉固葱茜，朱陵亦葳蕤。","兹山擅雄峻，伊予嗜灵奇。","停舻谐夙愿，彯节随所之。","仰探丹凤穴，俯见玄豹崖。","冥濛苦氛祲，窈窕多路岐。","皎镜雪方积，虚壑风何悲。","岂知淩绝巘，及此娱晴曦。","歘吸朅灵景，混茫开太仪。","烟霭散林薄，云光溢川坻。","平崖少延伫，穷发皆可窥。","振衣望郢甸，披云辨京圻。","如彼朝阳鸟，跂尔梧桐枝。","整翮自兹去，翱翔本无期。"]},{"t":"濂溪","f":"五言古诗","c":["真儒去代久，一亩存遗宫。","濂泉洌不食，旦夕寒潨潨。","芙蕖谢光彩，卉棘纷蒙笼。","乌鸟聚乔木，噭噭鸣积阴。","依岩见樵爨，驻辙闻村舂。","日晏牛羊下，秋高禾黍丰。","溯源旷无人，沿泂焉所终。","蹇予勇言迈，扶策安能从。","精灵谅斯在，沕穆相为通。","繄昔宋中季，皇流叠褒崇。","披云起结构，洒翰盘蛟龙。","霁月辉朱缀，光风摇琐窗。","谁令坐消歇，吾道曾何穷。"]},{"t":"月岩","f":"五言古诗","c":["驱车冒灵雨，月岩访幽奇。","引顾穹壤间，见此两郁仪。","蟾兔耀白日，神工开翠崖。","金波互盈朒，玉输中渺瀰。","消长瞻世变，弦望通天时。","广筵得明牧，脱幅忘尘羁。","葭鸣虚籁起，杯深灵景移。","因之发长啸，风生丛桂枝。"]},{"t":"送秦刑曹之留都","f":"五言古诗","c":["瞻彼长淮水，上有孤凤台。","躯车发朱夏，岐路何恢台。","淑问睎皋陶，振缨感我怀。","我怀草昧初，经纶协云雷。","晋接有遗构，丰芑多良材。","粲粲琅玕花，亭亭倚风开。","昊穹正玄邈，孤凤何时来。"]},{"t":"莲亭奉南渭王宴中作","f":"五言古诗","c":["菟园启瑶构，灵沼竞芳鲜。","莲花何晔晔，莲叶何田田。","耀魄泛空波，神飙起中天。","馨香入襟袖，把酒心茫然。","懿此出深滓，素质虚以圆。","本无枝与蔓，何惧外物牵。","缅怀君子德，冥心入冲玄。","嘉宾从南来，浩倡协虞弦。","闾阎一以阜，民愠从兹捐。","徽音彻穹垕，清欢眇云烟。","思为双飞鹤，接翅浮漪涟。"]},{"t":"大兴隆寺小集赠别卢侍御尧文分韵得冕字","f":"五言古诗","c":["孤飞思比翼，独行愿同辈。","自我违良友，契阔情不浅。","京洛期合并，江淮怅悠缅。","今夕乃何夕，及此会轩冕。","宝瑟延素月，金罍耀芳宴。","问子何所为，令猷日光阐。","乘骢训青衾，雕龙理黄卷。","譬彼荆山璞，追琢尽成瑑。","采萧固三秋，艺兰亦九畹。","洋洋清商阕，宛宛车轮转。","脉脉衔离忧，恻恻增婉娈。","潞渚肃清涨，秣陵望丹巘。","自非南流景，何繇知近远。","瑶华迟尔音，琼树跂余蹇。","千里通精诚，愿言各敦勉。"]},{"t":"秋日登万岁山不果至琼华岛辽后妆楼而返与张廖二子同赋分韵得登万二字 其一","f":"五言古诗","c":["玄天临析木，白云出丘陵。","皇居阻通轨，神池閟清澄。","翠峒纡历览，琼楼恣攀登。","阳陆日月迥，阴崖雷雨凭。","雕阑缀碧藓，藻井巢苍鹰。","炯戒鉴夷夏，端居思废兴。","飞狐已迢递，疏龙尚轩腾。","宇宙席休运，人神归圣能。","同游集轩冕，缛仪崇股肱。","虹桥架鳌炬，星旗翼鸾乘。","灵踪固葱茜，秋霜正严凝。","抚化惜遐景，览物怀坚冰。","长啸倚林薮，浩歌望觚棱。","虚籁殷珠树，凉飙摇玉绳。","兹游信有适，谁言殊鴳鹏。"]},{"t":"秋日登万岁山不果至琼华岛辽后妆楼而返与张廖二子同赋分韵得登万二字 其二","f":"五言古诗","c":["青梧飘素秋，烟霜变昏旦。","所忻天地肃，适意山水玩。","眇默循玉阙，威迟度金涧。","长虹浮大川，积翠亘天半。","瑶甍拂台斗，绮窗瞰云汉。","丹梯指遐坂，黄图入英眄。","凤京环百二，鹏霄翻九万。","风起云嵯峨，日耀树淩乱。","昔闻青娥妆，今见碧草蔓。","采莲无缓歌，握兰白遗叹。","淋池翔王凫，芳洲宿朱雁。","蹇予及朋好，羡尔游波间。","谑浪金门隐，凄其广陵散。","扣阍讵有遇，褰裳庶无闷。","缅怀岩桂业，徘徊岁将晏。"]},{"t":"闻汪侍读奉命校书建阳诗以奉谂","f":"五言古诗","c":["矫矫鸾凤姿，翩翩出蓬海。","吐卷嗟已尘，衔甲今安在。","姬坛久零落，孔室沉光彩。","振翮时一鸣，人文朗千载。","缅邈闽峤东，潇洒辞鸳鸿。","而我咏苞栩，骋望愁烟空。","蒹葭下玉露，橘柚摇金风。","因之感摇落，征心夜冲冲。"]},{"t":"十六夜补之席上赏月分韵得水字","f":"五言古诗","c":["长风吹燕树，月色浩如水。","华堂彻明烛，飞轩集同轨。","金波散窗户，琼筵一何绮。","兴随虚籁发，歌逐流云起。","清辉虽可悦，亏盈自兹始。","人事有代谢，况乃幽玄理。","惟恐秋已深，严霜被兰芷。","默坐闻疏砧，孤怀渺千里。"]},{"t":"学古三首赠胡承之归关中 其二","f":"五言古诗","c":["巾车返初服，淩晨发京洛。","引顾咸阳道，云山互参错。","威夷眄三涂，嵚岑辨二岳。","草树郁仟仟，沟塍纷漠漠。","霞日映宫雉，明灭见城郭。","行子归旧疆，园田惧芜落。","庄生傲柴栅，台公愿藜藿。","已蠲原宪耻，无论启期乐。","道因傥来悟，心泯然疑作。","达士有遗矩，卷舒在龙蠖。"]},{"t":"学古三首赠胡承之归关中 其三","f":"五言古诗","c":["玄冬服纤纩，不若貂襜褕。","新知虽云乐，不若故人姝。","华轩岂不美，休休惟故居。","故居乃何所，乃在秦城隅。","山泉环户牖，树木何舒舒。","开帘见栖鸟，临渊羡潜鱼。","孤菊扬其英，芳草不复除。","适意向井臼，陶情在琴书。","此生谅已得，不乐将焉如。"]},{"t":"八美诗八章章八句美同馆八君子也分携眷恋聊宣别情云尔 其一 张侍御","f":"五言律诗","c":["水南鸾凤姿，栖心向丹霄。","兰台聊大隐，尘埃视金蜩。","诒我一束诗，灿灿英琼瑶。","容辉在寤寐，鄙吝犹自销。"]},{"t":"八美诗八章章八句美同馆八君子也分携眷恋聊宣别情云尔 其二 张太史","f":"五言律诗","c":["龙湖蕴神奇，豪爽绝今古。","性不缨垢氛，啸傲对圭组。","存身贵深蛰，偕时乃施普。","炳炳金艧言，铭之在衷腑。"]},{"t":"八美诗八章章八句美同馆八君子也分携眷恋聊宣别情云尔 其三 葛黄门","f":"五言律诗","c":["魁山冀方杰，博雅能沉几。","振缨愿匡济，握镜通玄微。","申章吐芳讯，焕烂云霞飞。","行矣掩瑶瑟，知音良已希。"]},{"t":"八美诗八章章八句美同馆八君子也分携眷恋聊宣别情云尔 其四 赵黄门","f":"五言律诗","c":["洪洋秉清真，胸次无尘滓。","高卧烟山春，倏为苍生起。","裁诗最清绝，秋月照寒水。","临岐怀好音，轸念林居子。"]},{"t":"八美诗八章章八句美同馆八君子也分携眷恋聊宣别情云尔 其五 杨中允","f":"五言律诗","c":["方城甲天下，灵气钟神州。","蹇谔斥奸佞，谦光遇王侯。","青冥翔健翮，白日县方猷。","喟焉伤别促，采萧咏三秋。"]},{"t":"八美诗八章章八句美同馆八君子也分携眷恋聊宣别情云尔 其六 廖太史","f":"五言律诗","c":["廖子谢白鹿，英声振金马。","掞天摛雄词，星辰纮九野。","凫藻竞驰目，骊珠遂盈把。","嗟余蹇且拙，末由追大雅。"]},{"t":"八美诗八章章八句美同馆八君子也分携眷恋聊宣别情云尔 其七 郑黄门","f":"五言律诗","c":["郑公不胜衣，见义奋直前。","日月勤献纳，忠愤思回天。","芸阁昔讲肄，器重余独先。","诵抑师卫武，终身知寡愆。"]},{"t":"八美诗八章章八句美同馆八君子也分携眷恋聊宣别情云尔 其八 王太史","f":"五言律诗","c":["兰陂何温温，璠玙美无度。","遇事类迟钝，潜心绝驰鹜。","六籍究万微，绩学日宏富。","燕郊独送远，离情满豪素。"]},{"t":"游通天岩同林二山宪副作","f":"五言古诗","c":["石林展奇眺，飞幰遵崇阿。","翠壁中洞开，云日相荡摩。","桂户頫琼阙，花宫敞银河。","四顾绝埃壒，颢气流灵和。","披襟倏萧散，盘礴兴啸歌。","陶陶随所适，野酌依烟萝。","皓月照堤柳，微风扬泽荷。","褰帷自兹去，真赏岂在多。"]},{"t":"白沙新祠二首 其一","f":"五言古诗","c":["尼山日云雾，叹息弥轸情。","万有何芸芸，虚完本中扃。","好古遗真筌，乃为耳目营。","所以林居子，持此常惺惺。","嗟彼芷与蓠，不同春草荣。","玄穹正摇落，辛勤荐芳馨。"]},{"t":"白沙新祠二首 其二","f":"五言古诗","c":["崇祠倚云汉，飘缨陟遐坂。","萧萧木叶下，冉冉岁月晚。","贞元无停毂，端坐知易简。","环顾望九洲，天逵一何坦。","黄鹤去不息，白云何时返。"]},{"t":"同年会以新秋同年雅集为韵六首在会者顾佥宪溱刘佥宪乔余给谏经梁侍御世骠伦侍御以谅及予也 其一","f":"五言古诗","c":["南纪肇秋序，金飙动高旻。","今夕乃何夕，宴笑成阳春。","顾刘宪度肃，余梁凫藻新。","伦子材卓荦，俱称华国珍。","愧予澹荡姿，海鸥竟难驯。"]},{"t":"同年会以新秋同年雅集为韵六首在会者顾佥宪溱刘佥宪乔余给谏经梁侍御世骠伦侍御以谅及予也 其二","f":"五言古诗","c":["明月满庭幽，照我紫绮裘。","携手步明月，举白交相浮。","歌声浩无倪，飒飒松桂秋。","情随玉山倒，兴逐银河流。","五君顾我笑，真成鹏鴳游。"]},{"t":"同年会以新秋同年雅集为韵六首在会者顾佥宪溱刘佥宪乔余给谏经梁侍御世骠伦侍御以谅及予也 其三","f":"五言古诗","c":["粤客鸣丝桐，商声出瑶空。","始奏天地肃，再奏烟霜浓。","万里久为别，一尊今始同。","愿排十二翮，乘云扈飞龙。","三星在丹牖，可以明深衷。"]},{"t":"同年会以新秋同年雅集为韵六首在会者顾佥宪溱刘佥宪乔余给谏经梁侍御世骠伦侍御以谅及予也 其四","f":"五言古诗","c":["落落荆山璆，辉光烛中天。","举举同声友，五彩蔚相宣。","舒啸似鸾凤，摇笔生云烟。","玉壶酒易满，金枢月难圆。","对景不尽意，应嗟离别年。"]},{"t":"同年会以新秋同年雅集为韵六首在会者顾佥宪溱刘佥宪乔余给谏经梁侍御世骠伦侍御以谅及予也 其五","f":"五言古诗","c":["海濆集群彦，蜚英振风雅。","对月成七人，可以当作者。","顾予忝嘉招，瓦缶混琼斝。","天长去雁回，霜急飞梧下。","因之感摇落，忘情共陶写。"]},{"t":"同年会以新秋同年雅集为韵六首在会者顾佥宪溱刘佥宪乔余给谏经梁侍御世骠伦侍御以谅及予也 其六","f":"五言古诗","c":["碧山金琅玕，彩凤日翔集。","气谊有不同，咫尺宁相及。","主歌白驹劝，宾赋长鲸吸。","醉来愿天游，海月期俯拾。","褰衣渺然去，玉露沾涂湿。"]},{"t":"避暑矩洲书院与欧阳宪副汪少参黎伦二道长王主政同赋得矩字","f":"五言古诗","c":["招摇出西郭，宛辔临芳渚。","浮阳耀原隰，凯风动禾黍。","伊人不可见，中坻敞衡宇。","开轩游鲋适，卷幔宾鸿举。","顾我平生友，兹焉澹容与。","肃肃嘉树阴，行歌谢徒旅。","晞发散烦燠，蜚觞对灵雨。","好乐无太康，先民有遗矩。","襜帷难久淹，虹桥屡延伫。","嗟彼凫与雁，安知慕俦侣。"]},{"t":"秋日登镇海楼有作呈同游东庵徐宪副顾小泾刘鱼洲二佥宪","f":"五言古诗","c":["飞楼镇重溟，凿翠倚太清。","翩然彩云上，玉京连五城。","绮户环日月，丹梯殷雷霆。","秋风左右至，松桧皆金声。","留连紫霞赏，慷慨沧洲盟。","俯视几席下，茫茫尽尘缨。","鳌极莽安在，鲸波浩难平。"]},{"t":"游粤台与方棠陵伦右溪王象川伦彦蕃同赋得览字","f":"五言古诗","c":["精庐展良晤，胜地纡玄览。","舍舆蹑风磴，连袂度云埯。","粤台一以陟，远翠纷可揽。","潇潇雨初霁，冉冉日欲晻。","川光溢寥廓，野色开黯惨。","长谣出金石，英论照肝胆。","于焉谢羁束，何必理铅椠。","沉冥圣所珍，傲睨吾岂敢。","凭林悟荣悴，步壑玩流坎。","霸图有遗迹，因之动遐感。"]},{"t":"泰泉山中二首 其一","f":"五言古诗","c":["清晓迟来客，采芳从岵间。","织鸟忽飞动，苍松澹然间。","回顾丘中云，为我封柴关。","风吹唐棣花，灼灼翩哉翻。","惄焉抱饥渴，默坐愁烟山。"]},{"t":"泰泉山中二首 其二","f":"五言古诗","c":["流水出深涧，和风送啼鸟。","邂逅问樵客，薇蕨今多少。","行歌去不顾，倏在烟萝表。","鴳鹏各有适，耳目暂无扰。","缅怀区中人，营营自昏晓。"]},{"t":"赠吴白楼学士展墓归苏州","f":"五言古诗","c":["云海纵飞鳞，风林戢归翼。","委质赞王猷，胡乃怀家食。","端居揆物理，去住各有适。","而我违松楸，感叹靡朝夕。","肃穆戒徂两，天惠流丹极。","扬旌潞河外，税驾昆山侧。","缇光发芳甸，积雪成春泽。","应时须哲匠，因之感行色。","蒿宫承日耀，扈阁淩天辟。","戾矣母优游，皇情轸明德。"]},{"t":"六月于役西江感群公饯送有作","f":"五言古诗","c":["西江肃王命，冲炎枻兰舟。","陈臬有程期，将母不敢留。","轩车远相送，怅别情绸缪。","朝发沉珠浦，夕宿拾翠洲。","灵风吹柘旗，海天浩悠悠。","顾见肃肃羽，与波竞沉浮。","奇云混高山，丰草翳层丘。","自古负羁绁，我何怀殷忧。"]},{"t":"桂山","f":"五言古诗","c":["桂山何高高，高可肩岱宗。","秀色洒百粤，玄象开万峰。","恍如蹑孤凤，鸷鸟翩然从。","又如乘云槎，星潢浩溶溶。","风回玉琮琤，日射金玲珑。","珠树遍岩穴，仙圣留灵踪。","我欲辔羲和，佩结苍精龙。","峨冠朝太清，献此青芙蓉。","天长彩霞远，岁晚苍烟浓。","长啸倚磐石，笙竽满杉松。"]},{"t":"蒋少傅约游湘山阻雨不果招陈宋卿同宴湘皋书屋","f":"五言古诗","c":["湘山韫奇秀，浩然歌远游。","晞发思春阳，众芳薆曾丘。","星车夙言驾，六辔一何柔。","密云翳扶木，蜚雨洒道周。","亮无精诚格，皇穹浩悠悠。","弭节升公堂，绮筵罗玉羞。","晤言获饱德，良友副所求。","弹冠谢荐达，缓带成淹留。","黄鹄拚拚飞，所览在九州。","而我方永怀，山川空阻修。","自非采兰杜，何由结绸缪。","愿回烛龙照，庶以写我忧。"]},{"t":"道州何司空席上作","f":"五言古诗","c":["司空修禹绩，声华蔼孤骞。","皓皓荆山玉，虹光烛中天。","舂陵雨新霁，延我于丘樊。","卜筑在苍翠，架构依巑岏。","琴书一萧散，迟日满前轩。","和风泛烟际，有鸟鸣树间。","但觉清尊满，不知斟酌繁。","闲阶玩流水，疏篱见远山。","迟回步苔径，尽我平生言。"]},{"t":"三至轩为陈高吾中丞","f":"五言古诗","c":["提提高飞鸟，羽仪耀台端。","显显高吾公，德威为世观。","章江三弭节，不辞道路艰。","旄倪见公至，煦媮成欢颜。","章江东流去，城郭何郁盘。","台中启华构，桂户橑以兰。","祥鶤迎迢递，贺燕来翩翻。","岂为丽丹雘，芳馨良独难。","端居揆时运，晤言及湖山。","邂逅适我愿，怅别起长叹。"]},{"t":"浣俗轩五首为孙德谦 其一","f":"五言律诗","c":["冥鸿避矰缴，威凤栖琅玕。","呼汹埃壒中，谁能回羽翰。","浮荣逐不舍，乃见掇危患。","嗟古贤智人，天游恒闭关。"]},{"t":"洮水","f":"五言古诗","c":["驱车至洮阳，山川互盘纡。","淮南征战后，衣冠满如墟。","好鸟鸣青林，交交如自娱。","问女游何所，戢翼方踟蹰。","湘沅自南北，人生无定居。","桑土阴以雨，何由能拮据。","随阳愧鸿雁，逐美怜駏驉。","托身苟得所，不乐将焉如。"]},{"t":"衢村书屋三首为范宪副题 其一","f":"五言古诗","c":["天衢何坦坦，乃在东瓯阳。","和风荡原隰，戴胜鸣高桑。","课耕有馀闲，击缶歌慨慷。","世途方好径，而我循其常。","车马带倾覆，贫贱起膏粱。","不见陵陂麦，千载同感伤。"]},{"t":"衢村书屋三首为范宪副题 其二","f":"五言古诗","c":["天衢何坦坦，乃在东瓯侧。","中田敞衡宇，流水亘长陌。","逝者每如斯，守真在冲默。","好盈非所知，适意即安宅。","草木咸怀新，吾亦欣有得。","何必淩青冥，羡彼双飞翼。"]},{"t":"衢村书屋三首为范宪副题 其三","f":"五言古诗","c":["天衢何坦坦，乃在东瓯隅。","主人薄言归，豸服纡金朱。","杖策玩鱼鸟，下帷理琴书。","举俗爱芬华，谁能有此庐。","退耕混沮溺，出即卫皇舆。","白云蔚高山，浩然怀卷舒。"]},{"t":"严州孟太守去思亭","f":"五言古诗","c":["鱼龙召风雨，仁义徕蒸民。","有感岂不孚，所贵惟道真。","显允孟夫子，为邦善经纶。","阳和一以播，弦歌日莘莘。","至今舆人诵，恻恻怀二亲。","税履表遗爱，危亭瞰通津。","严山石齿齿，严水波鳞鳞。","水石会销歇，景耀垂千春。"]},{"t":"咏志二十首 其三","f":"五言古诗","c":["永夜闻商歌，迅响何袅袅。","凄清彻天地，游鯈出深沼。","岂无雅与南，所嗟知者少。","美人怅何许，遗世隔云表。","容辉耀日月，芬芳遍幽眇。","缄书道情素，愿寄西飞鸟。"]},{"t":"咏志二十首 其四","f":"五言古诗","c":["太仪运天地，日月相沉浮。","瀛海扬其波，巨鳌奠神州。","真宰每如兹，逝者何时休。","姬公避管蔡，仲尼涕衰周。","从事不及时，毫末成山丘。","鸡鸣盥漱初，营营何所求。"]},{"t":"咏志二十首 其五","f":"古风","c":["端居发深省，忳悒莫予语。","松乔炼金质，永为万象主。","褰裳从之游，淩霞頫环宇。","荧荧桃李花，??蜉蝣羽。","胡然耀人目，所得能几许。"]},{"t":"咏志二十首 其六","f":"五言律诗","c":["登楼望高山，密云结重霄。","农祥阻灵雨，四泽居然焦。","遥遥慰我心，青青见陵苕。","常恐鶗鴂至，众芳从此凋。"]},{"t":"咏志二十首 其七","f":"五言古诗","c":["今兹复来兹，愿言美禾麦。","饱食轻寸阴，何由崇明德。","日月驰光辉，中自为蝥贼。","天下归其仁，颜生惟自克。","芟除若不早，斤斧何嗟及。","今我长兢兢，雷声在渊默。"]},{"t":"咏志二十首 其八","f":"五言古诗","c":["城隅有奇树，昔为霜所枯。","东风旦夕至，枝条竞芬敷。","达官驾高马，万夫行避途。","威光夺霆电，意气倾皇都。","逢时恣嘘噏，政道犹蒲卢。","何哉仲尼志，浮海思乘桴。"]},{"t":"咏志二十首 其十二","f":"五言律诗","c":["崦嵫回羲轮，丹渊出明月。","天地为炉鏊，膏火相煎灭。","贤圣皆糟秕，兰玉岂芳洁。","咏彼苏门歌，抚运惭薄劣。"]},{"t":"咏志二十首 其十三","f":"五言古诗","c":["荧荧陌上花，濛濛丘中麻。","累累王侯冢，望望令人嗟。","六龙运元化，千古成尘沙。","吾闻浮丘公，驾鸿淩紫霞。","呼吸日月景，求用思无邪。","贵富岂必终，不见青陵瓜。"]},{"t":"咏志二十首 其十四","f":"五言律诗","c":["凛凛风霜厉，乔松有贞性。","物情无定端，巧言动人听。","掇蜂伤吉甫，拾煤眩孔圣。","隔垣闻斗声，曲直谁能竟。"]},{"t":"咏志二十首 其十五","f":"五言古诗","c":["轻车驾羸马，悠悠遵逵路。","东指泰山岑，苍然翳云雾。","愧无鲁阳力，何由照诚素。","徘徊彭城下，闻有桓魋墓。","朽骨灰已久，石椁安能固。","但见榛莽间，纵横走狐兔。"]},{"t":"咏志二十首 其十六","f":"五言古诗","c":["巍巍祝融峰，南临沅湘水。","弭节登其巅，天下犹敝屣。","仙者三五人，相招饮琼醴。","羽驾倏不见，丹书谁为启。","北归邯郸道，浮荣何足睨。"]},{"t":"咏志二十首 其十七","f":"五言古诗","c":["猗兰生深谷，脉脉含芳馨。","焉知涂上士，木槿同朝荣。","达人贵渊潜，岂用誇誉名。","中山有奇鸟，啾然凤皇鸣。","商风一夕至，毛羽空凋零。"]},{"t":"咏志二十首 其十八","f":"五言古诗","c":["阴阳迭升降，宇宙安所终。","谁从广成子，超然入无穷。","南山倚招摇，于焉息微躬。","白䓘释我劳，中谷挹条风。","南禺有鹓雏，愿言种梧桐。","岂知八桂树，乃在番隅东。"]},{"t":"咏志二十首 其十九","f":"五言古诗","c":["于嗟稷下士，驰声仁义场。","危冠切浮云，宽博为衣裳。","进退协矩度，调颜逾圭璋。","冲澹焉足保，利达乃其常。","岂若事畋猎，鸣镝驰高冈。","割解醉言归，百里无豺狼。"]},{"t":"陵祀纪行与姚维东殿撰","f":"五言古诗","c":["衔命承明庐，明发戒徒御。","逝将谒陵寝，川原莽驰骛。","浮阳映边堠，丰草被广路。","英寮谐所欢，联镳叙情素。","轻雷喧薄阴，燕山霭然莫。","前驱抗双旌，泮水导吾步。","息嚣谢人役，抚胜得天遇。","矞云吐金波，圆景在高树。","阴晴无定端，聚合良可悟。","与子永今夕，愿言丽金雘。"]},{"t":"送大理卿郑公讯狱如陕西","f":"五言古诗","c":["长飙彻炎暑，萧然燕冀秋。","天高万物肃，旷士怀国忧。","棘寺祇王命，严程戒华辀。","自闻帐下变，泾渭颓不流。","骋望五陵外，莽莽胡云愁。","原兽恶罔罗，时泽亮不周。","平反资淑问，及远遵壮猷。","君看鹰隼击，讵同鹏鴳游。","河梁阻西笑，怅别徒悠悠。"]},{"t":"读伯夷传有感","f":"五言古诗","c":["求仁本无怨，感义闻盍归。","清风满孤竹，首阳何巍巍。","拜诵孔孟言，永矣旭日辉。","何哉马迁传，复与周纪违。","左右兵义士，采取西山薇。","充蚓亦土毛，否臧非德威。","武城二三策，抚卷悲畴依。"]},{"t":"卧暄二首 其一","f":"五言古诗","c":["鲁麟获已久，礼乐日以新。","大化随浪迁，鬒变不待人。","负暄东荣下，泯默安形神。","弱子左右戏，欹我头上巾。","倦且效龙卧，寤言为鸟伸。","陶情举尘爵，觉有羲皇春。"]},{"t":"卧暄二首 其二","f":"五言古诗","c":["乃者庞德公，耦耕栖鹿门。","荆棘视城府，轶驾谁能轩。","吾庐在通逵，车马时往还。","抱独以混世，曲肱道终存。","采芳息尘务，观书忘市喧。","委和在我躬，悠然感乾坤。"]},{"t":"调鹿出郊谢徐方伯惠酒","f":"五言古诗","c":["调鹿适林野，就萍荒水滨。","水流日东逝，春序犹依辰。","倾耳无市声，在目多乱云。","寒岩寂如冬，古木相与亲。","有酒来南州，连觞饮其醇。","班荆亦县榻，素心良已勤。","醉来陟高冈，万化皆呈新。","陶然牵鹿归，放浪存吾真。"]},{"t":"春日草堂雅集分得桥字","f":"五言古诗","c":["浪迹栖烟山，采芳混渔樵。","东风随我行，不遣瑶草凋。","招携二三子，鸾歌蹑虹桥。","弦琴坐白石，万壑生神飙。","真乐岂在酒，所贵能久要。","长松阅千霜，飞萝拂丹霄。","好鸟枝间鸣，飞去枝摇摇。","后夜弄云月，相期挥碧寥。"]},{"t":"南园三忠祠分韵得院字","f":"五言古诗","c":["鶗鴂鸣素商，寒威起松院。","疾风被野草，日觉群芳变。","驱车游南园，云构蔚霞绚。","桓桓三君子，万代谅如见。","呜呼炎宋阸，中华駴龙战。","金陵生厉阶，雨雪集维霰。","谁令王多士，蔼蔼甘为媛。","黄河归紫塞，久矣忘燕汴。","艮岳成纥干，湖山尚芳宴。","荆淮日以蹇，斡难焰方煽。","辟彼强弩末，鲁缟何由穿。","胡尘暗三极，朔气瀰九县。","力断匈奴臂，虚发天山箭。","长缨竟莫系，大义赫霆电。","鲸涛浩凄恻，中有慈元殿。","楼船载国沉，辉光与天炫。","群龙翼日飞，陨首犹怀恋。","哀哉田横岛，不见华元面。","燕市望苍梧，哀歌泪如线。","吾闻贲隅都，卉服禹所甸。","通非嬴政始，迹是虞皇践。","厓门对韶石，高冈两葱茜。","危亡人所怜，明良吾所羡。","缅怀南薰弦，宏达四门荐。","言开城且闭，国步何由奠。","有道四夷守，无为万情忭。","勿以绮罗贵，而谓丝麻贱。","勿以便辟亲，而可疏忠彦。","徒糜磨钝资，见此金百炼。","愀然拜祠下，谁能愧缨弁。"]},{"t":"草堂与诸生二首 其一","f":"五言古诗","c":["吾爱秋日佳，萧然适我怀。","良朋日相觌，众芳未云衰。","朱光覃雾泽，绿水间云涯。","中塘集凫雁，接翼鸣喈喈。","蜻蜓振其羽，翾飞亦徘徊。","物色每如此，会盍何当乖。","九罭得鲂鲤，薄言同举杯。","虽无钟石奏，意志中自谐。","巢居托松柏，迟莫犹能来。"]},{"t":"草堂与诸生二首 其二","f":"五言古诗","c":["采菊登高冈，崎岖行苦饥。","顾见坂田中，粲粲金满枝。","芳馨不在远，中心胡乃遗。","缅怀王子乔，弃俗乘云螭。","寄言青鸾鸟，瑶华杳难期。","蹠实会有程，排虚非所知。","县圃不可即，仙夫诚已希。","白榆何历历，无根自相依。","霣地硁然石，乃为人所嗤。"]},{"t":"喜晴四首 其一","f":"五言古诗","c":["解缨息尘驾，复此园田居。","昊穹靳白日，后土成沮洳。","今晨雨初霁，良怀浩然舒。","玄蝉鸣灌木，高鸿淩太虚。","飘风卷蓬藋，奇岑映吾庐。","挥杯适真性，行歌随所如。"]},{"t":"喜晴四首 其二","f":"五言古诗","c":["离离原上苗，混混随流波。","久无持禄资，所望良已多。","农人速吾驾，及此风日和。","南畴理荒秽，劳者相与歌。","间关林中鸟，窈窕陌上华。","生态足娱悦，岂惮重荷锄。"]},{"t":"喜晴四首 其三","f":"五言古诗","c":["散步衡茅下，万木环芳洲。","白鹭矫其羽，清飙送回流。","云何雨无正，雅违林与丘。","肃肃天界澄，泱泱川潢收。","庶物露其生，景风亦和柔。","及辰盍朋好，浊醪相劝酬。","清言闲长谣，冥会臻神幽。","巍巍紫芝翁，千载相为谋。","缅彼商山时，为乐有此不。","委形宇宙内，纵浪将焉求。"]},{"t":"喜晴四首 其四","f":"五言古诗","c":["端居抚灵化，流幻成阴晴。","晨鸡奏天色，起觉衾绸轻。","籓篱未云树，溪壑浩已盈。","抱独有馀豫，焉知世上情。","邂逅适所愿，丹葵耀其英。","摇摇庭绿中，有鸟时一鸣。","物色每如此，聊以观我生。"]},{"t":"赠郭循夫北上","f":"五言古诗","c":["天池集高凤，炎峤起潜虬。","君子崇令德，及时建芳猷。","眩璧乃天损，闭关非世求。","修名如有立，千载扬嫭修。","兹行寿亲闱，明将观宸旒。","壮志丽阳春，健翮淩素秋。","出宿珠海湄，弭棹龙江流。","蹇予愧德邻，坎壈栖沧洲。","念子清庙姿，温温古天球。","赤手扶天步，丹心开圣谋。","仗剑自兹别，吾道何悠悠。"]},{"t":"泰泉纪游次京兆陈公韵","f":"五言古诗","c":["飞盖龙丘阳，投辖鹤台阴。","泰泉閟真源，乘秋可高寻。","烟萝开野酌，寒翠生衣襟。","采蒲历窈窕，怀菊经崎嵚。","安期与崔公，千载同素心。","云螭一以驾，碧山苔藓深。","松风如有情，飋飋瑶华音。","因之抚元化，庶以求吾忱。","于穆谅在兹，鱼鸟自飞沉。","晤言得真筌，万象居然森。","白驹倏难絷，伫望空遥岑。"]},{"t":"春郊感兴","f":"五言古诗","c":["升彼青门墟，绵绵生之瓜。","策马者谁子，容辉闲且都。","扬镳不相顾，我且芸荷锄。","但使固根蒂，宁无以为家。","姚冶人所羡，沉冥道为徒。","漂摇不可食，叹息林中花。"]},{"t":"冬日与子乾惟鉴兄弟游泰泉访鹤舒台","f":"五言古诗","c":["天池集南翼，帝车回北衡。","芳草寒未歇，潦川澹犹清。","晏阴日夕起，郁抱何由平。","溯风肃徂轸，陟云延友生。","周遭度玄渚，纡徐搴落英。","晨霞散馀绚，倏忽淩虚明。","虬松移翠葆，虹涧流金声。","辕马何萧萧，谷鸟亦嘤嘤。","蕴真效龙蠖，抚化忘将迎。","隆墀一永叹，远壑浩自盈。","缅惟辽海鹤，载彼瑶台笙。","邈矣安期子，乃垂千载名。"]},{"t":"草堂踏月二首 其一","f":"五言古诗","c":["飞鞅登古台，抱膝睎天路。","紫微何苍苍，玄化莽回互。","阳鸟来不息，江南正霜露。","飘风振虚壑，海涛自吞吐。","世涂渺无端，玉衡有常度。","僾焉怀古今，行歌写衷素。"]},{"t":"草堂踏月二首 其二","f":"五言古诗","c":["逍遥水上鹭，倏忽云中翔。","阜螽跃衰草，亦知明月光。","群动夜不息，玄天函百昌。","二虫何为尔，高下自有常。","纵浪大化中，洪涛浩茫茫。","自非松柏姿，日夕焜以黄。","慨彼风中叶，悠悠安所将。"]},{"t":"陈京兆浮丘心远亭分得落字","f":"五言古诗","c":["浮丘倚阑渚，郁水环山郭。","中流结衡宇，炎歊尽销落。","伊人天与游，委怀合冲漠。","投簪隐朝市，緤组尹京洛。","卷舒贵自我，虞罗岂云获。","丘隅协鸟性，濠梁遂鱼乐。","翛然驰寸心，万古纷回薄。","高云映樽俎，凉雨洒葵藿。","陶情良在兹，抚物欣有托。","愿为鸿与鹄，相将翔寥廓。"]},{"t":"三穷啚诗时九首为周侍御同年 其一","f":"五言古诗","c":["缝裳须用缄，和瑟须鸣琴。","芳年才十七，与君结同心。","譬彼梧桐枝，萋萋倚云岑。","岂知双鸾曲，翻成孤鹄吟。","幽灯照穗帷，凄恻谁能禁。"]},{"t":"三穷啚诗时九首为周侍御同年 其二","f":"五言古诗","c":["芙蓉含早霜，亭亭立清沚。","中虽怀苦心，所幸有莲子。","结根彻黄泉，不惜为君死。","抚膺顾遗腹，一脉尚存此。","雌雄嗟未判，血泪徒盈眦。"]},{"t":"三穷啚诗时九首为周侍御同年 其三","f":"五言古诗","c":["逝水无回波，断发不返根。","燕好甫三载，音容俄九原。","高堂有舅姑，谁与供晨昏。","悬弧倘不遂，妾身安用存。","恸哭视苍天，悠悠竟何言。"]},{"t":"三穷啚诗时九首为周侍御同年 其四","f":"五言古诗","c":["力田终有获，绩纺终成布。","谁言迈种德，一绝如零露。","越月兼逾旬，祥驹自天鹜。","尊嫜惊且喜，风骨俨如父。","提携方自兹，陟岵增怀慕。"]},{"t":"三穷啚诗时九首为周侍御同年 其五","f":"五言古诗","c":["衡茅勿云蔀，闯门当见天。","孩提勿云小，宗祏当绵延。","弥月拜舅姑，缟素登堂前。","嗟哉老无子，仗尔娱暮年。","尔孤不识父，呱呱泪如泉。"]},{"t":"三穷啚诗时九首为周侍御同年 其六","f":"五言古诗","c":["绵绵孤生瓞，子母相钩带。","旦夕勤护持，惧为风雪害。","周宗已磬石，孟母犹教诫。","乌啼书幌月，鸣机答虚籁。","旌弓方骍骍，奋志从此迈。"]},{"t":"三穷啚诗时九首为周侍御同年 其七","f":"五言古诗","c":["霜蹄肃皇路，云翼腾天池。","旭日送檐鹊，秋风飘桂枝。","憟憟未亡人，幸此光荣时。","驱车向京洛，宾兴有程期。","山川复悠邈，离忧良在兹。"]},{"t":"三穷啚诗时九首为周侍御同年 其八","f":"五言古诗","c":["北堂有慈竹，孙枝淩云起。","孤儿复抱子，兰阶映瑶珥。","四世萃一门，九原闻亦喜。","割鲜开锦席，犀钱一何绮。","沉忧天所释，树萱乃徒尔。"]},{"t":"三穷啚诗时九首为周侍御同年 其九","f":"五言古诗","c":["赤霄坦如底，骢马高腾骧。","顾见风中木，戚戚犹惨伤。","缄情达枫陛，鸾凤森翱翔。","巍峨表宅里，恩渥光泉乡。","我矢三穷诗，天道固有常。"]},{"t":"李番禺席上赋","f":"五言古诗","c":["兔丝依松柏，引蔓淩云天。","文明席佳会，弹冠怀昔年。","邵生圭组时，宁知在瓜田。","陈力审所就，周任有遗言。","弛张道所贵，辟彼望与弦。","华筵有明牧，飞觚罗豆笾。","坎坎鼓干舞，矫矫成飞鸾。","醉来命驾起，斗柄随车还。","浮云翳金枢，望舒閟复宣。","曲肱谢鞶带，皎日当盈前。","卷舒合龙蠖，庶以道自全。","解忧适真性，杜康无乃贤。"]},{"t":"新秋登玄览台分韵得峰字","f":"五言古诗","c":["高台临万峰，陆海开芙蓉。","玩弄忘日夕，凉翠生心胸。","载酒步云壑，豪客纷来从。","是时秋序肃，天空雁嗈嗈。","萝月挂霜镜，枫江驰玉龙。","醉来藉瑶草，舄外闻烟钟。","振衣划然啸，鸾声落长松。","悬知千载后，怀吾霞上踪。"]},{"t":"郭中丞半隐园迎春雅集","f":"五言古诗","c":["振羽择芚木，育鳞资澄渊。","岂知历台馆，歘焉接林泉。","苍郊迓春序，玄圃敞琼筵。","结构崇雅朴，高情属云天。","环亭列翠陌，凿沼引璿源。","飞觞坐秩秩，曲水闻涓涓。","令严榛莽辟，仁铺桃李妍。","壮节挺松竹，芳奠播兰荃。","和风动棂箔，秀色通漪涟。","养素成半隐，忘言飞泳间。","祥鶤仰迢递，贺燕来连翩。","蹇予谐夙尚，临眺心悠然。"]},{"t":"紫云观易台为薛吏部题","f":"五言古诗","c":["鸣鹤振远皋，潜龙耀灵渊。","懿彼庐山曲，栖兹高蹈贤。","紫云结兰若，孤峰霭炉烟。","筑台躆幽胜，迎风概中天。","侁侁衾佩集，琐琐圭符捐。","观易研众妙，洗心由浩然。","开轩丹巘入，承宇青霞连。","编韦会至赜，舍瑟成真筌。","虽生姬孔后，已悟羲皇前。","汇征谢嘉遁，道以时屡迁。","垂光虹蜺上，永怀丘壑年。"]},{"t":"马上偶述","f":"七言绝句","c":["南风吹沙作黄雾，紫骝嘶踏东华路。","停镳引领意悄然，宫树离离闻杜鹃。"]},{"t":"哀竻园亡弟傅保及开儿玄儿瘗处","f":"七言律诗","c":["琼楼十二秋无声，庞眉书客乘云軿。","佩环窅窅不知处，碧鸡啼烟素蟾语。","人间泪作荆花雨，绷雏伊啮夜台旅。","白杨酸风吹草花，锦囊馀春散寰宇。"]},{"t":"虚谷歌赠郭先生","f":"七言律诗","c":["苍碧相围云接山，结庐中谷心自闲。","深林无人野芳发，坐啸行歌响相答。","白驹仰秣瑶瑟希，足音不闻孤掩扉。","翛然默坐圜虚里，万壑无声月如水。"]},{"t":"演骚赠舫丘日者","f":"楚辞体","c":["朝绁余马登舫丘。","攀揽桂枝聊淹留。","翠涛?瀁如中流。","木兰为枻沙棠舟。","丘中人兮清且修。","逍遥水裔骖飞虬。","扬灵弭节光蚴蟉。","芙蓉衣裳纕以兰。","翠旌孔盖翩哉翻。","冶容妍迹无定端。","琼晖藻景摇沦澜。","云霓晻霭矫七盘。","褰帷独往河之干。","璜琚纂组缟与纨。","鬋鬒曼睩良可欢。","含商咀宫曲未殚。","浩倡眇语谁不叹。","飘然乘蹻徕湘岷。","乘鹥御霞析木津。","笑翻碧寥开帝阍。","指麾黔羸星斗鹑。","摄提孟陬窥玉衡。","群灵丰丰扈且屯。","冲风夕起波龙鳞。","众芳纷糅穷极研。","滂心嫭目符乾坤。","然疑不作孚以言。","招摇佩履何仙仙。","九州寿妖耿在天。","世途埃壒无庸贤。","飞鸾在笯鸮乃骞。","蹻蹠没牖原湛渊。","鞠歌问子胡为然。"]},{"t":"忆妾行次曾于阳韵","f":"七言古诗","c":["忆妾别君大河口，泪洒苍天誓相守。","船旁橹声如妾啼，船头水声作牛吼。","君家富压咸阳人，玉楼金屋娇芳春。","鸾杯凤管度朝莫，辞家乃与风涛亲。","风涛汹汹愿君返，幽幔疏灯耿孤馆。","剔残兰灺月犹在，落尽棠梨春不管。","脉脉停机待君至，锦织愁文宛将备。","时凭镜听卜归期，好语初同俄尔异。","念君相从多贾人，相时射利心胡秦。","念君交游多媚子，外平中险如河水。","君不为忧反为喜，安得长绳系君趾。","朝来蟢子罥罗帏，柳外垂鞭信马归。","山眉云鬓为君理，一曲尊前金缕衣。"]},{"t":"梦游仙吟","f":"七言古诗","c":["大罗天高高众天，梦乘凤车挥麟鞭。","扪奎历轸入超忽，下视齐州空九烟。","天真皇人见我笑，示我丹诠启玄窍。","玄之又玄言莫传，玄以言传非道妙。","拜领天诀葆天和，灵宝在体消群魔。","斡旋杓斗酌元气，坐令厄劫归无何。","郁轮驾我出东极，呼取星辰拥瑶舄。","罡风耳畔吹素云，瑞叶琪花满层碧。"]},{"t":"高吟行赠别杨惟仁","f":"七言古诗","c":["绀园碧院花木深，招风呼月长相寻。","与君对酌缥玉酒，酒阑击剑时高吟。","栖鸦翻露月当席，老鹤警霜风满林。","尊前不觉肝胆露，铜龙历历天沉沉。","看君意气何萧爽，玉井冰壶坐中朗。","但记欢娱有岁年，岂知携别生俄响。","太行云接晋水滨，秋花锦石相鲜新。","君持使节往问津，揽环结佩犹逡巡。","逡巡未已拂鞭去，河桥晓日新丰树。","紫骝跑空尘作雨，弦筈分违遽如许，弹冠徯君奉明主。"]},{"t":"月夜登王子小楼放歌","f":"七言古诗","c":["西山萧爽掌与平，绛河溯月秋有声。","白榆丹桂何历历，登楼一坐心眼明。","王郎爱客歌侑觞，倡酬况是词场英。","疏钟近户风漠漠，杂花绕径云冥冥。","剥梨举火讶斗落，园鹤时作摩天鸣。","酒酣为子歌慷慨，轩冕且付形骸外。","车如鸡栖走蹗蹗，富贵何如取酣快。","鲲鹏肯怯天池远，虾鳝只见蹄涔大。","朝市于今嫌我真，旧山尚觉长镵在。","王郎为我添浊醪，相逢能几尊前豪。","读书徒自吝驹隙，涉世无乃纷牛毛。","鸡鸣庭树宿鹭起，东方皛皛须臾高。"]},{"t":"厅前槐树歌为少傅蒋公赋","f":"七言古诗","c":["厅前古槐谁所植，藤萝到天云覆地。","磊落似是英雄姿，扶持讵识神明意。","父老相传百岁馀，共瞻羽葆听笙竽。","森森不数月中桂，历历还同天上榆。","离奇葱茜真堪忆，主人久作瀛洲客。","梦里花黄桂水秋，望中云净湘山碧。","当时燕坐凝妙香，捲帘对尔清昼长。","萧瑟恍闻雷雨入，夭矫欲逐蛟龙翔。","鹓池亦有当时树，不是当时旧游处。","金莲夜自九霄归，玉佩晨从三殿去。","遂令函夏歌时雍，植槐种德将无同。","花开叶脱自时序，太虚无语昭玄功。","更闻来使传消息，苍苍不老当年色。","白鹿贞松只自长，青牛文梓宁论直。","槐乎槐乎无与伦，力排摇落开鸿钧。","在昔海棕逢杜甫，尚欲移栽向北宸。"]},{"t":"观柯学士手植双柏有感追次西涯韵","f":"七言古诗","c":["双柏亭亭翠成匝，鹓池六月秋萧飒。","柯仙仙去馀芳声，手泽犹存敢轻狎。","霜皮露叶几经年，崔嵬欲与云霄肩。","维持本自荷真宰，典刑尚想司文权。","蓊葱色竞西山爽，奰屃势凭鳌极长。","夜寒杓斗入掩映，昼永珍禽鸣下上。","孤高迥与尘滓隔，劲直不为寻尺枉。","封植勤渠信有人，振屟岩廓接清响。","三槐当日期三公，至今名与旭日东。","燕诒只为孙子计，何以为国收群龙。","六桧有堂昭斧钺，妨贤无乃羞儿童。","广储榱桷作时用，此事自足馨无穷。","援琴一奏高山调，柏也为我呼天风。"]},{"t":"题画猫为丁大章","f":"七言古诗","c":["黄金台前白日孤，终风吹雨泥长途。","流光向我马上徂，归来客舍一事无。","兰镫荧荧明槁梧，中夜起坐思江湖。","有鼠有鼠繁有徒，嗷嗷橐中视则逋。","尔黠惊倒眉山苏，买鱼穿柳无狸奴。","眼中狸奴不可呼，击剑为尔歌呜呜。"]},{"t":"刘与清尚书夫妇八十寿歌","f":"七言古诗","c":["吴门八月天宇凉，狐南婺北相辉光。","洞庭琪花满遥碧，震泽万顷来银潢。","蓬瀛恍惚落人世，君家翁姥如刘纲。","方瞳如月鬓如雪，意者紫府传丹方。","桃都瑶水入图画，苍精云旗开渺茫。","满堂宾客正繁会，鹍弦龙管催行觞。","膝前骥子森起舞，绕阶玉树参差长。","酣来历历话畴昔，忆从花县升岩廊。","端冕青春静鹓鹭，埋轮白日销豺狼。","至今人诵大司寇，兰台棘寺多风霜。","碧油幢底足氛垢，挂冠归去鲈鱼乡。","春秋久阅椿更老，冰雪侵淩萱自芳。","翁今八秩姥望九，耳闻尧舜新垂裳。","万年至治付鼓腹，摩挲老眼窥沧桑。"]},{"t":"三芳行","f":"七言古诗","c":["蜀江鱼龙吹混茫，淩乘倒景浮苍苍。","雷骞电跃不可测，惊涛势欲摇雍梁。","冲撞未已潋为碧，万里一色如天长。","川后阳侯净不发，水花云叶参差光。","鸟疑明镜不敢下，我泛扁舟如燕翔。","此时水面光怪出，有石有石随兰桨。","天书神篆炯可识，赤日下照金琳琅。","三芳有兆自兹始，天岂有意登贤良。","当时一梦落洲渚，觉来渔唱空斜阳。","红衣翠带散秋色，江木策策鸣烟霜。","黑甜乡中尽乌有，境投真妄心俱忘。","岂知此梦太神巧，于嗟三仲今联芳。","于嗟三仲今联芳，高名合沓登岩廊。","黄金系肘笏满床，紫荆花发春醪香。","花前高歌嘉乐张，二十五丝招凤凰。","凤凰雍雍帝道昌，矢心共补山龙裳。","嗟石可转海可桑，流芳会与天无疆。"]},{"t":"燕歌行寿陆宪副","f":"七言古诗","c":["朔风萧萧越水波，碧洲硉兀云嵯峨。","琼轩珠缀临丹阿，玉杯锦席纷绮罗。","吹竽击筑奏云和，逶迤鸾舞杂凤歌。","态妍曲妙体傞傞，微闻芗泽飘芰荷。","娟娟兰玉连枝柯，银鱼朱绂光荡摩。","宾从鞍马金盘陀，摇舷载酒鸣鹳鹅。","梅花雪落覆绿莎，嘤嘤谷鸟啼松萝。","觥筹淩乱星转河，当空璧月扬素蛾。","豸冠一笑鹤发皤，朱火照耀苍颜酡。","千金为寿岂云多，岁岁年年奈乐何。"]},{"t":"九疑篇纪游作","f":"七言古诗","c":["九疑连蜷接南斗，顾视群山骏奔走。","三湘秀色如虹横，万壑虚涛作雷吼。","雷吼虹横自古今，徭吹牧唱愁人心。","春秋牲玉荐明祀，褰帷谁复来登临。","金侯自是循良者，夙驾行春度平野。","桃花开落讼庭静，邀我寻幽舜祠下。","我来晓逐东风行，千树万树皆流莺。","六鳌蹙沓谷神动，仿佛箾韶天际迎。","天际相携蹑飞步，自笑登高未能赋。","轻袂飘飘萦紫氛，曲磴盘盘出苍雾。","苍雾紫氛长不消，木石欹侧鹿豕骄。","重华灵坟莽何处，英娥泪竹空萧萧。","此邦路隔关河外，岂有鸣条葬炎海。","倦勤已矣复来巡，抱乌弓者曾谁在。","呜呼野死胡足稽，金舆芜没山鸟啼。","陟方之说误千古，捐佩无言春日西。","日西秉烛斜岩款，笑向全侯嫌昼短。","多露惊看征旆湿，灵风忽送清笳满。","归来祠下月微明，飒飒垂裳如有声。","明朝拜别巾车去，更听流莺消客情。"]},{"t":"都城引送陈七表兄之横浦","f":"七言古诗","c":["都城十月尘如山，朔风吹雪行路难。","侵晨我已驾马出，薄暮始随栖鸟还。","下马入门见兄到，张灯与兄拂巾帽。","三年不得奉颜色，一觞且共开怀抱。","兄之大父我外翁，声价昔震蓬莱宫。","家有图书出秘府，兄能取次藏胸中。","此时吐露惟衷款，笑谈衮衮良夜短。","促膝翻愁朱火尽，萦窗忽见金波满。","相看本是同根生，世态悠悠安足评。","天涯未易输肝肺，海内谁云皆弟兄。","我随玉节别兄去，荆门梦渚烟中树。","陇头两见秋云飞，又向都城得相聚。","都城阁道从天开，虎豹为关鸾凤台。","簪缨无数不敢到，兄以材贤长往来。","兄辞家久常思母，天遣为丞向横浦。","万树梅花道板舆，一水何曾隔乡土。","兄今十月出都城，风景如前非合并。","孤舟明日河桥路，微雨萧萧无限情。"]},{"t":"秋夜吟赠别信臣士畴二同馆","f":"七言古诗","c":["霜清月皎南雁翔，海怀霞想驰故乡。","登舻浩歌秋夜长，鸣琴击筑飞玉觞。","葭下紫鳞低复昂，踟蹰执手上河梁，临伊望洛回中肠。","与子同裯星岁多，猎精守玄栖禁坡。","龙骥翼翼金盘陀，越阡度陌相经过，笑谈如天悬九河。","骞鹏舞凤鸣蛟鼍，宿昔之乐今则那。","南箕北斗光有烂，别子良易会日难。","自从委佩辞鹓鸾，建我藩辅命自天。","扬灵击汰逾江山，绿水浩浩云漫漫，岁月婉晚多苦颜。","长河有洲山有薇，我徂于征忘渴饥，倚门何叹叹式微。","紫燕踏云天上归，弹冠振缨志莫违。","我且与子娱春晖，临岐赍咨何所为。"]},{"t":"中宿篇游清远峡山寺作","f":"七言古诗","c":["中宿之山吁壮哉，山巅兰若峥嵘开。","两崖夹束怒涛涌，扃钥二曜走万雷。","林壑苍苍莽交互，北梦南云入回顾。","帝子来游不记春，柔橹轻鸥自朝暮。","我来披翠上上方，忆从萝幌闻妙香。","旧游回首十年梦，天风吹我芙蓉裳。","山僧与话尽茫昧，玉环金锁今何在。","半云亭子故依然，谁构曾轩屹相对。","曲磴盘盘穷眼瀰，眼眵足趼不自知。","满前丛竹舞风叶，映水恐是青蛟螭。","崎岖西转穿茆入，和光洞古烟光湿。","烛龙下照开积阴，仰听玄蝉啸风急。","起来燕坐形神清，鱼鸟嬉恬如有情。","忽闻云外暮钟动，殷殷似斗飞泉鸣。","攀条尚欲搴琼蕊，荷锸还思寻石髓。","赏馀兴极且登舻，月出金枢浩如洗。","向来探历无乃劳，凭虚舒笑天为高。","岩居川观夙所愿，世间龙蠖真毫毛。","江干击汰美清夜，与客开尊共倾泻。","且置万事聊歌呼，飞来之说知有无。"]},{"t":"端午张黄门燕集分韵得细字","f":"七言古诗","c":["张君苍髯如拥戟，起家龙泉重当世。","我昔幽栖祇树林，伦郎视我犹兄弟。","君来奋髯发高论，意气豪雄略文艺。","尊前击剑星斗动，月下放歌鸾鹤唳。","伦郎一去未言返，招隐无人赋丛桂。","聚散于今又一时，赤墀青琐多留滞。","长安咫尺不相见，松筠寂寞门长闭。","端午开尊延我曹，宾从过逢得偕诣。","芳糈清酤溢筵几，艾叶榴花满庭砌。","兴酣徙倚前荣下，促膝相欢谈往岁。","火云消尽暮天碧，空翠时时落巾袂。","世事追思尽萍梗，人生那得无根蒂。","嗟我亦是江湖人，感时历历惭匡济。","翠管银罂不可求，细葛香罗谁复制。","阄诗怀古三叹息，呜呼盛事何由继。","燕俗到今传角黍，湘累终古伤兰蕙。","黄金高台未萧瑟，南薰古殿犹佳丽。","盍簪乍可开怀抱，弹冠且莫誇遭际。","张君爱客不知暑，执热传觞转容裔。","酒阑挥手谢君去，纤月当空凯风细。"]},{"t":"瓶山小隐为胡少参","f":"七言古诗","c":["鸿钧幽眑不可见，眼前突兀皆灵踪。","有山如瓶翠当户，青天不数金芙蓉。","摩挲叹尔谁所铸，欲诘真宰嗟无从。","颇闻混茫胚尔质，列缺辟历锤成峰。","汲井可以及千里，储粟岂特逾万钟。","斗杓挹酒尔堪贮，嗒然默默知有容。","临溪仙人顾尔笑，若作曲蘖烦天翁。","烟霏护足肖壶首，日月照背成龟蒙。","巨灵挈之不假器，阴阳为炭何年镕。","分江济渴泽可注，守口铭座云长封。","世途尘鞅未能掉，对此吸秀清心胸。","仙露往往集鸾鹤，元气浩浩流杉松。","药房兰室敞天地，练要服食忘春冬。","粤山霞侣傥相见，与尔共佩苍精龙。"]},{"t":"剑歌行发桂林作","f":"七言古诗","c":["对酒剑歌行路难，墨云当天凝作山。","渴龙怒卷海涛立，空林飒飒如人入。","跳珠白雨腾玄间，回看平陆皆成滩。","仆夫戒予行莫急，苍皇中道何嗟及。","停车拱极之飞楼，紫骝不嘶旌旆愁。","踆乌扬光忽垂地，驿吏冲泥亦来至。","翼予乘霁上前途，斧薪作糜勤仆夫。","逡巡饭罢出林薄，麦雉引雏鸣角角。"]},{"t":"十载行二首赠王子崇 其一","f":"七言古诗","c":["十载之行我在燕，与君相好随莺迁。","十载之后我归粤，与君相好听莺别。","听莺走马朝玉京，玉京十二楼五城。","山龙垂衣御紫清，羡君输丹达天扃。","彤云缥渺拂绮楹，手持金镜耀日明。","圣皇得一天下贞，寿万万岁垂鸿名。"]},{"t":"十载行二首赠王子崇 其二","f":"七言古诗","c":["十载之前与君同，弹冠谢策明光宫。","十载之后与君异，薜萝幽栖谢朝市。","燕雀岂知乌鸟情，麋鹿耻随龙虎争。","浩然溟涬同此生，羡君衣彩天边行。","三十六竽彩凤鸣，东王西母连云軿。","圣皇达孝天下平，寿万万年流颂声。"]},{"t":"送龚少参归田三首 其一","f":"七言古诗","c":["我之田矣东之皋，公之出矣攀倪旄，爱而不见心烦劳。","停云望久雨声歇，松壑潇潇生夜涛。"]},{"t":"送龚少参归田三首 其二","f":"七言古诗","c":["公之往矣南之浦，我之歌矣振林莽，帝车无声烛龙舞。","昨晴今雨庸讵知，眼前浮云何足数。"]},{"t":"送龚少参归田三首 其三","f":"七言古诗","c":["衡门反锁春泥深，蔷薇花开明素琴，公之行矣成孤吟。","十年离合叹岐路，脉脉长江空此心。"]},{"t":"中秋登楼赏月分得宵字","f":"七言古诗","c":["彤楼十二连斗杓，层轩珠缀临岧峣。","象筵绮俎相招邀，绣茵文毂停华镳。","兕觥屡酌银烛销，矞云斐亹开碧寥。","圆晖炯若英琼瑶，出自金枢行玉宵。","重轮五色成锦幖，兔宫桂斧如可徼。","霓裳羯鼓和仙韶，浩倡妙舞生神飙。","縠罗山立香泽飘，素娥青女空复娇。","含颦流盻心志摇，袨装重整双凤翘。","夜阑悲翠栖兰苕，清光难盈花易凋。","人生行乐须久要，愿言百岁同今宵。"]},{"t":"瑟调曲四首寿陈天游府尹 其一","f":"七言古诗","c":["月蟾临户星鸟翔，开春发岁舒青阳。","笙鸣瑟作嘉乐张，讴和阳阿协宫商。","帝台缥玉盈鹤觞，绮肴兰俎珍屑香。","振缨峨弁纷满堂，错衡琼毂鸣骊黄。","翡帷翠幕华烛光，朱明承夜乐未央。","缓声浩倡寿无疆，岁岁年年长乐康。"]},{"t":"瑟调曲四首寿陈天游府尹 其二","f":"七言古诗","c":["碧瞳绿发天与龄，绯衣绣黻临紫京。","郁葱佳气钟山明，虎符鱼钥开夜城。","长江如带流德声，五龙云卧珠海清。","浮丘羽人授黄庭，苍松丹桂冬不蘦。","乾坤一气魄载营，齐光日月餐玉英。","开轩献寿宝瑟鸣，岁岁年年长合并。"]},{"t":"瑟调曲四首寿陈天游府尹 其三","f":"七言古诗","c":["和风习习吹华池，瑶阶玉树兰满枝。","彩衣屡舞鸿鹄移，齐笙赵瑟荐羽卮。","雕盘缤纷翠釜驰，五音繁会陈雅诗。","群灵丰丰驻云螭，鸾回鹤跱吹参差。","清弹妙舞坐忘疲，河翻月堕星斗稀。","共言为乐不可支，岁岁年年寿无期。"]},{"t":"瑟调曲四首寿陈天游府尹 其四","f":"楚辞体","c":["天阍洞开何嵯峨，太仪发轫升紫霞。","麟车翩翩鸣凤珂，仙之人兮纷如麻。","俯望南极行且歌，彤狐瑞彩映若华。","九阳晞目炯不遐，注我锦席生黄芽。","千年桃实如枣瓜，荐以云液朱颜酡。","琅璈柯笛参灵鼍，岁岁年年仙赏多。"]},{"t":"腊后登谪仙楼","f":"七言古诗","c":["任城城南楼突兀，雪花飞后梅花出。","云里朔冰如白虹，东风旦夕来披拂。","金龟换酒忆当年，鼙鼓几曾惊醉眠。","夜郎回望长安日，济水不到峨眉天。","鉴湖鲸月亦安在，但见黄河入沧海。","我来大笑歌阳春，洪波渺渺开龙鳞。"]},{"t":"黄月溪太守归自京师得脱风涛之险携酒往南园饯之醉中赋此","f":"七言律诗","c":["神龙跋浪辞沧溟，喜尔不逐长庚星。","豪谈酌我紫琼液，南园万竹皆泠泠。","溪边明月照飞鹭，枕外白云生翠屏。","揭阳舟楫自今去，奈此薰风萧艾青。"]},{"t":"忆昔行贺陶中丞","f":"七言古诗","c":["升平忆昔宪孝间，阻兵惟有西瓯蛮。","端溪以东尽乐土，桑柘阴阴连万山。","江门谈道集轩冕，紫水黄云多往还。","都亭津头万家市，明珠翠羽车斑斑。","东山去后崇者圯，新宁分疆乱未已。","锄犁逐日化长戟，蛟螭血人作流水。","宫中未平吕太一，阃外徒劳毛御史。","公来威德如东山，百万疲癃一时起。","出师振旅不动尘，胸次要与天为春。","雷雨所到草木新，光风淡荡波龙鳞。","佐也支离栖病身，耕凿今喜为尧民。","击壤引领四海均，谁云盗贼非王臣。"]},{"t":"醉歌赠王天与归关中兼讯马伯循","f":"七言古诗","c":["薰风吹酒耳双热，笑看天地无秦粤。","清尊莫嫌琥珀薄，后夜珠江空素月。","珠江仿佛轩辕丘，金鳌蹙沓银河流。","乘槎羡尔泛牛斗，直上殽函观九州。","九州茫茫尽如此，昔日荒郊今日市。","百万鲸鲵已京观，三千鸡犬犹冠履。","杜阳山前东逝波，祈年宫中芳草多。","寻幽为讯三原县，马卿多病今如何。"]},{"t":"松巢为颜录题","f":"七言律诗","c":["层冰硉矹风萧瑟，谈玄邂逅归根日。","若木朝来结紫霞，扶光夜转成金液。","济水逶迤环玉龙，翩然独立东蒙峰。","丹丘黄石倘可遇，浩歌与尔巢云松。"]},{"t":"月下酌李王二子歌","f":"古风","c":["青袍白马款我扉，绿蚁沽就霜螯肥。","长风送秋入燕树，但见万里银蟾飞。","持螯酌酒向二子，银蟾弄我杯中辉。","古来几许叹圆缺，今子不醉当无归。","君不见王子乔，君不见丁令威。","云间笙鹤去不返，辽辽仙赏谁能希。","相逢高歌且倾倒，耳热那闻今是非。","酒阑挥手一为别，满空白露明秋衣。"]},{"t":"都门逢美人行姚倅奎席上赋送陈参政探韵得高举二字","f":"古风","c":["都门柳丝青可缫，间关好鸟求其曹。","美人久矣入梦寐，笑挥结绿歌鸣皋。","忆昔赠我金错刀，欲往报之阻烟涛。","云裾月佩忽相见，冰雪一洗心烦劳。","兔园开尊延旆旄，春风淡荡吹绯桃。","觥筹淩乱丝竹动，燕笑不知明月高。","泉陵别驾醉起舞，舞罢逡巡泪如雨。","感恩自是门下人，杀身未报尊前主。","当年人弃君独取，英雄未遇多龃龉。","剑埋楚国终作龙，璞售宋人何异鼠。","君不见毛公薛公谁与语，风雨感会生毛羽，平原之客徒豪举。"]},{"t":"昆山谣送王子绳武归省","f":"古风","c":["昆山何在，在娄江之湄。","江流浩浩，其中石离离。","上有玉树樛其枝，啼乌哑哑枝上栖。","乌啼不休江水移，野风骚屑明星稀。","江介有芳，彼美者蓠。","艾而张罗，子于何飞。","有母今得奉餔麋，有如清水白石长相依。","不能随鸿鹄，逐逐稻粱空念饥。","天寒阻冰雪，徘徊岐路尚将安归。"]},{"t":"怀罗浮吟赠别何工部","f":"楚辞体","c":["我怀罗浮四百三十有二峰，大朵小朵青芙蓉。","波泬寥兮根鸿濛，列华舒艳兮昭神工。","盘空承宇夐出万象表，秀色直射彤云东。","中藏号屏，列缺丰隆。","时和吐霖雨，岁旱眠蛟龙。","麟为车兮凤为马，仙之人兮纷菲菲其如丛。","亦有太霞之洞，古禺之宫。","琪花瑶草历乱映晴昊，铁桥流水光于虹。","鸣?钦䲹不敢翼而过，往往神圣留灵踪。","猗嗟走兮，昔所幽栖。","乾坤造设待结宇，日月照耀开璇题。","一辞蕙帐走尘坌，松花糁径青猿啼。","水曹仙郎承紫泥，与尔话别兰台西。","螺杯满酌白玉酒，牛鼎初熟黄金鸡。","柳条吹丝绾白日，醉听騕袅当门嘶。","君今扬帆向我望云路，我犹驻辙系籍通金闺。","风尘何蹩躠，蔚荟方朝隮。","浮浮回极中，颓波谁为堤。","罗浮望兮愁，碧草春萋萋。","归来归来兮，采琈㻬以终日，种芝术其盈畦。","琼麋云液可以供日夕，胡为乎绊柴栅而久稽。","风驱离心满烟树，月照去路闻铜鞮。","临岐执手何所道，归来归来兮，凭君为我一访旧日飞云梯。"]},{"t":"桂之树行为李宫谕寿母赋","f":"古风","c":["桂之树，千万年。","蟠根广寒殿，度影沧浪天。","黄金为堂璧玉轩，中有郁仪美婵娟。","承日毂，辗星躔。","朱萼翠叶不知其所际，直与若英扶木相延连。","孟秋蟾兔当三五，光景婆娑满庭户。","曲按鸾凰酌鹦鹉，任丘仙人寿其母。","母家兄弟金蜩光，蓬水摇山映圭组。","四座欢声撤彩霞，玉绳不动金波舞。","令汝齐光寿千万，郁仪幽修月中语。","抚三旌，享千庾，一任瀛河日东注。","君不见，桂之树。"]},{"t":"六羊仙人歌赠方棠陵","f":"古风","c":["君行南越复闽越，邂逅凌江对秋月。","持觞不饮语瓯窭，仰天大笑缨欲绝。","飘摇挥手淩紫烟，骑羊抱月成飞仙。","戏摘匏瓜解残暑，织女黄姑皆粲然。","昔从九天谪下土，车驾前头遇威武。","都人观者如堵墙，摇笔赋诗骂平虏。","平虏敢嗔未敢言，即麾羖䍽登天门。","扣阍每逢虎豹睡，堕地便作蛟龙蟠。","有时乘轺向江汉，忽然牧牛耕石涧。","仙乎仙乎岂无有，眼底见君能变幻。","今年骑羊来我州，六十五日去不留。","亡鸟飞鸣独鹤舞，空馀孤树堂之幽。","带围有花开顷刻，顷刻又作黄金色。","前驱壶公后九鲤，白日果能生羽翼。","只今五羊城下歌丰穰，谓是五仙骑来曾降祥。","君来匹之顿成六，触邪持法陈纪纲。","君不见，獬豸称神羊。"]},{"t":"赋得三神山寿翟侍郎母","f":"古风","c":["三神山在沧海东，烛龙照耀开仙宫。","璿题接天缀珠斗，万叠瑞霭青濛濛。","下有弱流三万里，四时天乐空中起。","仙灵来往翳鸾鹤，袅窕霓幢镜光里。","蟠桃结实山之幽，蔽亏日月枝相樛。","金光瑶草莽成薮，千载传闻惟十洲。","翟公本是东海客，出入金銮佐宗伯。","手?元气开阳春，家与仙灵连窟宅。","天门笑拂云锦裳，帝台满挹缥玉浆。","持觞寿母北堂上，愿母寿比三山长。","御厨络绎传翠釜，玳筵合沓鸣箫鼓。","生儿荣贵有如此，词林谁不羡公母。","我亦有母天一隅，一日不见心烦纡。","天边未办彩衣舞，云外空传青鸟书。","青袍白马在羁旅，目极飞云送飞羽。","为公高歌歌且长，天生南北莫谁语。","丈夫硉矹宇宙间，缁尘浩浩凋朱颜。","显扬自古贵不朽，杰立遭时良独难。","不然采药沧海上，或骑麒麟恣往还。","君不见，三神山。"]},{"t":"蜀道行送王侍讲之四川参政","f":"古风","c":["蜀道平，平如砥，沃野烟绵亘千里。","岷江浩浩浮元气，剑阁石门相向起。","锦官城中春意动，玉户金缸艳桃李。","郫筒沽取不费钱，醉唱巴渝满山市。","比屋繁华渐非昔，帝遣词臣振纲纪。","王夫子，起邹鲁，黼黻心胸炳如虎。","弱冠排门见毛质，石室兰台奉明主。","手持彤琯耀日月，口授丹书动雷雨。","迩来暂辍承明直，紫绶金章莅兹土。","薇垣浩啸赞玄化，坐使苍生有环堵。","君不见汉家使蜀称三王，君岂其裔当传芳。","格天自合有经济，谕俗不独工文章。","回车叱驭信忠孝，碧鸡金马殊荒唐。","维舟三峡访千古，噭噭青猿啼夜霜。","君不见浣花溪古霜枫赤，洗墨池荒烟草碧。","古来名胜乃如此，往往江山尽陈迹。","丈夫立身贵不朽，百炼精钢万钧力。","他日调羹气益振，此别传觞醉何惜。","星车迢迢出蓬瀛，问君何时朝紫清。","秋风吹衣白露堕，执手踟蹰空复情。","高梧参天鸾凤集，雄剑跃地蛟龙鸣。","宫花院柳送愁色，孤鹜落霞随去旌。","玉壶酒尽情难尽，矫首长安空月明。"]},{"t":"骢马行送刘宪伯乔","f":"古风","c":["骢马驱，何悠悠。","月题染朱汗，倏与飞电流。","昔驱长安陌，今在粤海陬。","外台手执天子法，儿能学语皆知刘。","翩翩鸣佩觐帝旒，祖筵衣冠盈道周。","酌金罍，罗玉羞。","吹长笛，弹箜篌。","莫奏折杨柳，清霜满炎州。"]},{"t":"橘乐亭歌为萧内翰","f":"古风","c":["亭于何所名橘乐，闻在潮阳山麓临水国。","上有古木千章宿猿鹤，下有寒涛万顷走蛟鳄。","主人谁欤乃是铁峰子，平生意气与我同洒落。","银鱼金马弃如土，世间何物能羁缚。","君家兄弟总能文，阶前兰玉香纷纷。","闲来寻此橘中乐，疏帘清簟忘朝曛。","竹晖入户翠如电，霞石映水赪为云。","长安回望正如奕，文武衣冠安可闻。","有时兰桡下烟渚，玄鹤飞来听人语。","铿然黑白开两奁，荷叶芦花不知处。","觥筹淩乱混笙箫，雕盘绮错堆江瑶。","酒醒棋罢浩歌发，月堕空江生暮潮。","可怜紫陌尘凝面，何事朱门候相见。","冲泥冒雨走碌碌，那似尊前且枯战。","我闻橘中乐，不减于商山。","我怀商山皓，枉用凋朱颜。","紫芝一曲振岩谷，汉廷车马来追攀。","笑指云与鸟，出岫仍知还。","丈夫舒卷要如此，所乐岂必长在山水间。"]},{"t":"画龙为刘吉卿题","f":"古风","c":["吾闻后稷之孙驱魃赤水北，密云蔽天天为黑，黪日扬尘野萧瑟。","帝呼董父鞭两龙，翻海作雨岁乃丰，遂令四海歌重瞳。","又闻夏禹之御郭支氏，南驾两龙归后启，云盖三重走万里。","龙虽神灵乃为人所制，不独孔甲之时有刘累。","刘生十年游我门，志向磊落似是累后昆。","手持此图开，仿佛堂上苍苍烟雾屯。","大龙昂首欲煦沫，小龙回顾如有言。","追轶似有疾霆电，马髯冉冉天瓢翻。","海涛倏已浃下土，元气歘吸腾云间。","方今西北边尘起，新畲荐荒谁采芑。","明堂宵衣总为此，桔槔无功众芳靡。","呜呼董父郭支不可作，刘累空馀豢龙水。","摩挲此图欲招尔，尔勿面墙久依倚。","谁能驾之献天子。"]},{"t":"放歌行赠祁惟允","f":"古风","c":["粤王古台结衡宇，八月芙蓉映霜渚。","饶州太守来举觞，潜虬跃波听人语。","我何以语君，曲肱之外多浮云。","把玩自怡悦，岂必追随鸿鹭群。","君何以语我，春阳所施何不可。","蓬弧志四海，岂必赤墀与青琐。","眼中离合今十年，世涛呼汹胡为然。","丹枫叶脱白榆暮，明发粤台怀婺川。","婺川本是施罗国，笑谢双旌入莲幕。","石阡在昔登方岳，渊源况是承家学。","鹏徙何曾同燕雀，且尽醁醽为君酌。","君不见，市上沽，何处无。","生计转大心易粗，清讴不复闻当垆。"]},{"t":"咏竹分得临字","f":"古风","c":["忆昔葛陂之龙匿山阴，朅来珠海为瑶林。","我知神物固莫测，尔与天地皆无心。","淩冬载酒为尔来登临，击节浩歌怀古今。","渭川长竿在何处，淇园万矢空销沉。","王侯事业龌龊犹蹄涔，况乃奔走随朝簪。","尔虽无言洞我臆，琅然答以清泠音。","须臾万壑缥缈皆龙吟，耳热谓是羲皇琴。","翠光零乱日挂树，清影娜袅天横参。","是时鹤台仙客同高寻，琼杯绮席依萧森。","尊前对此万苍玉，床头何惜千黄金。","紫箫吹凤直上层碧岑，俯视淑气闻疏砧。","天寒袖薄暮相倚，山川黄落那能禁。","嗟尔磊落不受烟霜侵，岁晚相看同素襟。","他年傥逐风雷去，万里沧溟空自深。"]},{"t":"送刘行人灿","f":"古风","c":["进春酒，陈雅诗。","惠而好我纷来思，何以酌之金屈卮。","江汉滔滔东以驰，皇帝万寿隆天基。","日重光，海重润。","前星从帝出虖震，皇华原隰电如迅。","黎元欢欣走相问，丝纶一日周百郡。","公之来，金鞍玉节从燕台。","公之去，祥云瑞霭停荆树。","彩衣晔晔升华堂，兰阶蕙幄交辉光。","麟蒲荐以缥玉浆，曲裾长袂鸿鹄翔。","介尔眉寿天地长。","公之翁，黄金横带廌绣红。","公之姥，鱼轩珠翟锦为黼。","鹍弦凤吹参鸣鼍，举青玉案赓尔歌，君臣协德玉烛和。","麟趾螽斯仁且多，舜日尧年柰乐何。"]},{"t":"九日粤山登高醉中尽用五微韵成歌题曰将进酒","f":"古风","c":["将进酒，歌镂衣。","举玉爵，停金鞿。","凤琯龙笙，硕人其颀。","于以解忧，式饮庶几。","莼羹鲈脍纷哉馡，蟹黄初溢凫翠肥。","促膝劝君君莫违。","君不见朝始晖，夕转霏，鲁阳戈在谁能挥。","嗟尔乌兔，胡为逐逐环我岩上扉。","童时种柳今十围，钓游旧迹遍天地，想像徒依稀。","幸无风萧萧，雨祈祈。","三秋虽云杪，九月犹芳菲。","有翩者鸟，嘤鸣相依。","盍簪实难，知音亦稀。","相逢不为乐，他时梦寐怀容辉。","粲粲黄花，盈盈翠微。","肃肃命驾，采采忘归。","仰见云间翼，不入虞罗机。","安能摧眉折腰谒朱门，趋琐闱。","疏钟动，明星稀。","酌复酌，酒行如翔翚。","不醉明月将笑我，窥帘帏。","羊肠世路艰且巍。","犊有妃，妃呼狶。","狐以为苍，当誉反讥。","龌龊蓬茅丛，啼络纬，腾伊蝛。","此中髑髅，昔曾牙绯。","谷量牛马，尘积珠玑。","僮奴策骖焱騑騑，薰天势倏成露晞。","纵能化鹤去千载，华表谁真逢令威。","南溟徙鹍鹏，西北荒蕨薇。","商颜绝萝径，渭曲空渔矶。","古来豪圣今尽非，徒劳营魄聆音徽，穷经何用编绝韦。","我且濯明河而振缨，翳扶光以乐饥。","吐情向君君莫笑以诽。","醉来长啸粤山上，浮云直北连燕畿。","山中多木，矗矗如旗。","其下流水，活活清于沂。","粤王一去古台在，惟有飘飘霜叶飞。"]},{"t":"珠江夜别亲友","f":"五言律诗","c":["祖帐循珠浦，离杯对玉轮。","分襟移鹢首，鼓棹动龙鳞。","剑气千年合，风期万里亲。","只应开阁待，今有汉平津。"]},{"t":"雨","f":"五言律诗","c":["肤寸云初起，弥天雨正狂。","鱼龙空窟宅，草木各辉光。","爽气连南纪，愁阴接上方。","故山青未了，归梦此宵长。"]},{"t":"对月二首 其一","f":"五言律诗","c":["旅馆维舟后，江天入望时。","兔蟾当北斗，乌鹊绕南枝。","只恐金波溢，宁教玉漏迟。","火云消已尽，真觉近秋期。"]},{"t":"对月二首 其二","f":"五言律诗","c":["江月初成镜，山城独倚楼。","徘徊如伴客，浩荡更随舟。","陌上清光满，尊前烂漫游。","岂知离别后，对尔转添愁。"]},{"t":"舟度彭蠡遇风作","f":"五言律诗","c":["奔策遵玄渚，扬帆向紫都。","遥林吹地籁，巨浪舞天吴。","汇泽开长道，风飙动壮图。","扶摇自有适，何必美游凫。"]},{"t":"京邸春日思家","f":"五言律诗","c":["金市乘羊路，铜街试马群。","夜吟低霁月，春梦断浮云。","上巳兰英会，新年柏叶醺。","斑衣今未拂，休寄锦回文。"]},{"t":"元日","f":"五言律诗","c":["四载逢元日，悠悠燕冀间。","河山双鬓短，风雨一灯闲。","凤沼随恩泽，龙墀整佩环。","辞家长素食，真愧紫宸班。"]},{"t":"独坐","f":"五言律诗","c":["独坐禅扉迥，怀归思窅然。","花光明薄暮，莺语入新年。","彩仗随春动，华灯与月悬。","绝怜风景美，不是粤山川。"]},{"t":"暮春郊外","f":"五言律诗","c":["五日逢休沐，千山得胜游。","楼台萧寺迥，花竹习池幽。","春事已黄蝶，旧盟惟白鸥。","烟尘奔走地，回首意悠悠。"]},{"t":"月下赠张子文邦","f":"五言律诗","c":["独榻依萧寺，清尊散暮愁。","疏钟闻上苑，片月在飞楼。","天地双龙剑，江湖一钓舟。","壮怀吾共汝，摇落岁云秋。"]},{"t":"再次韵赠张子","f":"五言律诗","c":["长安木叶下，萧萧生客愁。","夜寒空对酒，云澹独登楼。","柳岸横长笛，花滩放小舟。","向来江海意，凄断为清秋。"]},{"t":"速张侍御补之同访文邦诗以代简","f":"五言律诗","c":["秋风起阊阖，渺渺独愁予。","水落蒹葭冷，天长鸿雁疏。","兰台思楚客，枫叶咏吴趋。","骢马招携地，琴尊信所如。"]},{"t":"廖子鸣吾秋日见怀次韵二首 其一","f":"五言律诗","c":["吾爱白鹿子，诗传鹦鹉洲。","隋珠偏照夜，宋玉最伤秋。","水绿芙蓉渚，霜黄悲翠楼。","相看成去住，徒尔赋离忧。"]},{"t":"廖子鸣吾秋日见怀次韵二首 其二","f":"五言律诗","c":["知尔龙山饮，凭高凤野开。","日从燕树转，云自汉宫来。","目尽天南雁，心飞江上台。","杜陵空抱病，庾信独生哀。"]},{"t":"弥罗阁秋望二首与马子仲房 其一","f":"五言律诗","c":["珠阁拂瑶天，凭轩兴渺然。","西风吹野水，高柳送鸣蝉。","冠盖黄尘里，关河白雁边。","相逢且披豁，随意问玄玄。"]},{"t":"弥罗阁秋望二首与马子仲房 其二","f":"五言律诗","c":["羽观临霄汉，飙台出薜萝。","霞觞延客久，琪树受凉多。","日色隐平楚，秋声连大河。","君看惬幽意，吾醉即狂歌。"]},{"t":"秋日游迎祥寺至玉泉与张杨赵陆四子同分韵得松知二字 其一","f":"五言律诗","c":["珠林开鹫峰，下马闻疏钟。","绀殿已狐兔，翠琰空蛟龙。","对酒感慨发，褰衣霜露浓。","苍苍暮色动，秋声满寒松。"]},{"t":"秋日游迎祥寺至玉泉与张杨赵陆四子同分韵得松知二字 其二","f":"五言律诗","c":["迢递寻莲宇，淹留咏桂枝。","玉骢穿柳入，锦席傍泉移。","山翠浮龙苑，云光溢雁池。","尘心今已净，应有白鸥知。"]},{"t":"中秋不见月文徵仲席上赋","f":"五言律诗","c":["明月隐天端，疏灯耿夜阑。","浮云飞不尽，万里若为看。","晕落鹏霄迥，光生凤阙寒。","谁能天柱上，吾意欲骖鸾。"]},{"t":"冬夜宴陈子学宅赏菊分韵得微字","f":"五言律诗","c":["黄菊冬犹艳，清歌夜未归。","兴从添烛剧，寒到引杯微。","宫漏挟风度，塞禽冲月飞。","物华容易尽，心赏莫教违。"]},{"t":"新春","f":"五言律诗","c":["尧历开元岁，殷邦数中兴。","苑花红未入，宫草翠先凝。","功业时看剑，栖迟夜向灯。","匡扶在诸老，贫病任相仍。"]},{"t":"中秋夜对月","f":"五言律诗","c":["作客惊秋半，行歌对月明。","玉轮看桂满，银浦见槎横。","疏柳门墙静，高梧风露清。","此时裁谢赋，千里一含情。"]},{"t":"素翁先生元日书怀次韵二首 其一","f":"五言律诗","c":["许身齐稷契，挥手谢巢由。","鹊起千人悦，龙飞万国休。","王春随听履，卿月照稽谋。","一任云庄上，莺花锁鹭洲。"]},{"t":"素翁先生元日书怀次韵二首 其二","f":"五言律诗","c":["归兴凭谁语，裁诗每自怜。","草青壶峤外，鸥白影池前。","淑气通嘉石，祥飙洒列钱。","即看吾道在，行止信皇天。"]},{"t":"迎祥寺后游次韵四首 其一","f":"五言律诗","c":["五载吾重到，双林路欲迷。","梯飙寻绝境，拂翠见灵溪。","石洞云堪卧，花宫鸟自啼。","迟回意无限，归骑及乌栖。"]},{"t":"迎祥寺后游次韵四首 其二","f":"五言律诗","c":["辇毂环龙象，耽游未拟回。","金貂何处所，珠鸟至今来。","芳树含青霭，丰碑净绿苔。","琼帘自舒卷，谁见化人开。"]},{"t":"迎祥寺后游次韵四首 其三","f":"五言律诗","c":["沙柳明秋色，烟萝出梵香。","川原双步屧，感慨一持觞。","慧日无人相，慈云不住方。","世缘如可度，留宿远公房。"]},{"t":"迎祥寺后游次韵四首 其四","f":"五言律诗","c":["白马开三乘，祥鶤运九衢。","乾坤经浩劫，陵谷尽浮图。","柳径涵川净，枫林带藓枯。","倦游仍立马，寒日动平芜。"]},{"t":"舟中夜宴赠别胡苏州","f":"五言律诗","c":["荡楫语深夜，知君怀草堂。","微云开震泽，锦瑟奏伊凉。","飒飒满红树，翩翩飞紫凰。","曲终酒亦醉，明日各殊方。"]},{"t":"虎丘怀古","f":"五言律诗","c":["寂寞吴王国，笙歌入海云。","夫椒先自败，于越遂能军。","月落苧萝冷，花深麋鹿群。","千年金虎去，谁守阖闾坟。"]},{"t":"赠别黄武进同年","f":"五言律诗","c":["武进仙凫驻，三年报政成。","阎闾无复叹，山水有馀清。","渺渺舟楫去，苍苍霜月明。","停云时隐几，河汉欲三更。"]},{"t":"赠别韦评事归靖江","f":"五言律诗","c":["抗疏甘南谪，知君不负丞。","离情江上树，聚首驿前灯。","幽谷歌鸣鸟，天池息大鹏。","扁舟汛明月，回首梦毗陵。"]},{"t":"得子弥月二首 其一","f":"五言律诗","c":["犀果欣延客，风尘慰索居。","老亲期有后，游子敢无书。","赋命由天地，他年定智愚。","谁能识英物，啼看问何如。"]},{"t":"得子弥月二首 其二","f":"五言律诗","c":["定省心千里，栖迟梦一丘。","冰霜仍作客，江海更停舟。","去去怜渠小，呱呱解旧愁。","轩车那可问，为尔重淹留。"]},{"t":"立春","f":"五言律诗","c":["野馆依寒渚，愁吟且未回。","春从今日到，花在故园开。","白雪裁仙调，青云捧御台。","阳和不负客，偏入掌中杯。"]},{"t":"雨木冰正月二日作","f":"五言律诗","c":["野树纷纷白，连朝雨木冰。","人情怜上朔，天意望中兴。","絮雪风难起，梨云日易蒸。","春王调玉烛，何事有严凝。"]},{"t":"潞河元夜","f":"五言律诗","c":["水国明鳌火，烟花接凤城。","绝怜今夜酒，空复异乡情。","宝马嘶尘度，银蟾倚树明。","客愁无处看，况乃管弦声。"]},{"t":"冻开初发","f":"五言律诗","c":["万里图南翼，逢春始计程。","彤云辞魏阙，绿树出秦京。","鼓枻江天豁，流澌野岸平。","因风传尺素，应慰倚门情。"]},{"t":"河西午憩","f":"五言律诗","c":["水驿远郊圻，居然尘事稀。","酒帘明柳市，渔网集苔矶。","隐几白日静，开帘黄鸟飞。","行边有林壑，未觉素心违。"]},{"t":"天津雨中即事","f":"五言律诗","c":["幕府开三卫，粮漕集万艘。","人皆甘海错，吾且醉村醪。","潮落洲随出，烟深岸却高。","冲泥走风雨，端坐看儿曹。"]},{"t":"修复粤洲草堂经始桃源坞四首 其一","f":"五言律诗","c":["草堂修旧业，凿翠向高城。","俯首嗟人境，冥心谢世情。","山从疏树众，江入大荒平。","隐几云霞里，脩然得此生。"]},{"t":"修复粤洲草堂经始桃源坞四首 其二","f":"五言律诗","c":["桃源初小筑，茆屋可衰翁。","井市锥刀外，生涯一亩中。","乔林闻独鸟，幽谷送长风。","朋好今如此，清尊谁与同。"]},{"t":"修复粤洲草堂经始桃源坞四首 其三","f":"五言律诗","c":["日明花外路，雨长竹间泉。","隔谷难逃俗，依山自觉仙。","功名归坠甑，宇宙入浮烟。","已悟逍遥化，从今结静缘。"]},{"t":"修复粤洲草堂经始桃源坞四首 其四","f":"五言律诗","c":["排闼分青嶂，充庭尽绿柯。","敛神知日永，高步觉天多。","返照满城郭，孤烟生薜萝。","到家三舍近，尘土竟如何。"]},{"t":"送周秋斋方伯归闽二首 其一","f":"五言律诗","c":["珠江愁送客，薇省喜留君。","车马三城动，讴歌百粤闻。","沧洲难吏隐，紫极易风云。","去去吾何道，甘随麋鹿群。"]},{"t":"送周秋斋方伯归闽二首 其二","f":"五言律诗","c":["南海瞻冠冕，东风吹旆旌。","封棠无剪伐，骑竹有逢迎。","春舫随花发，秋容入镜平。","因思木兰水，端可濯吾缨。"]},{"t":"六月二十日梦中作七夕诗觉而忆其全篇录以纪异","f":"五言律诗","c":["凉色晚幽幽，疏梧知早秋。","古来传帝子，今夕会牵牛。","大泽生明月，苍崖带远流。","凭高语天上，何事有离愁。"]},{"t":"酌泰泉赠区广文","f":"五言律诗","c":["一勺泰泉水，中涵千仞青。","远分舒鹤渚，寒带聚龙坰。","花竹添萧爽，风云助杳冥。","看君苏齿颊，为尔续茶经。"]},{"t":"宿灵川寄怀范大参","f":"五言律诗","c":["性拙嗟无侣，交深赖有君。","襟期珠海月，去住桂山云。","黄屋匡扶切，苍生轸念勤。","灵川烟雨里，忧乐梦希文。"]},{"t":"兴安道中","f":"五言律诗","c":["放浪沧洲客，迟回桂水春。","密云虚碍马，芳草远随人。","野阔啼莺树，山多佩犊民。","戍歌愁听汝，荒服几时新。"]},{"t":"卧病二首 其一","f":"五言律诗","c":["卧病梧山晓，怀归菊径秋。","凄风催叶下，积雨入江流。","遂有鲈鱼兴，聊为鸿雁谋。","飘摇寄生事，天地一扁舟。"]},{"t":"卧病二首 其二","f":"五言律诗","c":["长笛送愁思，孤琴随病身。","鸦翻中夜月，鹊报故乡人。","千里庭闱梦，十年岐路尘。","悠然念黄绮，误逐汉廷臣。"]},{"t":"寄怀徐养斋方伯","f":"五言律诗","c":["多病朋簪盍，他乡意绪孤。","梧江通百粤，桂岭隔三吴。","归鸟择云木，游鱼依渚蒲。","何时同孺子，高枕著潜夫。"]},{"t":"江村书舍为滇人魏德如赋","f":"五言律诗","c":["勋业看朝镜，诗书伴夜檠。","下帷芳草色，闭户远潮声。","飞跃形吾道，渔樵乐此生。","鹍鹏终变化，滇国本南溟。"]},{"t":"控海楼有怀徐可大","f":"五言律诗","c":["南州徐孺子，落笔满人间。","江上笑为别，天边去不还。","高楼题控海，此日独看山。","尚忆危言日，投簪且闭关。"]},{"t":"崖山纪游次郑李二子韵二首 其一","f":"五言律诗","c":["岁晚空山静，遥闻猿鹤音。","胶舟前日事，倾盖此时心。","渔戙乘潮急，樵歌隐雾深。","停杯发高咏，兴剧不成斟。"]},{"t":"崖山纪游次郑李二子韵二首 其二","f":"五言律诗","c":["夕阳惟鸟雀，古道半榛荆。","蠹饱祠中木，苔侵石上铭。","英灵终寂寞，风物自凄清。","仰羡东山老，劳歌空复情。"]},{"t":"泰泉山中赠伦王二子","f":"五言律诗","c":["金涧绕青林，瑶空出翠岑。","烟霞供永啸，松竹入长吟。","春度莺犹在，杯香客每深。","随时共幽赏，吾未倦登临。"]},{"t":"草堂避暑四首 其一","f":"五言律诗","c":["林壑谒苍苍，层崖曲抱塘。","闭门蛙鼓竞，欹枕鸽铃长。","霞珥混斜照，炎威连大荒。","冥心对鹥鹭，将尔共沧浪。"]},{"t":"草堂避暑四首 其二","f":"五言律诗","c":["隐几消永日，薰风摇紫薇。","钩帘一以眺，绿水近岩扉。","嗒尔烟光夕，居然尘事稀。","翩翩松上鹤，遥带白云归。"]},{"t":"草堂避暑四首 其三","f":"五言律诗","c":["蹙啸延清籁，长谣集绪风。","岭云偏向北，郁水亦流东。","地切三边戍，天开万寿宫。","飞仙挟明月，应得到崆峒。"]},{"t":"草堂避暑四首 其四","f":"五言律诗","c":["徙倚碧氛氲，行歌许鹤闻。","剪茅通月色，攒石聚霞文。","袅袅竹到水，喤喤钟度云。","悠然俯尘世，天外自为群。"]},{"t":"人日雨霁出门志喜","f":"五言律诗","c":["王春听旧雨，人日见新晴。","万户笙歌沸，千山紫翠明。","和风匀柳色，淑气入莺声。","所喜青阳动，休嗟白发生。"]},{"t":"谷日陈茶山少参席上赋","f":"五言律诗","c":["谷日过从喜，薇垣礼数稀。","杯深花共劝，坐久月同归。","南海楼船静，东吴粳稻肥。","使君能化俗，未许问渔矶。"]},{"t":"喜雨次陈茶山韵二首 其一","f":"五言律诗","c":["献岁初逢雨，随车且泽民。","小楼听到晓，幽谷见回春。","燕雀依巢静，鱼龙出浪频。","沧洲理烟艇，蓑笠定随人。"]},{"t":"喜雨次陈茶山韵二首 其二","f":"五言律诗","c":["吾爱茶山子，吴讴播粤民。","檐声才入夜，野色尽成春。","水渐浮舟阔，花堪对酒频。","向来雩祷切，天果不遗人。"]},{"t":"粤台怀古四首分韵得幽字 其一","f":"五言律诗","c":["胜地经秦汉，高台近斗牛。","片云浮郁水，孤月满灵洲。","事往市朝变，秋来林壑幽。","霸图何足问，吾得采真游。"]},{"t":"粤台怀古四首分韵得幽字 其二","f":"五言律诗","c":["歌舞何人在，襜帷此日留。","长江涵楚越，远树入燕幽。","倾国嗟摎女，提兵忆路侯。","绝怜张乐地，斜日下羊牛。"]},{"t":"粤台怀古四首分韵得幽字 其三","f":"五言律诗","c":["对酒烟霞晚，裁诗天地秋。","坐闻松籁迥，行爱桂岩幽。","大泽龙蛇远，荒台鹿豕游。","向来南海尉，辛苦事嬴刘。"]},{"t":"粤台怀古四首分韵得幽字 其四","f":"五言律诗","c":["南武河山在，北窗花竹幽。","羲皇吾所傲，秦越尔何尤。","紫气通三极，沧波带十洲。","悠然阅尘世，高枕白云秋。"]},{"t":"白莲次韵陈天游二首 其一","f":"五言律诗","c":["丘壑旧同赏，琼琚新报词。","岳云增野色，郢雪助芳姿。","枝蔓勿复道，缁尘非所期。","悠然梦商皓，千载慰相思。"]},{"t":"白莲次韵陈天游二首 其二","f":"五言律诗","c":["懿尔泥不滓，况兹清且涟。","洛神终有恨，越女不成妍。","气夺星榆晓，光含露藻鲜。","钩帘浑未起，宿鹭亦相怜。"]},{"t":"草堂夜坐四首 其一","f":"五言律诗","c":["浪迹少城偎，衡茅向水开。","闭门青嶂合，卷幔白鸥来。","地僻清虚洞，天高玄览台。","坐闻松籁起，竟夕思悠哉。"]},{"t":"草堂夜坐四首 其二","f":"五言律诗","c":["越台舒啸罢，燕树去人遥。","寓目成今古，冥心谢市朝。","枝间乌鸟乐，陇上白云飘。","萧洒不知晚，空江自落潮。"]},{"t":"草堂夜坐四首 其三","f":"五言律诗","c":["性僻群鱼鸟，家贫足蕨薇。","偶寻瑶草去，时共暮樵归。","野色入河汉，钟声连翠微。","云鹏有奇翼，不为稻粱飞。"]},{"t":"草堂夜坐四首 其四","f":"五言律诗","c":["云卧开丹牖，瑶天四望通。","虞弦徒解阜，楚客谩雌雄。","万壑收虚籁，千林息断蓬。","何当秋色里，一叶咏梧桐。"]},{"t":"哭崔南甫二首 其一","f":"五言律诗","c":["执业越三载，盖棺悲仲春。","岂知吾未老，空恸尔为人。","亭伯夙工赋，原思甘食贫。","慰亲能不死，天与玉麒麟。"]},{"t":"哭崔南甫二首 其二","f":"五言律诗","c":["芹泮始于迈，舞雩频咏归。","倚筠瞻寿阁，纫穗扫慈帏。","水自三山逝，云依双鹤飞。","夜台终宿草，知尔恋春晖。"]},{"t":"绯桃","f":"五言律诗","c":["手种绯桃树，今成满院春。","垂垂堪系马，脉脉似怀人。","绿水浮天镜，红霞隔世尘。","向平毕婚嫁，好在武陵津。"]},{"t":"元夕次梁子韵二首 其一","f":"五言律诗","c":["粤山依静渚，陆海沸青宵。","火树流丹夐，荒郊拾翠遥。","骖驔风外辔，窈窕月中桥。","向晚游尘寂，犹闻芗泽飘。"]},{"t":"元夕次梁子韵二首 其二","f":"五言律诗","c":["五夜轩车密，千门景色赊。","金波依树渺，银浦逐城斜。","炬合疑朝旭，杯分似晚霞。","艳阳桃李在，休唱落梅花。"]},{"t":"春日玄览台独坐偶成四首 其一","f":"五言律诗","c":["为爱春台好，逍遥到日曛。","栖神随豹雾，矫翰谢龙云。","水自灵洲入，山从粤井分。","无论拳与勺，天地本同群。"]},{"t":"春日玄览台独坐偶成四首 其二","f":"五言律诗","c":["风磴纡盘郁，云萝出泬寥。","日垂天北极，春动粤南潮。","松籁传虚壑，莺歌赴远箫。","悠然澹忘味，何必更闻韶。"]},{"t":"春日玄览台独坐偶成四首 其三","f":"五言律诗","c":["下上茅皆屋，东西竹亦垣。","城标双塔短，冈拥一旗尊。","林密鸟巢隐，风低蛙吹繁。","稀疏见畦畛，真学邵平园。"]},{"t":"春日玄览台独坐偶成四首 其四","f":"五言律诗","c":["稍稍东风起，台前洲渚明。","竹光摇野色，花气润蛩声。","北斗依身近，南溟入掌平。","栖栖何所适，孤啸一含情。"]},{"t":"次韵梁应房园居四首 其一","f":"五言律诗","c":["青林依坝隈，翠牖何东开。","大泽龙犹卧，长安日自来。","濯缨疏郁水，拄笏对朝台。","啸傲浮云外，雄图安在哉。"]},{"t":"次韵梁应房园居四首 其二","f":"五言律诗","c":["揽辔漳南静，弹冠蓟北遥。","骅骝归别墅，鹓鹭梦清朝。","野水疑天咫，秋花忆雪飘。","衡门系舟楫，知尔待风潮。"]},{"t":"次韵梁应房园居四首 其三","f":"五言律诗","c":["水上谁家月，山中几度薇。","坐怜秋色半，吟待莫禽归。","风定松声合，云深竹径微。","相过吾所愿，疲病兴如飞。"]},{"t":"次韵梁应房园居四首 其四","f":"五言律诗","c":["卜筑青门胜，云山紫逻通。","萧条同杜甫，寂寞异扬雄。","日月双飞鸟，乾坤一断蓬。","玉衡如可协，将子共丝桐。"]},{"t":"梦中作","f":"五言律诗","c":["南斗钟人杰，中朝起帝臣。","日明鸾凤署，风静大羊尘。","道以无为大，功存不宰神。","掖垣花万树，无语自成春。"]},{"t":"送梁佥宪应房之贵州次韵二首 其一","f":"五言律诗","c":["脉脉怀燕北，行行度楚西。","地连丹水阔，天入翠屏低。","奋翅看鹏翼，骖驔送马蹄。","未须谈贵竹，吾意在烝黎。"]},{"t":"送梁佥宪应房之贵州次韵二首 其二","f":"五言律诗","c":["秋星垂马首，北斗映南箕。","鸟静粤山晚，天寒湘水微。","窥园因伐木，抱瓮本忘机。","怅别蓬门下，西风吹汝衣。"]},{"t":"悼幼儿在贞二首有引 其一","f":"五言律诗","c":["四龄虚度世，七月早知书。","常日依兄膝，危时挽母裾。","竻园埋白玉，兰砌陨明珠。","拭泪看天地，伤心汗血驹。"]},{"t":"悼幼儿在贞二首有引 其二","f":"五言律诗","c":["汝慧言难尽，吾衷情易哀。","黄裳空兆梦，彩羽竟成灰。","曙色连鸦起，春寒逐雨来。","不堪心寸折，泪尽更徘徊。"]},{"t":"子陵钓台次马宪副韵","f":"五言律诗","c":["文叔资为理，狂奴岂不胜。","高风鲁国钓，斜日汉家陵。","鼎足归侯霸，糟糠愧宋弘。","羊裘见几去，龙德至今称。"]},{"t":"济宁馆与孟太仆同年共酌","f":"五言律诗","c":["清济风涛静，坚冰日夕深。","燕台千里梦，鲁道百年心。","竹叶浮螺斝，梅花落凤琴。","玄冬堪纵酒，白首得知音。"]},{"t":"赠江钟石中丞","f":"五言古诗","c":["薇省声华久，枫廷宠渥新。","鹏抟持宪节，虎变起儒臣。","日月缠雄剑，风云拥要津。","直将炎海泽，散作塞垣春。","雪岭遥连晋，葱河近逼秦。","天骄虽匪茹，庙略正如神。","昔者分符竹，恭惟督泮芹。","去思曾款款，来学各駪駪。","匡济才惊代，旬宣政绝伦。","壮猷端许国，直道每褆身。","喜送潘舆近，威行卫幕匀。","攀援当此日，歌颂更何人。","入座鸿应渐，三旌蠖转伸。","蹇予随赤管，正尔奉清尘。"]},{"t":"挽丘侍御母","f":"五言古诗","c":["汾水扬慈教，闽山见女宗。","忧勤朝弋雁，谆切夜丸熊。","密密衣间线，行行道上骢。","鵻飞犹有集，川逝更无穷。","笋泣交加翠，萱嗟委坠红。","台乌向明月，时为唤悲风。"]},{"t":"送九江杜通判","f":"五言古诗","c":["杜曲传千载，韦经守一窗。","徽声驰北戒，新命佐南邦。","视篆垂朱绂，飞书出皂幢。","群峰浮鹿洞，九派接龙江。","日下华辀发，风前叠鼓韸。","临岐何所道，珍重锦韬杠。"]},{"t":"送张允清守济宁","f":"五言古诗","c":["宛洛邅吾道，风尘笑此生。","昔曾同客味，今乃送君行。","冉冉柳枝碧，萧萧班马鸣。","挥觥临祖席，飞幰问王程。","燕树当齐尽，河流到济清。","一麾知不忝，霄汉听蜚声。"]},{"t":"秋日赵信臣席上咏夏菊分得纤字十八韵","f":"五言古诗","c":["开席来金马，濡毫注玉蟾。","萧晨纡胜引，逸兴角精严。","淅淅风生座，依依日转檐。","曲中芳树净，天外绮云纤。","老干偏宜石，奇姿不避炎。","裳蕤黄竞艳，㔩叶翠交尖。","鳌阙高霞映，鹓池细雨沾。","香通缥玉液，清夺水晶盐。","纫佩哀湘屈，餐英效晋潜。","只今营斗粟，徒自拥帷襜。","世事灯前剑，心期架上签。","牖开怀斧扆，隅泣轸闾阎。","荆璞难为韫，吴刀未试铦。","鲸鱼终碧海，鹦鹉亦红甜。","抱拙蕲天遇，耽幽任俗嫌。","空群怜逐骥，知己愿成鹣。","霜吹俄欺袂，珠光渐近帘。","相逢须适意，吾敢赋厌厌。"]},{"t":"寿简封君","f":"五言古诗","c":["县圃乾坤大，康衢日月长。","仙方元不老，帝力正相忘。","皤发明鸠杖，童颜醉鹤觞。","安车花柳径，击壤水云乡。","菊对金章艳，兰交玉珥行。","凤毛鸣盛世，豸角立岩廊。","欢动狐南彩，情深冀北望。","白云如会意，终日自悠扬。"]},{"t":"宿刘谏议蕡祠","f":"五言古诗","c":["谏议祠堂在，栖栖托泮林。","雨垣春藓合，风柳莫蝉吟。","湓浦天何远，沙河水自深。","兽炉浮劲气，虬箭递徽音。","社稷谁能奠，经纶而独任。","毁方难入彀，晞古合投簪。","桑海时应变，桃源路可寻。","炎荒终弃置，幕府始浮沉。","宫府分南北，兴亡共古今。","吐言扶白日，回首破层阴。","牢落千年梦，凄清此夜心。","停镳休远躅，呼酒涤烦襟。","宿鸟喧云堞，飞鸿掠月岑。","广陵有馀恨，非直雍门琴。"]},{"t":"嘉靖丙戌郊祀庆成侍宴有述八十韵","f":"五言古诗","c":["五载精禋日，三灵锡羡时。","东皇初出震，北斗正临箕。","煦妪函元气，絪缊运太仪。","奉常稽令甲，宗伯阐宏规。","扈阁人文焕，容台礼数知。","馨香非黍稷，茧栗实牷牺。","象性陶匏具，依神藁秸为。","泽宫尝选士，祢庙夙谋龟。","斋沐神如在，端凝敬自持。","太羹调太鼎，明水办明齐。","衣桁回猋桂，盘飧折露葵。","阆阆开秘殿，莫莫护飞榱。","魄宝崇穹昊，归藏协地祇。","百神将受职，二后并开基。","作对纷纯黼，升中共泰壝。","天门何荡荡，帝绩更熙熙。","承宇方寥廓，中坛自峛崺。","青葱森玉树，蠖略秀金枝。","有瞽皆师旷，无工不巧倕。","宿县龙簨作，驭路虎贲驰。","万乘鸣銮出，千官委佩随。","星辰归剑履，日月下旌旗。","鹭鼓雍容伐，鸾箫缥缈吹。","孔旌翻格泽，垒叠走魖夔。","队拟钩陈列，声逾郁律攠。","苍虬衔玉轪，彩凤翳华芝。","画戟丛犹植，周庐布似棋。","九关严虎豹，七萃奋熊罴。","渐觉天威迩，相看日色迟。","班行分鹄立，匡卫结鱼丽。","驻辇闻王夏，趍庭奏采茨。","骏奔咸有恪，麇至总无遗。","静揆冥冥景，深存眑眑思。","玄圭端极拱，朱火粲星离。","凫氏鸣春律，鸡人唱晓曦。","象驯环日毂，骥集簇云螭。","琮璧交辉映，樵蒸待配藜。","仙宫澄碧落，天乐动黄麾。","轩冕繁璿藻，垂衣矗玉綦。","登高无白雪，疏越有朱丝。","衎衎承云舞，皇皇就日姿。","空桑依大卷，孤竹倡咸池。","肸响知何许，居歆谅在兹。","燔柴明远汉，埋瘗及窊坻。","遗灺销田烛，浮埃静路岐。","天回鱼钥启，雷动鸟旟移。","鳌抃连三极，鸿恩遍四夷。","飨神兼夏姒，类祀法虞妫。","白帝卑秦畤，黄郊陋汉祠。","上玄昭降假，下土受蕃□。","庆洽需云宴，欢同湛露诗。","尧厨传萐脯，镐饮荐嘉脾。","百味银罂叠，千牢绮俎披。","紫霞浆胜玉，玄圃菜如饴。","驾凤花扶扆，骖龙柳拂羁。","羽林盈陛盾，绣服耀轩墀。","日丽芙蓉阙，风清翡翠帷。","辟门来辅弼，通籍引丞疑。","雉扇黄金幄，麟轩白玉逵。","五侯先在列，百辟各攸司。","御气通瑶席，宫花散彩枝。","鹓行沾圣渥，虎拜感皇私。","枫陛宣酬劝，兰觞示惠慈。","铿金尊帝德，销玉合坤维。","晨露翻柔瑟，钧天起朔鞞。","华冠重岌嶪，锦臂烂葳蕤。","虹辫天魔发，蛾扬玉女眉。","都卢方矍铄，曼衍复躨跜。","海宇歌仁洽，鞮鞻舞德绥。","八珍仍络绎，九籥讵参差。","谛听金陵曲，元非璧月词。","皇天曾燕及，谟烈有鸿垂。","莫以龙颜喜，浑忘虎尾危。","本朝真舜禹，吾道在皋伊。","礼竣荣簪绂，心铭建鼎彝。","联镳归月夕，奋翼赴风期。","周雅祈天保，虞谟警日孜。","鸾情驰禁籞，凤想入罘罳。","喜色融山野，荣光澹海涯。","摛毫颂玄化，万物已华滋。"]},{"t":"嘉靖丙戌元宵燕集分得银字赋二十韵","f":"五言古诗","c":["帝城三五夕，明月丽芳春。","玉宇澄晖早，金枢泛滟新。","香车腾桂苑，缇骑出枫宸。","陆海鱼龙混，天关虎豹驯。","烟花连凤野，箫鼓动鸿钧。","乐事还同众，清光故可人。","弄芳珠作佩，步玉锦为茵。","宝炬交蟾影，琼奁并兔轮。","风回歌舞地，香拂绮罗尘。","鳌彩浮燕树，星球射汉津。","惰随虬箭晓，兴与鹤觞亲。","对此开文会，因之仰德邻。","摽缨三益至，挥翰四筵陈。","淑气回彤琯，清歌尽白蘋。","音徽嗟尔阔，契合道吾真。","凫藻人争羡，骊珠世共珍。","花边青玉案，柳外紫纶巾。","云户低圆壁，虹桥掩寸银。","赤霄繁健翮，沧海足潜鳞。","共沐恩波洽，追欢莫厌频。"]},{"t":"游金山次刘太守士奇韵","f":"五言古诗","c":["宝地纡玄览，雌途拥梵僧。","风烟千里合，江海一桴乘。","树色依山见，云光带雨升。","象溟迷浴景，龙钵变炎蒸。","望阙频回首，忧时更拂膺。","凄凉非楚客，萧瑟问吴绫。"]},{"t":"次日游焦山复和同游刘太守韵","f":"五言古诗","c":["玉屿淩空迥，金山入望斜。","乾坤分砥柱，日月送浮槎。","鹤冢空烟水，龙宫自雨花。","丹枫明远浦，白鸟失晴沙。","浩劫皆成幻，征途未有涯。","所欣陪五马，来此听三车。"]},{"t":"送翁少参归蜀","f":"五言古诗","c":["北上曾倾盖，南归但倚楼。","旬宣临粤土，俊杰起泸州。","菽水情偏共，兰金分亦投。","甘为清净退，真脱网罗求。","奉檄缘家食，悬车谢国谋。","人歌棠所茇，天照柏为舟。","白峒开三径，黄花傲九秋。","潘舆驰燕喜，郫酒侑鸾讴。","宝岫云随望，支江月映流。","羡君从此去，扶病赋离忧。"]},{"t":"中秋游扬历岩二十韵奉谢郑南雄","f":"五言古诗","c":["旅客逢秋半，重岩望日边。","风江连楚粤，云树极幽燕。","笳鼓循坰发，旌旗陟巘联。","境推扬历胜，人喜郑庄贤。","鹫岭开金地，龙潭际碧天。","崖含萝幌狭，磴转竹房偏。","袅缀云何卉，高垂不记年。","奇音闻素瀑，秀色映平田。","万象皆超忽，千峰自蜿蜒。","岭梅遥度马，堤柳竞鸣蝉。","虚籁笙簧合，中轩锦绣悬。","清歌螺梵外，妙舞鸟巢前。","辙逐朱幡驻，杯从彩袖传。","傍泉移绮幕，拂石列琼筵。","暯暯旋灵耀，陶陶象帝先。","冥心忘泡影，握手问真源。","北去浮鸣雁，南流跕断鸢。","涧花寒未落，云碓晚相喧。","步壑璇零迥，归途璧月圆。","何由穷绝顶，直欲挟飞仙。"]},{"t":"庚子孟冬恭遇千秋令节赐宴赋二十韵","f":"五言古诗","c":["燕冀年方茂，虹流月始阳。","发祥开鹤籞，称寿奉麟觞。","睿德摇山重，蒙泉少海长。","圣箴承敬一，神器副元良。","矫迹崇贤里，含毫翊善傍。","汉庄言益敏，夏启道弥光。","玄辔骖龙象，丹幢引凤凰。","鹄舆犹玉裕，鸡戟更金相。","硕辅来兰殿，英寮集桂坊。","寿街齐抃舞，华阙俨趋跄。","钜砌烟花绕，琼筵锦绣张。","殷梅调鼎美，尧萐助羹香。","翠釜传中使，黄封出上方。","座依红日永，杯逐彩云翔。","自愧冥鸿羽，仍随振鹭行。","荐雷期有则，明两祝无疆。","既醉缘霞紫，无言感昊苍。","逶迤归玉署，仿佛度银潢。","万国欢声动，千官喜气扬。","沾恩何所似，丰草露瀼瀼。"]},{"t":"庚子二月入京述怀四首 其一","f":"五言律诗","c":["释耒回鹓沼，驱车入凤城。","日明新阆苑，春满旧蓬瀛。","珠树森玄极，瑶坛概紫清。","踟蹰思无限，惟愿泰阶平。"]},{"t":"庚子二月入京述怀四首 其二","f":"五言律诗","c":["赤帝驱胡地，苍姬奠鼎年。","仁涵繁露外，礼缦庆云边。","灞棘悬孤垒，皋兰控万弦。","词臣频献颂，谁敢勒燕然。"]},{"t":"庚子二月入京述怀四首 其三","f":"五言律诗","c":["白首承明直，回翔十五春。","花前仙掌露，柳外属车尘。","鹤禦开青幌，螭坳侍紫宸。","候朝清不寐，瞻望月重轮。"]},{"t":"庚子二月入京述怀四首 其四","f":"五言律诗","c":["衮职云无阙，徒闻上谏章。","地分青琐闼，天隔白云乡。","凤藻传东阁，龙晖接少阳。","所希吾道泰，千古说黄唐。"]},{"t":"移居春坊咏庭桧","f":"五言律诗","c":["丛桧霭深秋，苍霞烂不收。","霜髯临玉涧，秀色带昆丘。","拂槛光风入，萦窗璧月留。","恍然江海上，飞跃有灵虬。"]},{"t":"感秋三首时洪都兵变予方种菊东篱有终焉之志因赋此诗 其一","f":"七言律诗","c":["秋风萧瑟起千山，篱外黄花自作闲。","冠盖何年通宛洛，鼓鼙连日动乡关。","风尘不入窗间岫，世事能彫镜里颜。","闻道日边佳气在，都人长望属车还。"]},{"t":"感秋三首时洪都兵变予方种菊东篱有终焉之志因赋此诗 其二","f":"七言律诗","c":["一舸当年发豫章，豚鱼吹浪棹相将。","黄芦夹岸天连海，白雁临关夜有霜。","氛祲秪今干斗极，江湖依旧远岩廊。","悲吟不尽伤秋意，红叶萧萧暮吹长。"]},{"t":"感秋三首时洪都兵变予方种菊东篱有终焉之志因赋此诗 其三","f":"七言律诗","c":["漠漠秋阴云满城，梦回惊问此何声。","紫台霜急雁初到，沧海月寒潮自生。","宋玉萧条曾作赋，杜陵摇落最关情。","东篱生意依然在，无数黄花照眼明。"]},{"t":"雨后珠江登望","f":"七言律诗","c":["珠江烟水碧濛濛，锦石琪花不易逢。","三岛楼台开日月，二仪风雨动鱼龙。","浮云荏苒团秋扇，野树依微乱晚峰。","越女未知摇落早，轻舟何处采芙蓉。"]},{"t":"九成台次章提学韵时闻王师发金陵","f":"七言律诗","c":["睥睨鸦啼向古台，台前斑竹自花开。","水通湘浦萦如带，山近苍梧翠作堆。","嘉乐也知非野合，倦勤何事复南来。","鸾舆虎旅传消息，心折江城画角哀。"]},{"t":"秋夜梦后作","f":"七言律诗","c":["疏槐宫院罢朝天，淮海干戈有岁年。","未厌西风吹几杖，每依南斗望楼船。","新丰车马黄尘里，故国园林白露前。","归梦忽醒寒漏迥，绮窗斜挂玉婵娟。"]},{"t":"腊月十日奉迎大驾纪事二首 其一","f":"七言律诗","c":["奏凯欢呼大驾回，一时和气满燕台。","端门日丽龙旗入，驰道风清凤吹来。","九庙神灵真有托，百年文运定重开。","都人此日瞻依切，共说君王有将才。"]},{"t":"腊月十日奉迎大驾纪事二首 其二","f":"七言律诗","c":["铙歌鼙鼓尽天声，亭旆金缯载道迎。","上将独乘千里骏，义儿多领四家兵。","车悬虎豹知蒐狝，架叠鲸鲵报武成。","从此鼎彝书镇国，汉文徒幸亚夫营。"]},{"t":"早朝","f":"七言律诗","c":["苑云城树隐苍苍，仙漏销沉宝炬光。","露下貔貅金队冷，风前鹓鹭玉声长。","螭头渐近闻天语，豹尾徐开挹御香。","朝罢宫臣导清跸，空瞻团扇护君王。"]},{"t":"雪后早朝","f":"七言律诗","c":["北风吹雪静芳尘，雪霁千门丽景新。","丹地秖闻鸣玉步，碧天疑有散花人。","寒光掩映龙楼晓，迟日熏成凤沼春。","归向柳边凝立久，试裁巴曲和韶钧。"]},{"t":"侍车驾幸太学恭赋一律","f":"七言律诗","c":["豹纛龙斿拂曙烟，即随清跸下遥天。","衮衣日月宫墙里，冠盖风云俎豆边。","环壁波光摇宝扇，閟坛花气绕金悬。","青衿际此欢无极，共播皇休入诵弦。"]},{"t":"郊祀斋居大兴隆寺与懋贤举之绳武三太史同赋二首得旗字 其一","f":"七言律诗","c":["大驾迎天早练时，端门灯起禁钟迟。","春回御气通黄道，夜静神飙闪翠旗。","龙骑肃分千陛戟，鹤群寒并一禅枝。","泰坛却忆追趋地，云捧珠宫月满墀。"]},{"t":"郊祀斋居大兴隆寺与懋贤举之绳武三太史同赋二首得旗字 其二","f":"七言律诗","c":["璧月彤云澹不移，竹房花影正离离。","僧来秖觉钟磬响，院静不知更漏迟。","都荔有香浮剑舄，穗杨无力拂旌旗。","夜寒银棨巡金钥，吟望圆丘有所思。"]},{"t":"内阁前迎春花开有述","f":"七言律诗","c":["春丛照眼见轻黄，玉署裁诗觉兴长。","唐苑错教催羯鼓，汉宫徒自斗仙装。","龙池日转才分色，凤阁风来细认香。","何事偏承天泽早，结根元自五云傍。"]},{"t":"春兴八首 其一","f":"七言律诗","c":["燕京二月芳草新，天南嗟有未归人。","清泉白石入幽梦，紫燕黄鹂鸣好春。","三殿奔趋连日夕，九衢车马杂风尘。","栖迟凤沼浑何事，吟望渔舟独怆神。"]},{"t":"春兴八首 其二","f":"七言律诗","c":["阊阖千门拂曙开，即随鹓鹭集蓬莱。","云边彩仗分仙掖，日下青旗绕帝台。","扈阁风回初变柳，琳池冰泄半侵苔。","上林春色应无限，空羡文园作赋才。"]},{"t":"春兴八首 其三","f":"七言律诗","c":["太液池头万岁峰，波光回合翠重重。","神人驱石开三岛，天子乘春驻六龙。","紫殿虚无馀御气，碧云迢递忆仙踪。","玉凫黄鹄无消息，长听趋朝午夜钟。"]},{"t":"春兴八首 其四","f":"七言律诗","c":["燕台自昔兴王地，今日垂衣驭四夷。","紫禁烟花连朔漠，黄河烽火望旌旗。","西山积雪辉辉在，北极浮云袅袅垂。","跂马春郊回首晚，五侯歌管未休吹。"]},{"t":"春兴八首 其五","f":"七言律诗","c":["广寒宫殿锁岧峣，汉帝神灵隔绛霄。","阴洞夜凝龙虎气，阳林秋老凤凰条。","金茎瑞露沾朱缀，银浦流云入绮寮。","翠辇不来环佩冷，满庭修竹自萧萧。"]},{"t":"春兴八首 其六","f":"七言律诗","c":["踏青闻幸芙蓉苑，红日未高金吹鸣。","从此宸游多乐事，向来几务太留情。","风传羯鼓南薰殿，云拥鸾旗北斗城。","千载太平知有象，词人先已颂河清。"]},{"t":"春兴八首 其七","f":"七言律诗","c":["风雨潇潇闻曙鸡，春来长忆碧山栖。","烟开篱落花光动，日暖园林菜甲齐。","入馔江鱼供白发，泼醅芳酒对青溪。","刺桐枝上红如锦，自在流莺尽日啼。"]},{"t":"春兴八首 其八","f":"七言律诗","c":["幕府鱼书报越裳，期门龙节发荆湘。","北风鸿雁飞何处，南海渔樵思故乡。","即恐军储非往日，却劳宵旰及殊方。","平林月出闻啼鴂，击剑酣歌意转长。"]},{"t":"谒康陵书感","f":"七言律诗","c":["夏云销尽午风恬，目极烟霄思未厌。","瑶水几年留马迹，鼎湖回首堕龙髯。","泉涂寂寂山当户，松籁萧萧月转檐。","却愧青衫虚十载，对扬无路拜宸严。"]},{"t":"康陵禫祭有述","f":"七言律诗","c":["康陵禫日宿神郊，奏格无声藉白茅。","七庙精灵昭巩洛，二仪风雨积函淆。","明楼灯火鹓鸾集，隧道松杉翡翠巢。","羽猎长杨今涕泪，寸心遥与白云交。"]},{"t":"赠赵景昭归广州","f":"七言律诗","c":["庭闱每入京华梦，消息真从里闬传。","慰我客怀千里外，与君交谊十年前。","心驰珠海云随棹，路入金陵日在天。","好向明时图远大，只今青琐重材贤。"]},{"t":"岁暮书怀次王绳武韵","f":"七言律诗","c":["萧萧松院朔风侵，坐拥重裘力不任。","蓟北暖遥花去眼，天南书断鹊惊心。","层云此日连青琐，芳草何年卧绿沉。","喜有王维同笔砚，清诗时为涤烦襟。"]},{"t":"别吴成甫","f":"七言律诗","c":["金陵此去三千里，玉殿回瞻咫尺天。","两载风烟同逆旅，一帘霜月照离筵。","即看会计苏江左，还有谋猷达帝前。","闻雁裁书应有日，听莺携手是何年。"]},{"t":"三江毛尚书致仕归姑苏留别次韵","f":"七言律诗","c":["笑别鹓行问鹤田，归来林壑故依然。","月明震泽秋应早，柳映阊门地亦偏。","黄阁未曾登扈圣，青山相对更怀贤。","东曹此日情何限，目断冥鸿在远天。"]},{"t":"送三江先生","f":"七言律诗","c":["吴门烟艇故知津，宝带麟衣照莫春。","蕉鹿梦中曾玩世，莼鲈乡里最宜人。","三朝礼乐归青简，八座声华动紫宸。","心折此时瞻望地，潞河南下柳条新。"]},{"t":"寿陈虚白炼师","f":"七言律诗","c":["飙台羽客宴星坛，四座罡风六月寒。","绛节曾随苍水佩，玄田应结紫金丹。","瑶池月冷飞青鸟，珠树云深驻彩鸾。","知尔蓬瀛多浪迹，摩挲铜狄待谁看。"]},{"t":"董学士父母受封","f":"七言律诗","c":["桂坊秋早竹书成，紫诰貤封荷圣情。","天与北门添盛事，人依南斗颂长生。","碧鸡山下棠阴合，丹凤楼前日色明。","笑领龙章齐举案，一麾今觉到蓬瀛。"]},{"t":"送林子行归吴川","f":"七言律诗","c":["莱衣将母羡君行，把酒临岐百感生。","杨柳影凋朝雨净，芰荷香暖暮潮平。","病身与鹤栖萧寺，归梦如云绕粤城。","曾是同舟忍分手，岸花樯燕总关情。"]},{"t":"九月十七日大封宗室奉命充南渭册礼使","f":"七言律诗","c":["胪陛传宣仰圣君，锡茅分器重殷勤。","日临阁道开三殿，风递宫韶出五云。","宝册下时经辇路，金貂行处散炉薰。","即从北极趋南渭，怅别天边鸳鹭群。"]},{"t":"永州楼上春望","f":"七言律诗","c":["萧萧梧竹弄新晴，天畔登楼眼倍明。","湘水碧连云梦渚，粤山青近永阳城。","三春物色怜多病，万里驱驰笑此生。","忽忆玉河垂柳径，紫宸朝罢听流莺。"]},{"t":"别萧潘二通判于淡岩作","f":"七言律诗","c":["五马翩翩度远岑，日浮苍翠满离襟。","同寅合共循良传，异国仍多故旧心。","客思渐随芳草远，春光偏入野棠深。","明朝鼓柁营阳道，回望零陵烟树林。"]},{"t":"游甘露寺同刘士奇作","f":"七言律诗","c":["空香浮动翠巉岩，徙倚珠林驻玉骖。","七泽湍声流日夜，六朝山色落东南。","朱幡向晚情难别，碧院逢秋酒易酣。","萧洒不知归路杳，满天竽籁起松杉。"]},{"t":"归自京师赴常斋钟子夜宴二首 其一","f":"七言律诗","c":["魏阙劳君千里梦，粤巢分我一枝安。","即看春事辞莺燕，且尽芳樽共肺肝。","沙坞雨馀花气近，江城风定角声寒。","相看此夕清狂甚，从此过逢兴未阑。"]},{"t":"归自京师赴常斋钟子夜宴二首 其二","f":"七言律诗","c":["炉烟袅袅篆垂垂，扫径开尊恨到迟。","亭榭风烟仍月夜，江湖花鸟况春时。","金尊玉鲙堪留客，醉舞狂歌果为谁。","却忆去年羁旅地，粤云南望只成悲。"]},{"t":"全节庙","f":"七言律诗","c":["极目胡尘暗帝畿，楼船南去逐斜晖。","已无虎帐鸣金柝，秖有龙潭葬宝衣。","精卫何时填海满，苍梧终日见云飞。","贞魂若化吴宫燕，应是年年一度归。"]},{"t":"大忠祠","f":"七言律诗","c":["谁扶黄屋此长征，夷夏分明万古情。","百粤波涛非帝宅，两厓风雨是天声。","气吞蛇豕频挥剑，力尽驰驱尚请缨。","再拜高祠回首地，满山松桂月微明。"]},{"t":"乙酉守岁","f":"七言律诗","c":["帝城鼓角促朝晖，紫禁烟花锦绣围。","风静笙歌临路发，雪晴乌鹊背人飞。","贪趍魏阙年华换，留滞周南心事违。","柏叶椒花吾祝汝，明年须对老莱衣。"]},{"t":"元日早朝","f":"七言律诗","c":["阁道沙堤雪未乾，马前银烛雾中看。","疏钟欲动飞宫鹊，绛节初齐引佩鸾。","瑞日影浮双阙表，钧天声在五云端。","侍臣赋就阳春曲，未觉琼楼玉宇寒。"]},{"t":"暮春书怀效陈去非","f":"七言律诗","c":["曲肱作梦客不到，游丝满空春正晴。","世事悠悠秖蕉鹿，韶光冉冉但林莺。","蒋陵山远碧云合，郭隗台高芳草平。","踏歌吹剑一翘首，天北天南无限情。"]},{"t":"题雷氏山水卷","f":"七言律诗","c":["羡汝习静栖空山，苍翠无言相对闲。","松花满地云不扫，柴门敞天风为关。","波浮龙鳞晓澒洞，峰横豸角秋孱颜。","丹梯倘许淩绝顶，散发醉呼黄鹤还。"]},{"t":"春夜大醉言志","f":"七言律诗","c":["拔剑起舞临高台，北斗插地银河回。","长空赠我以明月，天下知心惟酒杯。","门前马跃箫鼓动，栅上鸡啼天地开。","倦游却忆少年事，笑拥如花歌落梅。"]},{"t":"白莲二首 其一","f":"七言律诗","c":["水殿盈盈万玉妃，淩波长是步炎晖。","迢遥玉井峰头见，缥缈瑶池月下归。","洛浦雾繁珠作佩，楚台风急翠成帏。","若教解语应愁绝，闻道金笼锁雪衣。"]},{"t":"白莲二首 其二","f":"七言律诗","c":["不见红衣映绿苔，夜长疑有鹭飞来。","蕊珠宫冷香云湿，鱼藻池深素锦开。","太乙驭风摇翠楫，飞琼乘月出瑶台。","露华似慰相如渴，分得金茎满玉杯。"]},{"t":"陵祀次韵刘侍御见寄","f":"七言律诗","c":["园陵报祀开秋序，骢马追趋出帝城。","四塞云山随远近，二仪风雨自阴晴。","金支掩映蛟龙色，玉殿苍凉燕雀声。","怅望轩辕弓剑在，青霄沾洒不胜情。"]},{"t":"重阳次韵答孙贞父","f":"七言律诗","c":["相看京洛共缁尘，拂拭荷衣发兴新。","江上离忧嗟易老，云间归梦恐难真。","飞飞白雁遥怜汝，采采黄花懒寄人。","抱病重阳正愁绝，把君诗句重逡巡。"]},{"t":"省亲三疏获允出郭别亲友","f":"七言律诗","c":["喜闻纶綍卷诗书，万里乘槎信所如。","即办彩衣供色笑，不妨黄发老樵渔。","临岐尚忆公家事，出郭多烦长者车。","南北相望意无限，江空岁晚独愁予。"]},{"t":"文衡山致仕言归次韵二首 其一","f":"七言律诗","c":["十月轩车出紫宸，三年京洛谢缁尘。","北河冰雪偏留客，南国江山久待人。","石室有书曾汗简，扁舟无日不思莼。","此身直在云萝外，谁向中原惜凤麟。"]},{"t":"文衡山致仕言归次韵二首 其二","f":"七言律诗","c":["金銮早上乞休书，疏传当时恐未如。","万里青冥双倦翼，百年黄发几悬车。","阊门日暖繁杨柳，震泽春深足鲤鱼。","知尔登临诗不废，停云回首渺思予。"]},{"t":"除夜赠文徵仲","f":"七言律诗","c":["即看芳草入新年，岂有椒花媚远天。","多病独愁双鬓改，故人相对一灯悬。","匆匆岁色归莺燕，冉冉春声动管弦。","明日试从高阁望，阳和多在五云边。"]},{"t":"丁亥元日","f":"七言律诗","c":["朔云自绕滦河曲，燕树遥连汉苑斜。","彩鹢独依河畔柳，新莺应到苑中花。","三朝礼乐开青琐，万里冠裳拥翠华。","去去沧江回首地，太平歌颂落烟霞。"]},{"t":"客楼春望徵仲见过有赠","f":"七言律诗","c":["楼外河冰春未消，旅魂吟望倦摇摇。","骊黄有路开丹峤，孔翠何心恋赤霄。","燕市风尘通潞渚，吴门烟月满枫桥。","何时坐尔停云馆，幽竹繁花慰寂寥。"]},{"t":"微雨后风沙大作晚泊临清","f":"七言律诗","c":["笑辞钟鼎向山林，去路尘沙苦见侵。","万里舟航淹日月，九河风雨战晴阴。","草堂花竹萦春梦，泽国鱼龙伴夜吟。","心迹不教双寂寞，灯前呼酒漫开襟。"]},{"t":"次韵答廖鸣吾见怀","f":"七言律诗","c":["北风吹女思悠悠，乘兴难移雪夜舟。","建礼昔同鸳鹭序，裁诗今在凤凰楼。","岸花樯燕催春色，洛水秦山入暮愁。","多病可堪回首远，吏情吾已付沧洲。"]},{"t":"丁亥除夕","f":"七言律诗","c":["旅馆频年过岁除，莱衣今夕乐何如。","摇摇蜡炬轻风里，浅浅霞杯细雨馀。","江海只便鱼入馔，烟霞惟恐鹤传书。","等閒又被梅花恼，漏泄春光满敝庐。"]},{"t":"元旦","f":"七言律诗","c":["南国浮云向晓开，日华初上钓鱼台。","东风又与縻芜绿，老屋惟应燕子来。","万里晨昏逢岁改，三年供奉忆朝回。","沧溟不似君恩阔，起舞尊前莫放杯。"]},{"t":"英德别杜生兄弟","f":"七言律诗","c":["扁舟六月度浈水，英德县前鲈已肥。","别尔弟兄难废酒，驱人岐路易沾衣。","沧江急雨群龙出，古峡闲云独鹤飞。","返棹相看情不断，倚门真觉梦同归。"]},{"t":"感秋二首用南津胡宪长趣驾韵 其一","f":"七言律诗","c":["淅淅秋风吹岸沙，西江迁客思无涯。","浊醪粗饭足娱老，去燕来鸿犹念家。","百年洛涘愧潘岳，九日龙山怀孟嘉。","故园咫尺不归去，辜负东篱无数花。"]},{"t":"感秋二首用南津胡宪长趣驾韵 其二","f":"七言律诗","c":["淅淅秋风吹雨来，自怜樗散未须培。","水边白鸟背人去，霞外青山待我回。","抱病江湖长对酒，侧身天地数登台。","故园只在扁舟上，三径黄花万树梅。"]},{"t":"南溪卷为佴都帅","f":"七言律诗","c":["南溪分得扬之水，岩姿林霭相光辉。","主人燕坐列霜戟，童子清歌调雪衣。","弦琴每觉薰风入，载酒直随明月归。","我亦沧洲曾结宇，吏情长恐与心违。"]},{"t":"秋夜对菊","f":"七言律诗","c":["且随麋鹿走山林，岂合簪缨击此心。","永夜鼓钟欺鬓短，小楼风露报秋深。","鸾声自作孙登啸，龙卧谁为梁甫吟。","潇洒不知贫与病，东篱元有万黄金。"]},{"t":"苍梧初发","f":"七言律诗","c":["苍梧北望尽蛮荒，云黑山青烟雾黄。","旌旆行随日隐见，蒙冲坐觉天低昂。","鼋鼍乘雨出岩穴，翡翠挟春鸣桄榔。","旅怀历乱不可尽，芳草萋萋弥岸长。"]},{"t":"桂林元夕","f":"七言律诗","c":["何处笙歌入座闻，即看陆海在人群。","星桥暗度重轮月，火树晴开五色云。","湘水未逢天北使，漓江犹驻粤南军。","江湖心事年年在，徙倚东风酒易醺。"]},{"t":"横州伏波庙","f":"七言律诗","c":["高滩危石锁崔嵬，长夏风烟午未开。","南海楼船从此去，中原冠冕至今来。","武陵一曲风尘静，铜柱双标日月回。","千载伏波祠宇在，汉朝何事有云台。"]},{"t":"旅感","f":"七言律诗","c":["尘事熏心千种在，晨昏回首一星周。","枕前风月照归梦，帘外西山窥客愁。","短策干时何所得，薄田供岁未须求。","他年北极怀明主，当日东陵有故侯。"]},{"t":"初秋","f":"七言律诗","c":["玉河杨柳已萧萧，羁思逢秋转寂寥。","亲舍每疑云外近，长安翻觉日边遥。","浮名肯似莼鲈美，壮志宁随髀肉消。","自笑行藏浑未卜，巫阳堪问竟谁招。"]},{"t":"秋夜大兴隆寺玩月","f":"七言律诗","c":["玉壶对酒秋色满，金地坐看明月高。","北戍不随胡马暗，南巡应照圣躬劳。","山河有影看蓬鬓，风露无声生缊袍。","忽忆越江垂钓叟，流光千顷一浮舠。"]},{"t":"得七月家书志喜","f":"七言律诗","c":["红叶声中醒客梦，白云飞处忆亲庐。","情多岂保鬒不变，计拙乃为饥所驱。","燕颔果谁还有相，羊肠何路是无虞。","临风正觅伤秋句，忽领平安两字书。"]},{"t":"送祁惟允","f":"七言律诗","c":["执手别君何郁纡，帝城秋色野踟蹰。","离情不学晓云淡，知己渐随烟柳疏。","去国未须言勇退，还家聊且赋閒居。","想应明主不相弃，谁合南山有弊庐。"]},{"t":"赠西蜀胡秀才","f":"七言律诗","c":["遥遥蜀道亘天端，来去惟君不作难。","来为慈颜欣奉檄，去缘皤发倦弹冠。","柳摇燕市听莺别，云拥峨眉驻马看。","索句赠君还自笑，一年为客向长安。"]},{"t":"赠陶二尹之任元城","f":"七言律诗","c":["风流此日陶彭泽，善唱吴歈向别筵。","制锦正当佳丽地，弹冠初遇中兴年。","一庭诗景孤松里，疋马春风立柳边。","倾盖相逢又分手，金台凉月夜娟娟。"]},{"t":"寄梁应房","f":"七言律诗","c":["去年萧寺忆殷勤，长剑高歌入夜闻。","异国风烟能慰我，同年交谊不如君。","落霞秋倚新丰树，疋马晴瞻震泽云。","南北祇今成怅别，夜来樽酒梦论文。"]},{"t":"送余崇一使蜀","f":"七言律诗","c":["凤凰衔诏出蓬莱，剑气峥嵘拂曙开。","万里风烟驰蜀道，五云宫阙梦燕台。","浣花溪在搜唐迹，洗墨池荒忆汉才。","闻道故园沧海上，星槎争羡自天回。"]},{"t":"荆庭春恨和潘源鲁","f":"七言律诗","c":["东风庭院雨丝丝，姜被寒生梦后悲。","浅绿正添鸿雁沼，轻红初上鹡鸰枝。","流年未觉音尘尽，往事空诒肺腑知。","断送一番吟鬓白，可怜荆树似秋时。"]},{"t":"赠梁明仲","f":"七言律诗","c":["都门杨柳映愁生，久客怀归此送行。","乡梦昔曾随去马，春光今已别流莺。","舟移北渚龙光窅，路入南天剑气明。","他日一尊寻旧约，白云溪上濯尘缨。"]},{"t":"席中赠伦彦蕃","f":"七言律诗","c":["看君意气薄青霄，京邸相逢即久要。","凤沼每传贤父子，雁行多在圣明朝。","虹横楚水朝看剑，月满吴门夜听潮。","何事春明携手地，满堤垂柳正萧萧。"]},{"t":"别伦彦周侍御","f":"七言律诗","c":["青藜灯火同高阁，皂盖声华独内台。","日月祇随燕树转，云山长羡粤鸿回。","劳劳世事关蓬鬓，黯黯离怀付酒杯。","姜被莱衣荣子去，风江烟艇待谁来。"]},{"t":"宜阳八景次东溪郑尚书韵八首 其一 黄岑叠翠","f":"七言律诗","c":["晓入宜阳见万峰，鸡声人语共疏钟。","停车最爱黄山好，滴袖俄惊翠黛浓。","陆海鱼龙凭砥柱，青天波浪出芙蓉。","淩风欲挟飞仙去，直上蓬莱第一重。"]},{"t":"宜阳八景次东溪郑尚书韵八首 其二 白水垂虹","f":"七言律诗","c":["扣舷何处有渔歌，泉拥西山景最多。","云外恍疑垂玉蝀，人间真觉近银河。","静涵桂魄天同色，流入桃花锦作波。","若到春郊频极目，东风吹润遍嘉禾。"]},{"t":"宜阳八景次东溪郑尚书韵八首 其三 玉溪春涨","f":"七言律诗","c":["玉溪流水碧沉沉，巧算还谁测浅深。","细雨斜风浑二月，鲸吞鼍作忽千寻。","敲诗日忆澄江练，倚仗时闻绿树禽。","何事临流歌仰止，三星桥外有遥岑。"]},{"t":"宜阳八景次东溪郑尚书韵八首 其四 宝刹云幡","f":"七言律诗","c":["碧树苍烟锁绀园，四民曾此礼三尊。","岧峣地上开金刹，仿佛云中立翠幡。","山色可能随世改，烧痕长是到秋繁。","凭高莫漫搜陈迹，时倚衡云望蓟门。"]},{"t":"宜阳八景次东溪郑尚书韵八首 其五 蒙洞泉香","f":"七言律诗","c":["景星灵洞足探奇，石上浮觞漫尔为。","碧落玉书空往梦，葛巾藜杖可芳时。","香分下泽烟花绕，暖入东陂雁鹜知。","羽客不归瑶草暮，桃源何处问蛾眉。"]},{"t":"宜阳八景次东溪郑尚书韵八首 其六 良岩龙隐","f":"七言律诗","c":["独倚苍岩玩碧澜，共知龙向此中蟠。","九天空阔疑雷动，万木萧疏带雨寒。","马鬣不教桑楚歉，鸟耘那见稻畦乾。","行藏笑与髯翁道，潜跃由来不是难。"]},{"t":"宜阳八景次东溪郑尚书韵八首 其七 榜山晴旭","f":"七言律诗","c":["列岫排云切太苍，曲江银榜宛如长。","当衙已献千重秀，带日还成五色光。","秋净烟霞开锦绣，春深风雨散红香。","地灵人杰从来是，满耳蜚声说庙廊。"]},{"t":"宜阳八景次东溪郑尚书韵八首 其八 普化晚钟","f":"七言律诗","c":["涉水循山问化宫，翠微深处有村舂。","僧来且共松间坐，溪午遥闻烟外钟。","贝叶昙花空寂寂，琼帘珠栱自重重。","旧游回首思长乐，无限诗情到晚浓。"]},{"t":"华节亭别亲友","f":"七言律诗","c":["宿雨冥冥晓正开，故人遥放酒船来。","啼莺语燕催春事，绿水红亭照客杯。","别梦绸缪犹粤海，片帆迢递又荆台。","临岐欲尽分携意，满目停云郁未裁。"]},{"t":"洸口寄伦子彦式","f":"七言律诗","c":["魁冈南望隔湘烟，闻道征帆别后悬。","楚粤山川空寄梦，江湖风雨正连天。","明光起草逢今日，京洛看花忆去年。","岐路祇今随使节，可堪心折五云边。"]},{"t":"赣州紫霄岩赠林二山","f":"七言律诗","c":["凭空飞观倚岧峣，风磴盘盘入紫霄。","章贡滩声天外落，燕云山色日边遥。","百年气谊堪杯酒，万里离忧自市朝。","笑与使君图后会，扁舟何日重相招。"]},{"t":"夏日游何氏园","f":"七言律诗","c":["漠漠朱光接翠寒，萧萧林樾隐风湍。","浣花暂尔栖疏放，古柏终当宿凤鸾。","遂有卧龙清洛水，还从飞雁望长安。","种榆袅袅成何事，心折云边金露盘。"]},{"t":"放船","f":"七言律诗","c":["城乌翻月鼓沉沉，虎丘寺前初放船。","青山白水晚如画，枫叶芦花秋可怜。","皇华万里但原隰，供奉三年犹俸钱。","鸱夷邈矣不可见，隔浦缓歌闻采莲。"]},{"t":"海珠别方塘汪宪副","f":"七言律诗","c":["海珠山下寒潮生，击鼓放船君欲行。","酾酒千巡谷鸟啭，粤城十月江花明。","碧鸡金马在何处，游子孤臣俱有情。","此去登临不同赏，倚楼诗句向谁成。"]},{"t":"送范衢村大参","f":"七言律诗","c":["桂州城南漓水流，白蘋芳芷满中洲。","即看彩鹢随春色，聊遣清尊消别愁。","画省交游成旧雨，彤云瞻望及新秋。","相逢若问鸱夷子，已向江湖买钓舟。"]},{"t":"大藤峡徭老","f":"七言律诗","c":["大藤勋业使人疑，今日褰帷始见之。","每忆韩公成感叹，且令徭老望威仪。","江山道梗空千里，兵甲屯云又一时。","闻道招安成妙算，从前真觉费王师。"]},{"t":"洮阳野次","f":"七言律诗","c":["画船箫鼓拥青衿，岂有当年木铎音。","故国烟花那在眼，长途风雨若为心。","三湘秀色来天地，五岭华风自古今。","耿耿有怀成野宿，梦魂虚绕泰山岑。"]},{"t":"元日","f":"七言律诗","c":["晓来簪弁换荷衣，遥望祥云夹日飞。","北塞风尘应已静，南溟楼橹竟安归。","乾坤脉脉移花柳，林壑欣欣动蕨薇。","谁在青冥生白发，且持春酒对春晖。"]},{"t":"粤山诗社试笔分得清字","f":"七言律诗","c":["碧山云卧倚江清，衣马何人献岁行。","丽日楼台明万井，轻风箫鼓庆三城。","东南漂泊嗟悬磬，西北驱驰费请缨。","且向烟萝开野酌，渔樵相与话升平。"]},{"t":"人日和陈天游韵 其一","f":"七言律诗","c":["骀荡春光满隐窝，放狂判到鬓双皤。","柳条色映青丝骑，柏叶杯翻白纻歌。","莺燕不嫌三径僻，风烟偏在五陵多。","年来无地寻花胜，世道应随东逝波。"]},{"t":"人日和陈天游韵 其二","f":"七言律诗","c":["东风吹遍海天涯，隐几萧条忽见花。","人日钩诗谁对酒，草堂携鹤自移家。","冲星剑佩真吾事，满地江湖又岁华。","何事步兵从晋室，春来犹咏救侯瓜。"]},{"t":"天开图画亭","f":"七言律诗","c":["突兀茅斋跨石台，玉杯瑶席倚云开。","天边湘色褰帷入，地底漓江逐马来。","北极自勤瞻阙梦，西山谁有济时才。","侧身天地酣歌里，鸿雁冥冥首重回。"]},{"t":"肇庆李东渠中丞邀游洒然亭次韵二首 其一","f":"七言律诗","c":["岭海栖迟有岁年，草堂今喜识高贤。","钓残野水从鱼乐，锄罢寒葵带露鲜。","世事驱驰真梦里，天涯谈笑且尊前。","朔云他雨劳相问，犹记萍踪自洒然。"]},{"t":"肇庆李东渠中丞邀游洒然亭次韵二首 其二","f":"七言律诗","c":["崧台今夕是何年，投辖倾杯见此贤。","半亩方塘开罨画，一亭明月共澄鲜。","习池已觉心俱醉，宣室还看席屡前。","勋业古来戎马地，可能无意勒燕然。"]},{"t":"苍梧言归口号","f":"七言律诗","c":["十载行囊一素琴，寥寥天地几知音。","渊明已有归来赋，和靖初无禄养心。","北郭晚田堪白酒，东篱秋菊尽黄金。","扁舟一去随明月，回望苍梧空绿阴。"]},{"t":"丙申元日","f":"七言律诗","c":["阳吹朝来动远空，九重春与万方同。","金盘北望思承露，玉琯东回验相风。","日月催人双鹤鬓，江湖容我一渔翁。","十年旧梦成追忆，曾侍朱衣紫殿中。"]},{"t":"灯夕立春","f":"七言律诗","c":["东风澹澹月团团，灯市逢春倍觉欢。","汉苑烟花曾驻马，秦楼歌舞更骖鸾。","传柑错忆红云殿，缕菜惊看白玉盘。","官柳野梅俱在眼，莫教长笛倚阑干。"]},{"t":"和邓沃泉宪副元夕","f":"七言律诗","c":["升平灯火几喧阗，笑指东风十二年。","陆海鱼龙春变化，艳阳桃李夜暄妍。","镐京尚忆红云宴，郢曲遥传白雪篇。","同是江湖怀圣主，步随明月望尧天。"]},{"t":"暮春赠别李仪部四首 其一","f":"七言律诗","c":["离梦摇摇倦倚阑，江城春共一尊残。","马前红雨真堪驻，鸿外青山正耐看。","粤国龙蛇蟠大泽，汉家卿相满长安。","趋朝好在南薰殿，莫待金风吹玉鸾。"]},{"t":"暮春赠别李仪部四首 其二","f":"七言律诗","c":["满院樱桃齐作花，柳条袅娜牵风斜。","即看春事遽如许，自信吾生安可涯。","南国浮云供伏枕，北山孤鹤望移家。","酒阑相送柴门莫，月满遥林明钓沙。"]},{"t":"暮春赠别李仪部四首 其三","f":"七言律诗","c":["石门云树浩悠悠，鸿雁拚飞并彩舟。","君去可堪还北望，此心无尽亦东流。","月明桂馆烟花晓，风落榆关笳鼓秋。","倾倒渌尊频看剑，江湖何处有离忧。"]},{"t":"暮春赠别李仪部四首 其四","f":"七言律诗","c":["荔子红时风满枝，彤云飘忽望京师。","瑶坛晓日銮舆度，珠树微凉彩仗移。","北阙已新周典礼，南宫曾识汉官仪。","十年畎亩丹心在，跂尔承恩向玉墀。"]},{"t":"草堂酌别刘仙令","f":"七言律诗","c":["东方之日赤轮囷，照我庭前双树根。","仙凫到门化飞舄，神鱼入网开清尊。","南归暂与山水会，北去莫受风尘昏。","玉墀青琐寄消息，夜夜梅花劳梦魂。"]},{"t":"暮春醉游","f":"七言律诗","c":["东风飘飘吹絮衣，沉醉不忧生计微。","粤台云朗木客啸，珠寺花深江燕飞。","山川有恨天相罩，薇蕨无言春自晖。","已抛簪弁逐渔钓，浩浩放歌明月矶。"]},{"t":"登观海楼醉后作","f":"七言律诗","c":["逍遥短褐沧洲上，突兀高楼霄汉间。","潮落鱼龙犹并出，日晴鸥鹭已知还。","冲帆野色来千里，入座春声殷万山。","飞絮又随杯酒尽，东风何事亦偷閒。"]},{"t":"缁尘","f":"七言律诗","c":["缁尘休问旧貂裘，十月轻衫试薄游。","春事只看芳草变，清尊聊尽白云求。","雪车冰柱燕山路，枫叶芦花楚水舟。","偶忆少年成独笑，夜调玄鹤上丹丘。"]},{"t":"赠别黄子章北上次铁桥司马韵二首 其一","f":"七言律诗","c":["沙头寒日照津旗，南雁初飞北棹移。","谢客池塘新入梦，于门车马重相期。","江湖冉冉冰霜尽，花柳欣欣雨露私。","春近可堪人渐远，停云应是渺予思。"]},{"t":"赠别黄子章北上次铁桥司马韵二首 其二","f":"七言律诗","c":["芙蓉阙下绾银章，彩笔当年逐俊良。","沙苑月明驰骏足，掖垣花暗散鹓行。","西山爽气朝应在，南海遗珠夜有光。","若到凤池相问讯，扁舟今在白云乡。"]},{"t":"粤王台怀古二首用王李二子韵 其一","f":"七言律诗","c":["粤城秋日转觚棱，与客登台感废兴。","孤鸟迥随云影没，野花寒带露华凝。","楼船有路天低海，剑玺无踪谷变陵。","留得当年歌舞地，断猿清夜啸烟藤。"]},{"t":"粤王台怀古二首用王李二子韵 其二","f":"七言律诗","c":["百年天地静风尘，吊古临觞莫怆神。","鸟雀似闻弦管夜，云霞犹见绮罗春。","湟关北去元通汉，肄水南来不向秦。","绝胜楚台暮摇落，白蘋空对独醒人。"]},{"t":"梦游洞庭作","f":"七言律诗","c":["瑶台今夕侍宸游，五色云中驾彩虬。","银汉有章回紫极，碧天如幕护皇州。","未央日转芙蓉殿，太液波涵翡翠楼。","欲奏霓裳先按舞，凤笙吹彻洞庭秋。"]},{"t":"送程太史舜敷二首 其一","f":"七言律诗","c":["十月露葵青满溪，嘤嘤山鸟向人啼。","梯飙直与鸾霄近，步壑回看象纬低。","池上引杯玄鹤舞，花边多烛紫骝嘶。","湘弦一奏清商曲，离思如云暗柳堤。"]},{"t":"送程太史舜敷二首 其二","f":"七言律诗","c":["供奉当年紫禁东，扁舟吾已谢鹓鸿。","烟花北望开秦苑，江海东流绕汉宫。","婺郡趋庭双舄远，粤台倾盖一尊同。","白头迟尔青冥翼，兴在骊驹感慨中。"]},{"t":"苦雨","f":"七言律诗","c":["即看苍翠逐人来，何限藩篱向水开。","北极云烟连粤树，南溟波浪接燕台。","蘅皋惯见蛟龙舞，草屋长闻燕雀回。","自笑野夫贫亦得，小楼高枕胜蓬莱。"]},{"t":"夏日方氏园池小集分韵得狂字","f":"七言律诗","c":["宝月团团山雾黄，薰风拂拂水烟苍。","尊前白纻翻新调，槛外红蕖妒艳妆。","柳榭拂云来鹳鹤，兰桡冲雨散鸳鸯。","习池金谷风流在，谁道江湖放酒狂。"]},{"t":"中秋白莲沼上见月","f":"七言律诗","c":["穆穆金波照玉泉，人间天上共婵娟。","云移宝镜初离匣，风定骊珠正在渊。","万里河山看桂阙，九霄环佩听娥仙。","芙蓉不为烟霜老，更觉光辉异昔年。"]},{"t":"秋夜卧疾","f":"七言律诗","c":["西风瑟瑟到芙蓉，寒入琼楼十二重。","极浦云烟连朔雁，满城砧杵间疏钟。","宫中思妇歌秋扇，塞上征人望夕烽。","何事文园止消渴，金盘应有露华浓。"]},{"t":"腊月立春感怀次梁南皋韵三首 其一","f":"七言律诗","c":["岁晚春阳开淑景，海滨林薄振暄风。","朱门杂沓笙歌里，皂帽逍遥水石中。","南国暖回莺易至，北河冰结鹢难通。","沉香亭上花应发，谁奏清平入汉宫。"]},{"t":"腊月立春感怀次梁南皋韵三首 其二","f":"七言律诗","c":["粤城歌吹晓纷纷，隐几萧条实饱闻。","生菜又从年里见，彩花曾向御前分。","有情北雁随迟日，无赖西郊自密云。","最羡梁鸿诗律好，五噫何事怅离群。"]},{"t":"腊月立春感怀次梁南皋韵三首 其三","f":"七言律诗","c":["萱草淩寒先自生，皋禽掠暖复交鸣。","百年未满秖须醉，万事逢新殊可惊。","楚地雪霜当岭尽，粤台云物到春明。","登临一笑人间世，犹有沧浪堪濯缨。"]},{"t":"游泰泉席上与陈京兆天游邓宪副沃泉分韵得文字","f":"七言律诗","c":["一尊何处可论文，买得青山近白云。","野色不随秋气改，松涛长共涧声闻。","剪茅渐作花三径，种稻频来鹤数群。","吟眺不知仙客去，满林萝月白纷纷。"]},{"t":"登泰泉山椒和天游峰字韵二首 其一","f":"七言律诗","c":["万仞烟霞一短筇，绿蒲黄菊尽仙踪。","安期海上空遗舄，崔相庵前秖断峰。","道在沧洲应易得，笑缘尘世每难逢。","何时更定云岑约，幞被同听野寺钟。"]},{"t":"登泰泉山椒和天游峰字韵二首 其二","f":"七言律诗","c":["瑶空飞翠可扶筇，仙侣淩秋觅异踪。","樵径风清闻落木，海门霞起混高峰。","蟹泉瀹茗吟边酌，虹涧寻花醉里逢。","翻笑十年尘土梦，马蹄空趁景阳钟。"]},{"t":"南园吊古用梨韵","f":"七言律诗","c":["南园秋草蔚萋萋，来谒新祠路不迷。","五岭炫烟曾跃马，百年忠愤但闻鸡。","逢崖往事西风冷，蹈海高名北斗齐。","却恨天津明月夜，杜鹃啼血上棠梨。"]},{"t":"次韵答周八崖宪长见怀","f":"七言律诗","c":["六月芙蓉开绛英，粤池遥带楚湘清。","山中麋鹿堪吾友，地上麒麟羡尔行。","玉殿翠云怀北极，石林红日卧前荣。","瑶华忽慰音尘隔，南浦悠悠梦旆旌。"]},{"t":"春日田园杂兴次郑大尹韵 其一","f":"七言律诗","c":["农圃归来荷圣朝，暖风迟日出迢遥。","青黄夹路携儿看，花竹成畦课仆浇。","牛带寒鸦过别浦，叶随流水聚平桥。","年来自觉疏慵甚，无奈流莺早见招。"]},{"t":"春日田园杂兴次郑大尹韵 其二","f":"七言律诗","c":["黄犊悠悠不用鞭，绿杨袅袅未舒绵。","即看喜气通丘壑，已有和风到海天。","陌上斗歌人似月，花间吹笛酒如泉。","年来种秫开三径，不为青山有杜鹃。"]},{"t":"暮春效白沙","f":"七言律诗","c":["烟树苍苍黄鸟飞，草堂春晚故人稀。","北风卷雪马犹去，西水漫天船未归。","性拙久拚玄鬓改，家贫长恐素心违。","雨馀天阔芳蹊暖，无数红香点褐衣。"]},{"t":"春兴和邓沃泉韵","f":"七言律诗","c":["春回盘谷瘴烟消，千古青云近斗杓。","丹凤有书传此日，白驹何事永今朝。","粤山采药穿云倦，珠海寻僧泛月遥。","招得草堂猿鹤伴，碧桃花里醉仙瓢。"]},{"t":"咏灯花次余仲栗韵","f":"七言律诗","c":["天涯芳草翠连空，惟有寒灯相对红。","金粟光芒如向月，银缸开谢肯随风。","赤城霞起明窗里，太乙星移绛帐中。","忽忆炬莲随佩马，十年恩宠向谁浓。"]},{"t":"送李稚大广右视学","f":"七言律诗","c":["吹剑当年歌昔游，十年尘梦对三洲。","湘山似戟马前出，楚水如丝天际流。","监禄岂知终化俗，伏波何用更封侯。","离弦莫奏清商曲，梧叶萧萧已报秋。"]},{"t":"九月与内姻兄弟登龙冈答梁应民二首 其一","f":"七言律诗","c":["龙冈亭榭倚岧峣，采采黄花不惮遥。","陟岵看云移白日，长松高茑入丹霄。","风回古寺千山叶，野阔寒江万里潮。","曝背有怀还北望，可堪关塞正萧萧。"]},{"t":"九月与内姻兄弟登龙冈答梁应民二首 其二","f":"七言律诗","c":["江湖独卧逢人少，风日重阳发兴赊。","碧海波光依帽落，白云山色抱檐斜。","松萝正尔堪杯酒，蓬鬓何曾愧菊花。","帝圃仙台休更问，笑看天地有烟霞。"]},{"t":"南江卷为冯侍御子仁题","f":"七言律诗","c":["南江之水向南流，谪仙结庐栖上游。","真源混混自天地，巨浪轰轰连斗牛。","鸣皋玄鹤月当夜，入馔白鱼风报秋。","浩歌放浪渺然去，为尔芦间寻钓舟。"]},{"t":"灵洲晓发","f":"七言律诗","c":["妙高台前郁水流，宝地祇林何太幽。","雨晴山向镜中出，潮长舟从天上游。","鹏风忽送扶光晓，蜃月犹含珠海秋。","一尊取醉挂帆去，渺渺沧波飞白鸥。"]},{"t":"峡山寻铁壁泉源宴挹泉亭次王十竹韵二首 其一","f":"七言律诗","c":["云构初成风籁清，翠寒当户接流声。","禺阳凤竹自秋色，赵叟鱼台空月明。","铁壁长年锵玉佩，沧江终日驻霓旌。","酒阑更觅飞来迹，直上蓬山绝顶行。"]},{"t":"峡山寻铁壁泉源宴挹泉亭次王十竹韵二首 其二","f":"七言律诗","c":["萧寺重过亭榭新，十年烟艇实藏身。","有情峡鸟催沽酒，无赖江花笑问津。","极北云烟看欲近，天南冰雪坐疑真。","尊前却忆乘骢使，彩笔题诗合有神。"]},{"t":"飞来寺右林莽中寻达磨石小憩戏作一转语","f":"七言律诗","c":["淩空飞锡结嶙峋，薝卜香中草自春。","鸟度云移今此世，鸿冥天阔我何人。","羲娥断送千年梦，龙象终成一聚尘。","便合拈花发微笑，沧波无语月华新。"]},{"t":"舟次韶州奉怀黎韶山用赠行韵","f":"七言律诗","c":["对酒联舟忽异乡，曲江回望粤山长。","九成台上箫韶远，二相楼前草木香。","春殿独摇苍水佩，秋风偏洒碧荷裳。","徘徊家国情何限，云白天青自一方。"]},{"t":"秋日宴凤来亭呈同游符陈二使君","f":"七言律诗","c":["危亭开宴逼秋穹，五马同游一马骢。","岐路即看千里近，劝酬真觉四愁空。","楚山北向青如簇，肄水南来曲似虹。","笑指九成台上凤，来仪应在碧梧中。"]},{"t":"扬历岩醉后咏月","f":"七言律诗","c":["明牧招携上翠微，金尊倾罢玉蟾飞。","桂枝似向淮岩出，纨扇疑从汉苑归。","泽国鱼龙疏作雨，江干鸥鹭久忘机。","广寒共是曾游客，莫唱开元旧羽衣。"]},{"t":"过岭瞻望张丞相祠","f":"七言律诗","c":["蹇蹇宗臣起海涯，荆州南去为谁家。","鼓鼙尘里青骡远，鹰隼风前紫燕斜。","揭日声华垂宇宙，格天英采在云霞。","十年旧路生秋草，长忆寒梅绕树花。"]},{"t":"登吴山驿楼晓望","f":"七言律诗","c":["楼外缁尘望不昏，榣山高峙彩云屯。","潮声近欲兼溟渤，树色遥应接蓟门。","桑柘影疏嗟亢旱，芰荷衣薄藉朝暾。","凭高倚剑歌回首，家在天南烟水村。"]},{"t":"立春日东墅探梅简刘东溪中丞","f":"七言律诗","c":["招携东墅探寒梅，冷蕊疏枝尚未开。","绣豸金貂频促席，吴歌楚舞肯停杯。","东皇已正苍龙驭，灵女虚传赤凤来。","风籁萧萧归路晚，采芳何处是春台。"]},{"t":"宫僚燕集次许松皋冢宰韵四首 其一","f":"七言律诗","c":["玉河皓皓树苍苍，歌管催春入燕觞。","四海簪缨趋圣主，万年圭鬯属元良。","风云灿烂铜扉里，日月光华玉殿傍。","留滞周南通籍晚，只将麟趾咏姬昌。"]},{"t":"宫僚燕集次许松皋冢宰韵四首 其二","f":"七言律诗","c":["桂宫兰殿倚穹苍，绮席淩寒绿满觞。","银榜自今晖日月，金台从古重贤良。","鸾镳合沓瀛洲里，凤吹飘摇太液傍。","既醉不愁归路暝，上台光彩属文昌。"]},{"t":"宫僚燕集次许松皋冢宰韵四首 其三","f":"七言律诗","c":["宫槐院柳竞寒苍，仙侣开筵荐羽觞。","周诵师资曾作圣，桓荣稽古亦称良。","榣山睇视西山外，南斗追趋北斗傍。","自笑冥鸿随羽翼，即从诒宴颂隆昌。"]},{"t":"宫僚燕集次许松皋冢宰韵四首 其四","f":"七言律诗","c":["前星炯炯天苍苍，高云斐亹明霞觞。","鸿逵岂谓羽仪少，鹤禁正须筹策良。","燕京馆阁玉霄上，魏阙衣冠珠斗傍。","阳春忽奏郢中调，万岁飞龙应寿昌。"]},{"t":"重午谩兴","f":"七言律诗","c":["萧艾青青烟雨中，锦囊谁与奏薰风。","骖驔骏骑来燕市，迢递翔鶤仰汉宫。","竹叶谩随人意绿，榴花孤倚客窗红。","去年此日衡门下，笑看菖蒲碧涧东。"]},{"t":"冬至早过承天门时同行者赵校书罗赞善唐司谏闵中允谢司直","f":"七言律诗","c":["去年济水逢长至，今日蓬山得并游。","西苑未闻归大内，南郊何处礼圆丘。","葭传淑气三千界，鼎现丹光十二楼。","最是昔曾趋走地，朝阳依旧殿东头。"]},{"t":"曲江晓发赠别符颖江太守","f":"七言古诗","c":["曲江流水混晴霞，岭树阴阴背郭斜。","八月扬舲趋鹤禁，十年垂钓向鸥沙。","旷筵挥麈欢无极，明牧连驺兴未涯。","锦寺剧谈支遁躅，帽亭遥指邵平瓜。","隋珠几见传仙掖，韶石重来驻使槎。","忧世旧愁怜杜甫，阜民新调协虞华。","芙蓉国里三千首，烟雨楼前十万家。","杯酒论文更何地，春风应在紫薇花。"]},{"t":"恭谒孝陵侧望懿文墓","f":"七言律诗","c":["紫金积翠镇重泉，绛节扬灵护九玄。","五色云车龙渺渺，万行珠树鹤翩翩。","鼎湖风雨秦淮水，缑岭烟霞句曲天。","玉玺一从归冀北，郁葱佳气自年年。"]},{"t":"玉亭侍家慈宴坐述怀","f":"七言律诗","c":["玉亭幽胜颇宜人，喜奉潘舆眺望频。","龙阙日高吴苑曙，凤台花发蒋陵春。","巢林乌鸟声偏乐，入馔鲥鱼味更新。","犹自倚楼思梦里，南溟天阔有垂纶。"]},{"t":"子夜四时歌八首 其一","f":"五言绝句","c":["采桑南陌去，共欢桑下嬉。","归来理机素，成匹待何时。"]},{"t":"子夜四时歌八首 其二","f":"五言绝句","c":["黄鸟双双飞，园林春意早。","欢爱绯桃花，侬爱菤葹草。"]},{"t":"子夜四时歌八首 其三","f":"五言绝句","c":["团团合欢扇，摇动生薰风。","辗转罗帏里，时复障颜容。"]},{"t":"子夜四时歌八首 其四","f":"五言绝句","c":["乘凉登水榭，见那采莲船。","石阙映芙蓉，含悲谁复怜。"]},{"t":"子夜四时歌八首 其五","f":"五言绝句","c":["猛风吹梧桐，玉露坠金井。","蹋歌人不闻，明月照双影。"]},{"t":"子夜四时歌八首 其六","f":"五言绝句","c":["门前霜枫树，洒泪积成许。","蛛网罥黄蘖，腹中苦思汝。"]},{"t":"子夜四时歌八首 其七","f":"五言绝句","c":["白雪满庭户，朱火耀窗牖。","清歌侑兰觞，郎笑揽侬手。"]},{"t":"子夜四时歌八首 其八","f":"五言绝句","c":["枯木噪寒雀，开门欢正来。","炭炉火未冷，思心欲成灰。"]},{"t":"送刘符卿使楚","f":"五言绝句","c":["扬舲向荆楚，渺渺烟波涛。","河桥挥手后，酒醒明月高。"]},{"t":"梁子席上赏葵","f":"五言绝句","c":["萧飒天南鬓，羁留冀北身。","凭将向阳意，一为问花神。"]},{"t":"风雨与张景川酌","f":"五言绝句","c":["风雨送深秋，千山木叶流。","黄花犹自艳，知为故人留。"]},{"t":"禾雀","f":"五言绝句","c":["两三啁哳雀，飞飞自容与。","天地无网罗，郊原熟禾黍。"]},{"t":"玄堂八景为罗大参题 其一 绿潭灵源","f":"五言绝句","c":["大岗发灵源，绿潭何迤逦。","松涛翻翠寒，秀色亘千里。"]},{"t":"玄堂八景为罗大参题 其二 上涌烟村","f":"五言绝句","c":["烟树横一抹，微茫混天色。","林疏见夜灯，点点讶奎壁。"]},{"t":"玄堂八景为罗大参题 其六 丹桂山香","f":"五言绝句","c":["丹桂孤巍巍，移根自蟾穴。","空翠从风来，万古香不灭。"]},{"t":"玄堂八景为罗大参题 其三 紫峒天衢","f":"五言绝句","c":["天衢在丹霄，紫峒相与通。","常有五色云，飞绕蓬莱宫。"]},{"t":"玄堂八景为罗大参题 其四 东冈晓日","f":"五言绝句","c":["商歌闻饭牛，长夜嗟未旦。","东冈忽摇白，织乌动层汉。"]},{"t":"玄堂八景为罗大参题 其五 西岸夜渔","f":"五言绝句","c":["寒潮拥西岸，渔艇互相呼。","答歌不知夜，皓月生菰蒲。"]},{"t":"玄堂八景为罗大参题 其七 村头翠竹","f":"五言绝句","c":["徙倚村头望，翠竹干云霄。","欲截凤凰管，凭谁叶虞韶。"]},{"t":"玄堂八景为罗大参题 其八 冈背青松","f":"五言绝句","c":["冈背何所有，历历青松树。","飒飒悲风来，恍恍神灵雨。"]},{"t":"题居竹轩","f":"五言绝句","c":["清阴满窗户，幽人澹无语。","翠影交龙蛇，白日惊风雨。"]},{"t":"题寒江小景","f":"五言绝句","c":["大地阳初复，寒江雪独深。","古崖空老树，渔艇忽拿音。"]},{"t":"寄易司训体乾","f":"五言绝句","c":["北雁飞南天，蒹葭霜月圆。","美人千里隔，深夜一灯悬。"]},{"t":"题倭扇画鼠","f":"五言绝句","c":["喜遇秦丞相，悲逢汉大夫。","不知当磔日，犹记太仓无。"]},{"t":"月出","f":"五言绝句","c":["月出群犬嗥，月入群犬静。","幽人耿不眠，翛然发孤咏。"]},{"t":"苦热","f":"五言绝句","c":["月淡万籁寂，更寒百蛩语。","道人据槁梧，挥扇自驱暑。"]},{"t":"游南华次章朴庵韵漫作禅语","f":"五言绝句","c":["南能无伎俩，妙境还谁履。","拈花裂虚空，莫问如何是。"]},{"t":"双井梧桐小景","f":"五言绝句","c":["凤鸟久不至，鲁叟悲道穷。","谁从双井上，手自种梧桐。"]},{"t":"题画鸠","f":"五言绝句","c":["大地龙正蛰，江山望禾黍。","枝间闻女声，苍林自风雨。"]},{"t":"题画练鹊","f":"五言绝句","c":["蓬蒿恣浼鹊，羽翼何翘翘。","何如舍之去，玉立当云霄。"]},{"t":"春日游郑氏庄","f":"古风","c":["寒食园林载酒，暖风帘幕啼莺。","高阁一回欹枕，小楼何处吹笙。"]},{"t":"渔父词","f":"古风","c":["迟日桃花浦上，轻风杨柳矶边。","鼓枻一声欸乃，中流遥见湘烟。"]},{"t":"谷雨燕坐偶成","f":"古风","c":["檐前当树阑珊，竹外鸣鸠往还。","隐几只销香篆，蔷薇开遍东山。"]},{"t":"潞河晓发","f":"古风","c":["楼前淼淼潮平，陌上萧萧马鸣。","孤月徘徊芳渚，五云缭绕神京。"]},{"t":"文渊阁登望嘉靖乙酉","f":"古风","c":["八柱高檠远汉，四檐长纳明霞。","渺渺碧山云树，重重紫禁烟花。"]},{"t":"凯歌词十首 其一","f":"七言绝句","c":["圣驾南巡江水清，凯旋惟恐露威灵。","虎贲夜散常山阵，龙气朝缠细柳营。"]},{"t":"凯歌词十首 其二","f":"七言绝句","c":["从官鹄立侍牙樯，中贵蝉联进玉觞。","百万貔貅齐喝采，载歌常武贺君王。"]},{"t":"凯歌词十首 其三","f":"七言绝句","c":["氛祲全销玉剑寒，鲸鲵京观筑如山。","风生虎帐刁斗静，日照龙江旌旆闲。"]},{"t":"凯歌词十首 其五","f":"七言绝句","c":["瓜步寒潮两坝通，居民今得醉春风。","红楼夜夜歌琼树，月堕河翻乐未终。"]},{"t":"凯歌词十首 其六","f":"七言绝句","c":["不杀天声本帝心，大江魑魅暗山林。","夏廷合铸神奸鼎，九牧遥闻已贡金。"]},{"t":"凯歌词十首 其九","f":"七言绝句","c":["郊圻草木沾天泽，淮海鱼龙识圣颜。","闻道赓歌临相第，唐虞今复在人间。"]},{"t":"凯歌词十首 其十","f":"七言绝句","c":["翠华询俗及阎闾，长有祥光散九衢。","后夜五云最深处，众星高护北辰居。"]},{"t":"征妇","f":"七言绝句","c":["织愁长倩锦为文，楼上花枝伴夕熏。","夜半朔鸿呼梦起，一天凉月泌香云。"]},{"t":"咏四皓","f":"七言绝句","c":["歌残鸿鹄汉宫秋，四老曾随鹤驾游。","采采琼芝谢车马，不知罗网是留侯。"]},{"t":"送卢仁三首 其一","f":"七言绝句","c":["河水东流无尽期，分携休唱莫愁词。","丈夫磊落要自许，兰室桂梁非所知。"]},{"t":"送卢仁三首 其二","f":"七言绝句","c":["金风剪剪不成霜，八骏行春及万方。","君去秦淮询盛事，满郊鱼鸟带恩光。"]},{"t":"送卢仁三首 其三","f":"七言绝句","c":["当年曾自大江回，映水芙蓉秋正开。","今日逢秋送归客，感时思旧不堪裁。"]},{"t":"怀罗浮四首别王用仪 其一","f":"七言绝句","c":["旅食燕台两变星，图南长拟蹑鹏翎。","无端夜雨惊心事，梦断罗浮未了青。"]},{"t":"怀罗浮四首别王用仪 其二","f":"七言绝句","c":["水帘洞口草生云，大石楼前花扑人。","唐世轩辕今我是，罗浮那有别家春。"]},{"t":"怀罗浮四首别王用仪 其三","f":"七言绝句","c":["伏波铜柱埋南纪，郭隗金台落北州。","看取长空没孤鸟，白云多处是罗浮。"]},{"t":"怀罗浮四首别王用仪 其四","f":"七言绝句","c":["罗浮秋色与天高，约略明朝买去舠。","万丈飞云携手上，共君眠石听松涛。"]},{"t":"闻雁二首 其一","f":"七言绝句","c":["云边久觉音书静，江上徒闻舟楫归。","嘹唳数声和梦破，凉蟾当户故辉辉。"]},{"t":"闻雁二首 其二","f":"七言绝句","c":["潇湘水碧莓苔青，白雁掠云时一声。","疏灯古壁照蓬鬓，江湖心事秋冥冥。"]},{"t":"题山水小景","f":"七言绝句","c":["九衢尘土袭簪缨，拟向乾坤借草亭。","恍惚罗浮画中见，乱松深处数峰青。"]},{"t":"秋霁","f":"七言绝句","c":["万壑长风吹日来，百年幽抱与云开。","倚阑舒啸一翘首，何处亭亭郭隗台。"]},{"t":"春日有怀家山二首 其一","f":"七言绝句","c":["花雨漫山杜宇愁，午窗归梦绕松楸。","入帘芳草应相笑，为报王孙已倦游。"]},{"t":"春日有怀家山二首 其二","f":"七言绝句","c":["语燕交飞舞蝶狂，杏花零落柳丝长。","天涯此日堪凄断，寒食郊原麦饭香。"]},{"t":"道中寓意二首 其一","f":"七言绝句","c":["燕赵相望一箭飞，东风吹老故山薇。","江南万里烟波阔，不似垂鞭信马归。"]},{"t":"道中寓意二首 其二","f":"七言绝句","c":["凤楼十二丽烟花，尽日凝妆望翠华。","开遍露桃多少恨，银环今夜落谁家。"]},{"t":"厓山怀古六首 其一","f":"七言绝句","c":["北风吹浪作龙楼，疑是乾坤正气浮。","闻说当年杨太后，间关挥泪渡中流。"]},{"t":"厓山怀古六首 其二","f":"七言绝句","c":["宋室逢厓事可知，燕台犹梦整天欹。","黄冠不到江南路，长使遗民叹黍离。"]},{"t":"厓山怀古六首 其三","f":"七言绝句","c":["云掩西湖王气销，厓山回首紫宸朝。","露松似浥朝衣泪，不逐青梧日夜凋。"]},{"t":"厓山怀古六首 其四","f":"七言绝句","c":["两厓形胜自天开，夺港犹思卷土来。","千古海陵遗迹在，云涛回望重堪哀。"]},{"t":"厓山怀古六首 其五","f":"七言绝句","c":["哀歌何处问荒亭，野烧随风讶陨星。","表暴尚遗徐礼部，断厓无语向人青。"]},{"t":"嘉会楼二首 其一","f":"七言绝句","c":["嘉会楼前谁主宾，老树挟风鸣向人。","坐槎仙客不可见，江水滔滔劳问津。"]},{"t":"嘉会楼二首 其二","f":"七言绝句","c":["江沙白白枫叶红，鳜鱼拨剌波摇空。","相逢渔父不相识，醉舞藤蓑明月中。"]},{"t":"访白沙宅四首 其一","f":"七言绝句","c":["堂前双柏走苍虬，苔自侵阶鹤自谋。","怪底诗翁贫到骨，野风萧瑟蔗塘秋。"]},{"t":"访白沙宅四首 其二","f":"七言绝句","c":["百年闻道属斯人，碧玉中藏太古春。","今我登楼望江水，青山红树四无邻。"]},{"t":"访白沙宅四首 其三","f":"七言绝句","c":["独上高楼开八窗，浮云飞尽月澄江。","人间亦有虬髯客，投老扶南自一邦。"]},{"t":"访白沙宅四首 其四","f":"七言绝句","c":["鹤骨峥嵘画幅开，执鞭何计起泉台。","翰林棨戟依然在，曾见先生马首来。"]},{"t":"梦中登故山作","f":"七言绝句","c":["清泉绿树抱山斜，万顷云天一亩家。","尽日掩关来自去，白云蒸雨湿松花。"]},{"t":"题黄鹤楼画二首 其一","f":"七言绝句","c":["黄鹤高飞览九州，楚江至今空此楼。","登楼浩歌一怀古，江木萧萧无那愁。"]},{"t":"题黄鹤楼画二首 其二","f":"七言绝句","c":["楚城斜日照洲渚，飞飞鸿雁鸣相将。","楼头客子笑无语，北梦南云尔许长。"]},{"t":"题便面小景次韵赠文徵仲","f":"七言绝句","c":["萧萧松径无尘埃，白云满地幽鸟来。","周南留滞未归去，旧日履綦空绿苔。"]},{"t":"舟中漫兴五首 其一","f":"七言绝句","c":["璧月团团玉镜台，照人怀抱霎时开。","无情最是芦包水，不共西南一路来。"]},{"t":"舟中漫兴五首 其二","f":"七言绝句","c":["胥江儿女多浣纱，道傍闻有莫愁家。","莫愁荡桨向何处，杨柳萧萧啼暮鸦。"]},{"t":"舟中漫兴五首 其三","f":"七言绝句","c":["宋朝栈道接烟霄，今日荒蹊没断桥。","花洞蛮歌喧逻口，竹房僧梵落山腰。"]},{"t":"舟中漫兴五首 其四","f":"七言绝句","c":["横石矶边秋水生，浈阳峡上鶗鴂鸣。","船头客子不能睡，对月长歌到五更。"]},{"t":"舟中漫兴五首 其五","f":"七言绝句","c":["河汉盈盈夜遽央，淡日欲出流云凉。","捲帘默坐看流水，风送一番松桂香。"]},{"t":"寿孙九峰尚书二首 其一","f":"七言绝句","c":["高咏琅函阅海筹，中台元不异丹丘。","年年六月蒲麟酒，长对来禽安石榴。"]},{"t":"寿孙九峰尚书二首 其二","f":"七言绝句","c":["锦席湘帘白日长，玉杯称寿未渠央。","调弦正奏缁衣曲，无限南风入座凉。"]},{"t":"戏赠杨中允二首 其一","f":"七言绝句","c":["海珠江头披绿蓑，春风秋雨共渔歌。","而今钓艇横江浦，鳣鲔年来柰尔何。"]},{"t":"戏赠杨中允二首 其二","f":"七言绝句","c":["梅花未发菜花香，坐到东风日渐长。","买菜供餐无那少，寻梅沽酒只消狂。"]},{"t":"采莲歌五首 其一","f":"七言绝句","c":["灵湘郁水粤王都，五层飞楼天下无。","江上行人莫回首，木绵花开啼鹧鸪。"]},{"t":"采莲歌五首 其二","f":"七言绝句","c":["江南江北机杼多，谁家儿女不停梭。","笑渠不似蜘蛛巧，能向虚空织网罗。"]},{"t":"采莲歌五首 其三","f":"七言绝句","c":["清远峡连黄木湾，采莲来往不为难。","青山亦有飞来日，何事萧郎未见还。"]},{"t":"采莲歌五首 其四","f":"七言绝句","c":["隔花相见两徘徊，荡桨低头笑不来。","双栖白鹭忽惊起，遥见浮萍一道开。"]},{"t":"采莲歌五首 其五","f":"七言绝句","c":["芭蕉叶卷久无舒，江口月明多鲤鱼。","要得鲤鱼寄消息，鲤鱼长在石岩居。"]},{"t":"寄钱太守索竹","f":"七言绝句","c":["采药归来即掩关，故人相馈一开颜。","已调滫瀡供皤发，更觅琅玕护碧山。"]},{"t":"汤文明惠并头葵花二株口占十绝 其一","f":"七言绝句","c":["缥蒂同心葵十寻，日华浮动朵云深。","江湖为尔怀霄汉，三月长安正绿阴。"]},{"t":"汤文明惠并头葵花二株口占十绝 其二","f":"七言绝句","c":["玉立亭亭见睟容，凤池相并集夔龙。","丹心只在彤云里，休道蓬山几万重。"]},{"t":"汤文明惠并头葵花二株口占十绝 其三","f":"七言绝句","c":["薰风未报清和月，淑气齐开并蒂花。","丹凤彩鸾天上路，一时飞动到山家。"]},{"t":"汤文明惠并头葵花二株口占十绝 其四","f":"七言绝句","c":["五夜彤庭绛节齐，火城如昼散乌栖。","十年不到芙蓉阙，坐对双红听曙鸡。"]},{"t":"汤文明惠并头葵花二株口占十绝 其五","f":"七言绝句","c":["翠蕤红脸自相依，不似桃花触处飞。","已共云霞分锦色，更烦雨露濯仙衣。"]},{"t":"汤文明惠并头葵花二株口占十绝 其六","f":"七言绝句","c":["春风秋月几离忧，谁似倾心结并头。","织女机丝何处所，长年辛苦会牵牛。"]},{"t":"汤文明惠并头葵花二株口占十绝 其七","f":"七言绝句","c":["此花不省人间有，喜自文明宅上来。","怪底潜龙惊起舞，夜来风雨动池台。"]},{"t":"汤文明惠并头葵花二株口占十绝 其八","f":"七言绝句","c":["覆雨翻云见汝难，晓来依旧立雕阑。","举头并向长安日，谁识芳心一寸丹。"]},{"t":"汤文明惠并头葵花二株口占十绝 其九","f":"七言绝句","c":["炎风时节集芳筵，同干骈花忆赏莲。","今日葵花更堪赏，暮春犹是艳阳天。"]},{"t":"汤文明惠并头葵花二株口占十绝 其十","f":"七言绝句","c":["独乐名园洛水滨，种葵长得殿馀春。","如今柳絮方零落，遥想南山尚有人。"]},{"t":"沙洲草堂四首为欧氏题 其一","f":"七言绝句","c":["海上结庐花满洲，春回沙际绿幽幽。","鸬鹚鸂鶒日来往，伴尔看花移小舟。"]},{"t":"沙洲草堂四首为欧氏题 其二","f":"七言绝句","c":["风帘冰簟对烟汀，浦口潮回日射星。","手种琅玕今长大，江村无数翠云屏。"]},{"t":"沙洲草堂四首为欧氏题 其三","f":"七言绝句","c":["鲈鳜初肥风满林。","海天寥廓绝拿音。","一声老鹤掠舟去，月出沙明蒲稗深。"]},{"t":"沙洲草堂四首为欧氏题 其四","f":"七言绝句","c":["朔风潇潇沙欲飞，翠凫黄犊寒相依。","古梅一夕倚檐发，吾爱吾庐春已归。"]},{"t":"雨中得吕氏读诗记答李三洲四首 其一","f":"七言绝句","c":["山雨潇潇花蕊红，卷帷呼酒倩谁同。","骖鸾一去传消息，多在青罗碧玉中。"]},{"t":"雨中得吕氏读诗记答李三洲四首 其二","f":"七言绝句","c":["谁传吕氏诗三百，苦忆云间陆士龙。","自别青冥今白发，镜湖何处见芙蓉。"]},{"t":"雨中得吕氏读诗记答李三洲四首 其三","f":"七言绝句","c":["白云飞处忆苍梧，梦入槐亭片月孤。","今日帛书才咫尺，杏花春雨卧江湖。"]},{"t":"雨中得吕氏读诗记答李三洲四首 其四","f":"七言绝句","c":["游丝千尺绊行尘，黄鸟嘤嘤似劝人。","尊酒当年同李白，融融风日洛桥春。"]},{"t":"仰云堂二首为林上舍志复 其一","f":"七言绝句","c":["小小茅斋傍樾开，壶山流影入书台。","翠涛摇动清风起，疑是云庄逸老来。"]},{"t":"仰云堂二首为林上舍志复 其二","f":"七言绝句","c":["霞明屏石晓荧荧，树引山光翠满城。","却忆过庭何处所，支颐翘首白云生。"]},{"t":"秋怀集古句四首 其一","f":"五言古诗","c":["伤禽恶弦惊，愁人知夜长。","辗转不能寐，秋风发微凉。","美人游不还，容好结中肠。","爱至望苦深，何况隔两乡。","愿飞安得翼，欲济川无梁。","丛雁鸣云霄，渥露沾我裳。","佳期怅何许，仰见明月光。"]},{"t":"秋怀集古句四首 其二","f":"五言古诗","c":["仰见明月光，星河曙耿耿。","迢迢牵牛星，荡荡空中景。","织女处其东，复与云路永。","无情尚有归，令人发深省。","何以慰我愁，挥杯劝孤影。"]},{"t":"秋怀集古句四首 其三","f":"五言古诗","c":["挥杯劝孤影，孤影中自恻。","浊酒且自陶，为君长叹息。","青苔依空墙，芳尘凝瑶席。","感叹何时平，含情弄柔瑟。","遗响飞青天，青天何历历。","云霞妆夕霏，回风吹四壁。","君怀良不开，冰玉徒贞白。"]},{"t":"秋怀集古句四首 其四","f":"五言古诗","c":["冰玉徒贞白，江湖迥且深。","秋菊有佳色，寒蝉无馀音。","感物忧不歇，隔我浮与沉。","人生有离合，孰为劳寸心。","濯足万里流，长啸高山岑。","大哉乾坤内，视古犹视今。"]},{"t":"集杜句题彩凤云龙卷送方公子行","f":"古风","c":["君不见陇山萧索秋云高，山巅朱凤鸣嗷嗷。","侧身长顾求其曹，万古云霄一羽毛。","君不见潇湘洞庭虚映空，中有云气从飞龙。","天地黤惨忽异色，万斛之舟行若风。","英雄有时亦如此，揽环结佩相终始。","凤臆龙鬐未易识，青眼高歌望吾子。"]},{"t":"草堂别友人集杜句","f":"七言律诗","c":["倚江楠树草堂前，忽漫相逢是别筵。","纵酒欲谋良夜醉，将诗不必万人传。","朝廷衮职谁能补，乡里衣冠不乏贤。","此别应须各弩力，浊醪粗饭任吾年。"]},{"t":"南雄返棹集陶句二首 其一","f":"五言古诗","c":["行行循归路，靡靡秋已夕。","遥遥望白云，露凄暄风息。","一形似有制，万花相寻绎。","江山岂不险，自古叹行役。","息驾归閒居，梅柳夹门植。","曲肱岂伤冲，披褐欣自得。","时还读我书，弱子戏我侧。","提壶接宾侣，抗言谈在昔。","林园无俗情，云鹤有奇翼。","孰敢慕甘肥，素襟不可易。"]},{"t":"南雄返棹集陶句二首 其二","f":"五言古诗","c":["形迹滞江山，僶俛四十年。","天地长不没，聊且凭化迁。","荣华诚足贵，于我若浮烟。","即日弃其官，守拙归园田。","白日掩荆扉，药石有馀闲。","啸傲东轩下，徘徊丘垄间。","青松夹路生，纷纷飞鸟还。","人道每如兹，此行谁使然。","世俗久相欺，任真无所先。","何必升华嵩，一盼周九天。"]},{"t":"桂林雨中望诸葛亭有感集杜句","f":"七言律诗","c":["云水长和岛屿青，江中风浪雨冥冥。","霜凋碧树作锦树，色过棕亭入草亭。","诸葛大名垂宇宙，元戎小队出郊坰。","卧龙跃马俱黄土，极目秋天虚翠屏。"]},{"t":"草堂夜坐有怀梁南皋用韵集杜二首 其一","f":"七言律诗","c":["琴瑟几杖柴门幽，请公一来开我愁。","夜如何其初促膝，岁云莫矣增离忧。","飘零已是沧浪客，角壮翻同麋鹿游。","走觅南邻爱酒伴，江花未尽会江楼。"]},{"t":"草堂夜坐有怀梁南皋用韵集杜二首 其二","f":"七言律诗","c":["东流之外西日微，羲和叠送将安归。","江中淘河嚇飞燕，天上浮云如白衣。","即事非今亦非古，暂时相赏莫相违。","因知贫病人须弃，独立苍茫自咏诗。"]},{"t":"江上寄山阴周给事","f":"七言绝句","c":["万里风烟接素秋，浴凫飞鹭晚悠悠。","更为后会知何地，忆向山阴上小舟。"]},{"t":"草堂招汤处士民悦饮集杜句","f":"古风","c":["君不见韝上鹰，万里寒江只一日。","焉能作堂上燕，可怜处处巢居室。","大夫垂名动万年，会是排风有毛质。","天意冲寒欲放梅，江上徒逢袁绍杯。","酒阑击剑蛟龙吼，山根鳣鲔随云雷。","男儿生无所成头皓白，我能拔尔仰塞磊落之奇才。","速宜相就饮一斗，丝管啁啾空翠来，如何不饮令心哀。"]},{"t":"东流江水篇","f":"古风","c":["东流江水西飞燕，只愿无事长相见。","咫尺应须论万里，可惜刻漏随更箭。","忆献三赋蓬莱宫，声价欻然来向东。","喜得与子长夜语，意匠惨澹经营中。","年年至日长为客，目脂面药随恩泽。","此时与子空归来，鸿飞冥冥日月白。","孤城西北起高楼，伐木丁丁山更幽。","青鞋布袜从此始，长歌短咏还相酬。","钟鼎山林各天性，后来况接才华盛。","青眼高歌望吾子，苍苔浊酒林中静。","冬至阳生春又来，亦知穷愁安在哉。","江上被花恼不彻，安得健步移远梅。","梅花欲开不自觉，细推物理须行乐。","玉垒浮云变古今，瑶台侍臣已冥寞。","君不见周南太史公，凡今谁是出群雄。","词源倒流三峡水，胡为见羁虞罗中。","君不见西蜀杜陵老，多才依旧成潦倒。","且尽清尊恋物华，不知明月为谁好。","高视乾坤又可愁，尊前还有锦缠头。","缘云清切歌声上，多暇日陪骢马游。","紫衣将炙绯衣走，饔人受鱼校人手。","忆昨邀欢乐更无，此曲秖应天上有。","箫鼓哀吟感鬼神，回风飒飒吹沙尘。","合欢却笑千年事，白水青山空复春。"]},{"t":"集杜句赠右溪伦子","f":"七言律诗","c":["晚来幽独恐伤神，相送柴门月色新。","卜筑应同蒋诩径，名家莫出杜陵人。","侍臣缓步归青琐，鸣玉朝来散紫宸。","南极一星朝北斗，勿云江汉有垂纶。"]},{"t":"又赠青萝王子与伦子同行","f":"七言律诗","c":["渡头翠柳艳明眉，仙侣同舟晚更移。","钟鼎山林各天性，风流儒雅亦吾师。","独当省署开文苑，会送夔龙集凤池。","离别不堪无限意，呼儿觅纸一题诗。"]},{"t":"伦子席上赏菊观戏","f":"七言律诗","c":["多暇日陪骢马游，尊前还有锦缠头。","残花烂漫开何益，妙舞逶迤夜未休。","遂有冯夷来击鼓，焉知李广不封侯。","合欢却笑千年事，许坐层轩数散愁。"]},{"t":"与李子同赋观奕","f":"七言律诗","c":["清簟疏帘看奕棋，百年世事不胜悲。","惟将迟暮供多病，不及前贤更勿疑。","庾信罗含俱有宅，李陵苏武是吾师。","名重万古知何用，独立苍茫自咏诗。"]},{"t":"出郭课野老为园","f":"七言律诗","c":["野老墙低还是家，为园须学邵平瓜。","已知出郭少尘事，且尽清尊恋物华。","江上小堂巢翡翠，山楼粉堞隐悲笳。","不嫌野外无供给，来岁还舒满眼花。"]},{"t":"铙歌鼓吹曲二十二首 艾如张一章十三句 其三","f":"古风","c":["艾如张，罗毕以罗。","雀飞避旃将谁何。","雀以飞，罗罹之。","钲镯何以为，嗟将问谁。","又何以为，嗟此者谁。","卿道不，鼓绝声。","白云上天，日月其明。"]},{"t":"江南弄七首 其一 江南弄","f":"古风","c":["桃花婀娜随轻风。","芳颜照灼舒春红。","垂手攘袖舞未终。","舞未终，歌羽衣。","行云驻，梁尘飞。"]},{"t":"江南弄七首 其二 龙笛曲","f":"古风","c":["朱唇掩抑呈妙音。","绿水澹荡闻龙吟。","长矕远引摇春心。","摇春心，破春寒。","动光风，汎崇兰。"]},{"t":"江南弄七首 其三 采莲曲","f":"古风","c":["青娥翠楫行彩舟。","莲花未绽含娇羞。","颦眉聚黛扬清讴。","扬清讴，度修渚。","炫明妆，澹容与。"]},{"t":"江南弄七首 其四 凤笙曲","f":"古风","c":["腾鸾起凤吹参差。","幽簧动翮纤指移。","珠垂玉振为君施。","为君施，间歌作。","拊秦筝，奏别鹤。"]},{"t":"江南弄七首 其五 采菱曲","f":"古风","c":["钿花匐叶浮香雾。","兰桨桂楫摇江步。","采菱声合流云度。","流云度，和风吹。","振罗袂，行相随。"]},{"t":"江南弄七首 其六 游女曲","f":"古风","c":["联娟翠翰映玉光。","縠衣绣袿嬉江阳。","淩波解佩游龙翔。","游龙翔，闻芗泽。","发浩倡，聚行客。"]},{"t":"江南弄七首 其七 朝云曲","f":"古风","c":["朝云飘忽巫山台。","扶光照耀群阴开。","瑶姬屏伏阳春来。","阳春来，散郁滞。","祝君王，千万岁。"]},{"t":"飞龙引阅中秘书作","f":"五言古诗","c":["飞龙开治朝，承宇何翘翘。","轻烟冒朱阁，玉除依庆霄。","基命会文执，提剑驱天骄。","燕台定吴鼎，奎光明斗杓。","羽陵启方策，鲁壁闻英韶。","遗编溢金匮，稽古师帝尧。","渊源浚翠川，腾跃昂碧寥。","缥缃今寂蔑，神悟畴与昭。","白驹乐场藿，伊人正逍遥。"]},{"t":"宫桑闻北郊亲蚕赋 其一","f":"古风","c":["有菀宫桑，遵彼郊场。","其叶扬扬，仓庚载鸣。","扤扤条肄，乃集乃翔。"]},{"t":"宫桑闻北郊亲蚕赋 其二","f":"古风","c":["有菀宫桑，遵彼郊曲。","其叶维沃，以筐以簇。","以躬杼柚，用成我服。"]},{"t":"宫桑闻北郊亲蚕赋 其三","f":"古风","c":["毋曰我私，黼裳卷衣。","爰响爰禋，既襄既宜。","父母攸诒，云胡勿思。"]},{"t":"梧凤朝阳三章","f":"古风","c":["维梧有凤，鸣于朝阳。","言翔于天，其音锵锵。","明哲君子，御此南疆。","维皇眷之，晋锡孔昌。","维梧有凤，朝阳其鸣。","其音嗈嗈，言翔于京。","明哲君子，戎功告成。","逖此南夷，皇心则宁。","梧桐萋萋，朝阳杲杲。","凤鸣高冈，其音载好。","明哲君子，身维保之。","懿兹戎功，皇维焘之。"]},{"t":"平潮夷雅十一章","f":"古风","c":["于赫皇命，征彼潮夷。","显允张公，秉钺孔宜。","黄旗旆旆，爰董我师。","有鞑有狼，如虎如螭。","维公率止，既类既祃。","元龟告祥，乃宜干社。","四牡锽锽，梧台之下。","金盾雕戈，光鉴于野。","出次于广，乃涉于潮。","虎臣洸洸，螭队翘翘。","七萃云连，苞有三饶。","岂敢欢嚣，我皇威孔昭。","元戎启行，四围其薮。","彼昏不知，如鱼在罶。","蠢尔逆琏，悔为乱首。","喘伏于莽，喙其群丑。","我师翼翼，乘其石城。","石城重重，既骞既崩。","深入其寨，克奋克登。","按其徂奔，罔敢有启扃。","雷电发发，威燀旁达。","于程于埔，震叠莫我遏。","彼蹙且頞，癙忧如暍。","如蘖如蘖，逢我薄伐。","我武既扬，神机允臧。","消其峰雪，日出之光。","琏既徽纆，群爝胥亡。","潮人咸喜，时雨其滂。","旻穹穆穆，哀氓之无禄。","既雨既洽，潮田既足。","蠲其漂血，殖我百谷。","扶挈旄倪，向用天福。","彼海有鳄，噬人于牙。","自剪且歼，俾我有室家。","南溟汪汪，服岭嵯峨。","四远来归，式讴式歌。","休兵燕喜，俎豆维旅。","箪食壶浆，祁祁士女。","鼚鼚其鼓，轩轩其舞。","萧勺群慝，万年无有侮。","皇锡张公，犀鞶豸綖。","駉駉訾黄，绥章绮軿。","公拜稽首，神谋自天。","公拜稽首，圣皇万年。"]},{"t":"翩翩者鹤贺吴子重闱荣寿三首 其一","f":"五言古诗","c":["亭亭州山阴，松竹何青青。","上有九苞羽，下有千岁苓。","栖息东王公，照耀南极星。","鹍弦沸瑶席，绣幄开云屏。","奕叶惠文冠，执法天子庭。","佩结苍精龙，金绯明玉映。","欢声彻霄汉，恩波告冥冥。"]},{"t":"翩翩者鹤贺吴子重闱荣寿三首 其二","f":"七言古诗","c":["宝日皛皛宣重光。","玄冬丹峤瑶草芳。","笙鸣瑟作广乐张。","清歌妙舞回鸣珰。","豸冠鹤发庞眉苍。","振缨峨弁纷满堂。","盈阶玉树侑王觞。","瑞枣如瓜笑且尝。","万岁千秋长乐康。"]},{"t":"翩翩者鹤贺吴子重闱荣寿三首 其三","f":"古风","c":["翩翩者鹤，鸣于菀林。","其子和之，载好其音。","念我重华，龙光是临。","天子万寿，言慰我心。","有鹤翩翩，鸣于菀柳。","其子从之，亦翯其首。","念我重华，锡此黄耇。","言慰我心，天子万寿。"]},{"t":"双节旌门诗","f":"古风","c":["明昭我皇，敬跻圣神。","允文允武，无竞惟人。","拔奇夷难，迈德振民。","丕展彝叙，上明下亲。","懿此双节，伯姒叔娣。","姒固称贤，娣以子贵。","教子伊何，敦诗说礼。","出入乌台，表表伟伟。","猗惟萧公，进思尽忠。","巡彼粤西，有奋元戎。","定姜卜征，馘夫之雄。","百战奇法，奏此肤功。","复巡东粤，崇我文教。","表章先儒，是式是效。","孟母励学，永言克孝。","绍衣德言，犹织之懋。","惟皇允武，公则诘之。","匪母之教，征则匪宜。","惟皇允文，公则崇之。","匪母之教，又孰可师。","文武彝德，既曰母教。","贞节昭宣，无德不报。","皇锡德音，旌门有诰。","为世作程，于赫斯耀。"]},{"t":"招颂补遗九首 其一 治洪水","f":"楚辞体","c":["洪水滔天，浩浩方割。","怀山襄陵，帝咨四岳。","禹作司空，惟荒度土功。","暨益秉烈火，山泽乃通。","有鸟高飞，鸣且哺矣。","呱呱者子，不皇顾矣。","龙门辟兮，播为九河。","崇禹之功兮，万世是何。"]},{"t":"招颂补遗九首 其二 刊山木","f":"古风","c":["下民昏垫，哀此无告。","禹乘四载，随山刊木。","吕梁太岳，底柱析城。","于恒于华，于荆于衡。","乃畋于山，乃牧于谷。","乃渔乃佃，于渊于陆。","我胼我胝，我思阻饥。","奏庶鲜食，惟下民之宜。"]},{"t":"招颂补遗九首 其三 浚畎浍","f":"古风","c":["禹决九川，以距四海。","距川伊何，浚兹畎浍。","肇河积石，江岷汉嶓。","济淮入海，渭洛惟河。","其鱼发发，孔庶且有。","既汕于梁，亦获于笱。","播奏庶艰，登彼丘陵。","懋迁有无，化居是营。"]},{"t":"招颂补遗九首 其四 立烝民","f":"古风","c":["生生有开，烝民乃立。","后稷播嘉种，下土斯啬。","白壤黑坟，赤埴青黎。","亦有黄垆，广斥涂泥。","耕彼南亩，离离蕃茂。","何铫何耜，载耨稂莠。","乃迎猫虎，奏我笙庸。","以乐我先啬，惟禹斯崇。"]},{"t":"招颂补遗九首 其五 锡玄圭","f":"古风","c":["禹锡玄圭，告厥成功。","万邦作乂，四海会同。","庶土交正，底慎财赋。","厥贡厥篚，厥包载路。","金石盐絺，丝枲织皮。","羽毛齿革，纳锡元龟。","球琳琅玕，玄纁玑组。","弼成五服，以修六府。"]},{"t":"招颂补遗九首 其六 建皇极","f":"楚辞体","c":["建皇之极，六府孔修。","厥动惟时，昭受天休。","帝迪厥德，光天之下。","海隅苍生，永得我所。","凡今黎献，共惟帝臣。","百工俊乂，乃歌卿云。","卿云烂兮，纠缦缦兮。","日月光华，旦复旦兮。"]},{"t":"招颂补遗九首 其七 明明一终","f":"古风","c":["明明尚天，烂然星陈。","日月光华，弘于一人。","日月有常，星辰有行。","四时顺经，万姓允诚。","于予论乐，配天之灵。","迁于贤圣，莫不咸听。","鼚乎鼓之，轩乎舞之。","精华以竭，褰裳去之。"]},{"t":"招颂补遗九首 其八 明明二终","f":"古风","c":["明明帝命，八风修通。","地平天成，万世之功。","天下攘攘，为利斯往。","诏尔和钧，与而嘉量。","天下熙熙，为利斯来。","同维审度，以莫不宜。","蟠龙贲信，蛟鱼踊跃。","草木萌生，蜚征咸若。"]},{"t":"招颂补遗九首 其九 明明三终","f":"楚辞体","c":["明明天常，永保尔极。","不识不知，顺帝之则。","日出而作，日入而息。","耕田凿井，以饮以食。","帝何力哉，亶惟不康。","垂衣鼓琴，轸我困穷。","南风薰兮，解民之愠兮。","南风时兮，阜民之财兮。"]},{"t":"梦中朔风诗三章","f":"古风","c":["朔风萧萧，庭绿葳蕤。","百鸟拚飞，栖宿相随。","君子亲民，安宅在兹。","彼蠢不譓，扰敚何为。","萧萧朔风，旖旖庭绿。","百鸟飞拚，于焉栖宿。","君子亲民，为邦建福。","彼蠢有知，归于寿谷。","朔风静矣，庭绿盛矣。","百鸟和鸣，胥自庆矣。","君子亲民，实邦之桢。","彼蠢来归，云胡不宁。"]},{"t":"游南华同章朴庵提学作","f":"五言古诗","c":["维舟访宝林，策蹇登翠微。","晴坡无鸟声，云霞随客衣。","寒威起层碧，枫叶随意飞。","山僧见行尘，竹房开半扉。","南能本无物，金碧何荣辉。","风幡忽高下，泠然启尘机。","云舂杂疏磬，岚影青四围。","眷兹川原幽，冥心澹忘归。","逃禅非我事，且与丘樊违。","振缨一鸣辔，皓月生苔矶。"]},{"t":"初宿大兴隆寺禅幌偶作","f":"五言古诗","c":["丰草浥朝露，寒鸦栖夕曛。","市醪解旅恨，鞠歌念离群。","缅怀南山豹，宿雾成炳文。","谁知北冥上，鹏翼垂天云。","隐显谅有时，世事徒殷勤。","嘿嘿对祇树，疏钟坐来闻。"]},{"t":"江淮大水有感","f":"古风","c":["中兴启昌祚，大横兆庚庚。","洚水儆尧心，匪眚惟休祯。","眷彼江淮间，川潢浩纵横。","初闻穿魏瓠，苞稂忾周□。","渐不辨牛马，潋滟当檐楹。","如嗃如振突，如沸仍如倾。","如立亦如斗，倏如扬甲兵。","如马脱鞿絷，驰逐车驞駍。","又如庆山起，干霄屹峥嵘。","拔如五丁力，虩如百里霆。","天地久黯惨，日月韬光晶。","浸淫鳀壑满，澹荡鹊岸平。","西流控巴蜀，东汜迩蓬瀛。","九派杳不分，三洲讵能名。","鼋鼍傍户出，鹳鹄当阶鸣。","夜阑象纬入，琐碎浮金琼。","沙篆漭已涤，石崖洄乍呈。","折苇不可杭，乘蹻安能征。","龙负逐飙逝，鲛织蒸霞明。","天吴起为舞，阳侯遁其形。","冰夷倚浪睨，江妃捐佩迎。","琴高杂鰋鲤，珠蟞乘蛷?。","海童与渊客，招邀如弟兄。","辏烟愿都市，构云望高坰。","籁涛迅飞镝，镜光寒发硎。","淩深候鼓楫，涉浅资浮罂。","露宿伊可畏，风期谁复评。","未睹纤萝动，欲随飞旆轻。","裹足避霾曀，褰裳越?泞。","触隒各趾折，集岸犹心惊。","菜色遍原野，楮词达虞衡。","逾时事渔钓，曷日躬岩耕。","禹排岂可望，鲧堙空复情。","此邦无息壤，祈灵费沉牲。","精诚在黄屋，宵旰缘苍生。","坤区自兹奠，坎德不复盈。","三光播炎景，千门流颂声。","洋洋适游鲋，渺渺潜长鲸。","坐令南国纪，山川靡不宁。","临流歌水调，为君叶韶英。"]},{"t":"罗浮朱明洞缓声歌三首 其一","f":"五言古诗","c":["朗朗朱光晶，肃肃朱火兵。","朱旗化岞崿，蔟叠环朱明。","耀真肇丹台，飞云概紫清。","于景守劫仞，罡风运流铃。","左摄白元尊，右襟交无英。","同归太信根，桃康保黄宁。"]},{"t":"罗浮朱明洞缓声歌三首 其二","f":"五言古诗","c":["晓发黄龙洞，夜宿朱明天。","朱明何高高，大罗相连延。","元始命天真，授我云篆篇。","九光驻飞鞅，三华返胎辕。","上窥无复色，下际宁有渊。","永言保冲虚，冥心同太玄。"]},{"t":"罗浮朱明洞缓声歌三首 其三","f":"五言古诗","c":["晨阳避玄仞，琅霄敞飙台。","濯濯鹤上仙，缤翻乘雨来。","水帘发红泉，金沙灿璚瑰。","琳和殷珠树，扶光入东隈。","鼓轮漱胎息，混合神风回。","元命归太初，千椿尚婴孩。"]},{"t":"梅花村前遇畲人荐酒","f":"五言律诗","c":["落落梅花村，前有烧畲客。","殷勤芳树下，酌以缥玉白。","杯盘出古窑，鸡豕自山泽。","陶然巾车去，和风荡长陌。"]},{"t":"题石川书赠张子","f":"五言古诗","c":["磐石何岩岩，流泉何弥弥。","石以励吾志，泉以洗吾耳。","渌净涵青天，秀色亘千里。","菰蒲断尘境，花竹粲成绮。","有时天水交，触石片云起。","彷佛御炉烟，絪缊映丹扆。","因之怀金门，忠贞讵能已。","秉志傥不移，润泽从兹始。"]},{"t":"浣俗轩五首为孙德谦 其二","f":"五言律诗","c":["闭关求我志，出即事廊庙。","文案虽纠缠，音徽自高妙。","玄珠翳绀渊，晶荧有馀耀。","朝市藏大隐，振缨可同调。"]},{"t":"浣俗轩五首为孙德谦 其三","f":"五言律诗","c":["同调子鸣鹤，异臭谁断金。","皎皎嘉石阳，肃肃棘树阴。","循除听流水，钩帘见鸣禽。","啸傲层轩内，聊用洗我心。"]},{"t":"浣俗轩五首为孙德谦 其四","f":"五言律诗","c":["洗心实稽古，攫名非俟命。","利本竞锥刀，色乃让千乘。","义欲在丹书，圣狂有明镜。","懿维皭不滓，芙蕖秉贞性。"]},{"t":"浣俗轩五首为孙德谦 其五","f":"五言律诗","c":["贞性本自敦，乃为薄俗移。","驱车出门去，扰扰多尘缁。","濯足蓬瀛流，晞发扶木枝。","俗累自兹浣，天衢以为期。"]},{"t":"赠华太守二首 其一","f":"五言古诗","c":["有鸟西南飞，拚拚栖桂林。","文彩一何绮，随风遗好音。","天地多网罗，山川嗟阻深。","期而协韶濩，谁言终陆沉。","陫侧念兹去，为奏龙唇琴。"]},{"t":"赠华太守二首 其二","f":"五言古诗","c":["商风鸣素节，鶗鴂凋百草。","兰芷竞芬芳，经霜逾鲜好。","孤根谅长在，岁寒可相保。","朝发苍梧野，夕至鉴湖道。","临岐愿有赠，守贞以为宝。"]},{"t":"赠邵端峰方伯之山东六首 其一","f":"五言古诗","c":["百粤殊气候，三伏竞炎凉。","幽居慎服食，况乃道路长。","门有车马客，驾言发我乡。","旬宣指邹鲁，邹鲁民所望。","思为骖与靷，复在水一方。","仰睇云中鹄，何时遂翱翔。"]},{"t":"赠邵端峰方伯之山东六首 其二","f":"五言古诗","c":["端峰倚天日，氛氲罗秀色。","肤寸蒸为云，触彼泰山石。","龙惟合变化，谁不愿甘泽。","久谢承明庐，居然服逢掖。","行行二十载，岂惟六月息。","古调终有谐，今见垂天翼。"]},{"t":"赠邵端峰方伯之山东六首 其三","f":"五言古诗","c":["迢迢泰山阿，郁郁古尼丘。","明明阙里祀，滔滔洙泗流。","凤德衰矣夫，谁其为东周。","衮章俨如在，俎豆万春秋。","君子孝岂匮，欲言惧招尤。","建藩自兹往，我心正悠悠。"]},{"t":"赠邵端峰方伯之山东六首 其四","f":"五言古诗","c":["越女颜如花，靓妆趋若耶。","采莲心亦苦，冶容人所誇。","君今秉幽贞，高阁淩飞霞。","缡縰翠羽帐，旖旎彤云车。","可望不可见，温温玉无瑕。","愿言托君怀，倘类蓬生麻。"]},{"t":"赠邵端峰方伯之山东六首 其五","f":"五言古诗","c":["海榴发岩楹，葳蕤含景鲜。","茭萼晞阳光，亭午丹欲然。","萧瑟岁寒节，缅怀中兴年。","雍齿反婴僇，丁公顾能全。","如彼荧荧者，乃矜一朝妍。","缄书持赠君，何由达灵荃。"]},{"t":"赠邵端峰方伯之山东六首 其六","f":"五言古诗","c":["遍性寡夙谐，幽痗每蕲豫。","偶逃朱绂困，遂洽沧洲趣。","公馀一相见，所欣襜帷驻。","退耕愧不任，内省恒多误。","感君砭我愚，胡然自兹去。","独坐泛瑶瑟，知音信难遇。"]},{"t":"崇德楼怀古八首为彭城马子津赋 其一","f":"五言律诗","c":["苍山倚天东，秀色亘千里。","缅怀山中人，羽翼赤龙子。","织鸟翔太霄，翩翩彩云起。","瞻云息机事，林卧观无始。"]},{"t":"崇德楼怀古八首为彭城马子津赋 其二","f":"五言律诗","c":["明月出西山，金波何穆穆。","徘徊入窗户，清辉如可掬。","楚王不复见，掩映见云木。","设醴待高贤，谁哉继芳躅。"]},{"t":"崇德楼怀古八首为彭城马子津赋 其三","f":"五言律诗","c":["南山当我前，翩跹如凤凰。","和风日夕至，草木皆文章。","仿佛九苞羽，来为王者祥。","荡胸俱凉翠，众鸟空榆枋。"]},{"t":"崇德楼怀古八首为彭城马子津赋 其四","f":"五言律诗","c":["宝瓶出楼阴，亭亭干斗杓。","璿衡齐七政，璀灿明九霄。","轸我匡时心，谁令元气调。","酒浆不可挹，大东有遗谣。"]}]};